window.ASPEKTE_B2_EXERCISES={"version":"0.5.0","activities":[{"id":"b2-ex-001","solutionId":"b2-sol-001","chapter":1,"module":"Modul 1 · Neue Heimat","moduleIndex":1,"label":"A2A","title":"Neue Heimat","page":13,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Beruf                            neuer Wohnort                   Grund für den Umzug\n       Job kündigen; Arbeit suchen;     Australien; kannte              aus Liebe; Liebe zu\n       Arbeitserlaubnis bekommen;       niemanden; Heimweh;             Australien und David\n       Stelle als Grafikerin in einer   Bekannter hilft (später) bei\n       Agentur                          der Wohnungssuche; Wetter,\n                                        Meer, Landschaft sind super;\n                                        Leben ist angenehm,\n                                        Menschen entspannter;\n                                        Probleme mit der Sprache","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-002","solutionId":"b2-sol-002","chapter":1,"module":"Modul 1 · Neue Heimat","moduleIndex":1,"label":"A2B","title":"Neue Heimat","page":13,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"positiv: gutes Gefühl, es zu schaffen, sich in einem neuen Land einzuleben; erweitert den\n               Horizont; man lernt Kultur eines anderen Landes kennen und dadurch erfährt man viel\n               über sich selbst und die eigene Kultur; hat Sprache gut gelernt; Leben ist angenehm:\n               Meer, Wetter und Landschaft super, Leben lockerer, hat schnell Freunde gefunden\n      negativ: Kündigung des alten Jobs und Abschied von Freunden und Familie ist ihr\n               schwergefallen; Neuanfang ist schwierig: keine Kontakte, keine Arbeit,\n               Arbeitserlaubnis war nicht leicht zu bekommen; hatte großes Heimweh; Beziehung zu\n               ihrem Freund zu Ende; Probleme mit der Sprache; Entfernung zu Familie und\n               Freunden in der Heimat; wird sich nie so in der Fremdsprache ausdrücken können wie\n               auf Deutsch","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-003","solutionId":"b2-sol-003","chapter":1,"module":"Modul 1 · Neue Heimat","moduleIndex":1,"label":"A4A","title":"Neue Heimat","page":14,"kind":"open","tags":["Practice","Grammar","Writing"],"modelAnswer":"Mittelfeld\n       Ich   bin      letztes      aus Liebe    ziemlich     nach Australien               ausgewandert.\n                      Jahr                      spontan\n       1    2         temporal     kausal       modal        lokal                         Ende\n                      (Wann?)      (Warum?)     (Wie?)       (Wo?/Wohin?/Woher?)\n      Merkformel: te – ka – mo – lo","fields":[],"film":false,"y0":320,"y1":980},{"id":"b2-ex-004","solutionId":"b2-sol-004","chapter":1,"module":"Modul 1 · Neue Heimat","moduleIndex":1,"label":"A4B","title":"Neue Heimat","page":14,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Wenn es Angaben und Ergänzungen gibt, steht die Dativergänzung meistens vor der\n      temporalen Angabe. Die Akkusativergänzung steht nach den temporalen, kausalen und\n      modalen Angaben und vor oder nach der lokalen Angabe.","fields":[],"film":false,"y0":320,"y1":980},{"id":"b2-ex-005","solutionId":"b2-sol-005","chapter":1,"module":"Modul 1 · Neue Heimat","moduleIndex":1,"label":"A4C","title":"Neue Heimat","page":14,"kind":"fill","tags":["Practice","Grammar"],"modelAnswer":"Präpositionalergänzungen stehen normalerweise am Ende des Mittelfeldes.","fields":[{"label":"Answer","answers":["Präpositionalergänzungen stehen normalerweise am Ende des Mittelfeldes."]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-006","solutionId":"b2-sol-006","chapter":1,"module":"Modul 2 · Ein Land, viele Sprachen","moduleIndex":2,"label":"A1C","title":"Ein Land, viele Sprachen","page":15,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"• Deutsch, Französisch, Italienisch und Rätoromanisch\n      • Sie ist eine Eidgenossenschaft: ein Zusammenschluss von 26 Kantonen, die politisch\n      selbstständig sind, ein eigenes Parlament haben und in denen von Anfang an auch\n      unterschiedliche Sprachen gesprochen wurden.\n      • Mögliche Lösung: Muttersprache: die Sprache, die wir von den Eltern lernen, sie ist Heimat\n      und Identität / Landessprache: die Sprache, die offiziell als Sprache eines Landes bezeichnet\n      und auch für die Verwaltung verwendet wird.","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-007","solutionId":"b2-sol-007","chapter":1,"module":"Modul 2 · Ein Land, viele Sprachen","moduleIndex":2,"label":"A2A","title":"Ein Land, viele Sprachen","page":15,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Beispiele, wo Informationen mehrsprachig angeführt sein müssen:\n      Durchsagen in Zug/U-Bahn/Bus, auf Produktverpackungen, bei Firmenkonferenzen, bei Flyern\n      und anderer Werbung, in Fernsehen und Radio, auf Homepages, auf Straßenschildern, …;\n      Gesetzestexte, Behördeninformationen usw. müssen mehrsprachig zugänglich sein; im\n      Schulunterricht, in der Ausbildung und beim Studium müssen die verschiedenen Sprachen\n      berücksichtigt werden.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-008","solutionId":"b2-sol-008","chapter":1,"module":"Modul 2 · Ein Land, viele Sprachen","moduleIndex":2,"label":"A2B","title":"Ein Land, viele Sprachen","page":15,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"Mögliche Lösung:\n      Zeile 42–47: Muttersprache in der Schweiz\n      Zeile 47–56: Schule und Sprachen\n      Zeile 56–71: Sprache und Offizielles\n      Zeile 71–Ende: Sprache und Geschäftsbeziehungen","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-009","solutionId":"b2-sol-009","chapter":1,"module":"Modul 3 · Missverständliches","moduleIndex":3,"label":"A1A","title":"Missverständliches","page":17,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      Beispiel 1: im Zug, Reise von Klagenfurt nach Rom, Mann allein im Abteil, Frau kommt hinzu,\n      sucht offensichtlich einen Platz und fragt etwas. Er antwortet „ja“ und sie geht. –\n      Missverständnis: Er hat die Frage nicht verstanden und dachte, sie fragt, wie in Deutschland\n      üblich: „Ist der Platz frei?“; in Italien fragt man aber: „Ist der Platz besetzt?“\n      Beispiel 2: Frau, Schüleraustausch in Japan, zwei Wochen bei einer Familie, zeigen Garten,\n      sie läuft direkt darin herum, alle sehen sie komisch an. – Missverständnis: Garten ist zum\n      Anschauen und nicht zum darin Herumgehen da.\n      Beispiel 3: Frau, Türkei im Urlaub, Busfahrt, Frage an Busfahrer, ob der Bus der richtige ist,\n      keine Antwort vom Busfahrer, hebt nur die Augenbrauen. – Missverständnis: Augenbrauen\n      heben ist nicht bedeutungslos, sondern bedeutet „nein“.","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-010","solutionId":"b2-sol-010","chapter":1,"module":"Modul 3 · Missverständliches","moduleIndex":3,"label":"A3A","title":"Missverständliches","page":18,"kind":"fill","tags":["Practice"],"modelAnswer":"2. Jede Kultur hat ihre eigenen Spielregeln; 3. Regeln sind verschieden – nicht richtig oder\n      falsch.","fields":[{"label":"2","answers":["Jede Kultur hat ihre eigenen Spielregeln"]},{"label":"3","answers":["Regeln sind verschieden – nicht richtig oder falsch."]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-011","solutionId":"b2-sol-011","chapter":1,"module":"Modul 3 · Missverständliches","moduleIndex":3,"label":"A3B","title":"Missverständliches","page":18,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      Spielregel: Für jedes Spiel gibt es bestimmte Regeln. In jedem Land gelten andere Regeln.\n      Die Regeln für Kulturen kann man nicht nachlesen, sie werden unbewusst weitergegeben.\n      Kultur: ein Team mit Regeln, aber Regeln sind nicht überall gleich. Jede Kultur hat eigene\n      Vorstellung von richtig und falsch. Regeln werden von Mitgliedern eines Kulturkreises als\n      selbstverständlich angesehen. Für besseres Verständnis: bewusste Auseinandersetzung mit\n      anderen Kulturen.\n      Missverständnisse: Menschen aus verschiedenen Kulturen – unterschiedliche\n      Weltanschauungen. Missverständnisse, weil jede Seite die andere Gruppe aus eigener Sicht\n      betrachtet. Kein richtig/falsch – nur anders/unterschiedlich.","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-012","solutionId":"b2-sol-012","chapter":1,"module":"Modul 3 · Missverständliches","moduleIndex":3,"label":"A4B","title":"Missverständliches","page":18,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"1. noch nie, 2. ohne Alkohol, 3. nichts Komisches, 4. niemand, 5. nicht (mehr), 6. kein\n      Missverständnis, 7. nirgendwo, 8. unverständlich, 9. nie, 10. intolerant","fields":[{"label":"1","answers":["noch nie"]},{"label":"2","answers":["ohne Alkohol"]},{"label":"3","answers":["nichts Komisches"]},{"label":"4","answers":["niemand"]},{"label":"5","answers":["nicht (mehr)"]},{"label":"6","answers":["kein Missverständnis"]},{"label":"7","answers":["nirgendwo"]},{"label":"8","answers":["unverständlich"]},{"label":"9","answers":["nie"]},{"label":"10","answers":["intolerant"]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-013","solutionId":"b2-sol-013","chapter":1,"module":"Modul 3 · Missverständliches","moduleIndex":3,"label":"A4C","title":"Missverständliches","page":18,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"-los, in-, Des-, a-, non-, il-, ir, miss-, -frei, -leer, Nicht-, Un-, dis-","fields":[{"label":"Answer","answers":["-los, in-, Des-, a-, non-, il-, ir, miss-, -frei, -leer, Nicht-, Un-, dis-"]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-014","solutionId":"b2-sol-014","chapter":1,"module":"Modul 3 · Missverständliches","moduleIndex":3,"label":"A5","title":"Missverständliches","page":18,"kind":"fill","tags":["Practice","Grammar"],"modelAnswer":"• am Ende des Satzes: Satz 2\n      • vor dem zweiten Teil der Satzklammer: Satz 1\n      • vor Adjektiven: Satz 5\n      • vor Präpositionen: Satz 3\n      • vor lokalen Angaben: Satz 4","fields":[{"label":"2","answers":["• vor dem zweiten Teil der Satzklammer: Satz"]},{"label":"1","answers":["• vor Adjektiven: Satz"]},{"label":"5","answers":["• vor Präpositionen: Satz"]},{"label":"3","answers":["• vor lokalen Angaben: Satz 4"]}],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-015","solutionId":"b2-sol-015","chapter":1,"module":"Modul 4 · Zu Hause in Deutschland","moduleIndex":4,"label":"A1","title":"Zu Hause in Deutschland","page":19,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Beispiele:\n      • viele Sprachen\n      • Mischehen\n      • verschiedene Nationalitäten, z. B. in der Schule/im Kindergarten\n      • neue Feste kennenlernen\n      • internationale Restaurants\n      • Offenheit für Neues\n      • einander zuhören/aufeinander zugehen\n      • verschiedene Gerüche","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-016","solutionId":"b2-sol-016","chapter":1,"module":"Modul 4 · Zu Hause in Deutschland","moduleIndex":4,"label":"A2A","title":"Zu Hause in Deutschland","page":19,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n        Abschnitt 1: Statistische Informationen / Informationen zu Migranten in Deutschland\n        Abschnitt 2: Umfrage zum Thema „Integration“ / Verschiedene Meinungen zu Möglichkeiten\n        der Integration","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-017","solutionId":"b2-sol-017","chapter":1,"module":"Modul 4 · Zu Hause in Deutschland","moduleIndex":4,"label":"A2B","title":"Zu Hause in Deutschland","page":19,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"-c Abschnitt 1:\n      1. knapp 80,5 Millionen\n      2. 16 Mio.\n      3. in Berlin (900.000) / Frankfurt: ca. 40%\n      Abschnitt 2:\n       Person 1                            Person 2                              Person 3\n       Beratung                            Begegnung / mehr Kontakt              Toleranz\n       Person 4                            Person 5\n       Sprache                             Ausbildung/Arbeit","fields":[{"label":"1","answers":[":"]},{"label":"1","answers":["knapp"]},{"label":"5","answers":["Millionen"]},{"label":"16","answers":["Mio."]},{"label":"3","answers":["in Berlin ("]},{"label":"90","answers":["0."]},{"label":"00","answers":["0) / Frankfurt: ca."]},{"label":"40","answers":["% Abschnitt"]},{"label":"2","answers":[": Person"]},{"label":"1","answers":["Person"]},{"label":"2","answers":["Person"]},{"label":"3","answers":["Beratung Begegnung / mehr Kontakt Toleranz Person"]},{"label":"4","answers":["Person"]},{"label":"5","answers":["Sprache Ausbildung/Arbeit"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-018","solutionId":"b2-sol-018","chapter":1,"module":"Modul 4 · Zu Hause in Deutschland","moduleIndex":4,"label":"A3A","title":"Zu Hause in Deutschland","page":20,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"Meinung äußern\n        Ich bin der Auffassung, …            Ich bin der Ansicht, …\n        Ich finde, …                         Ich stehe auf dem Standpunkt …\n        Ich denke, …                         Ich meine, …\n        Meiner Meinung nach …                Davon bin ich überzeugt.","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-019","solutionId":"b2-sol-019","chapter":1,"module":"Modul 4 · Zu Hause in Deutschland","moduleIndex":4,"label":"A6A","title":"Zu Hause in Deutschland","page":21,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"-d\n         Koko N’Diabi Roubatou                   Ivan Novoselić                  Sandeep Singh Jolly\n         Affo-Tenin\n         kommt aus Togo; Flucht vor              vor 20 Jahren mit Familie aus   Gründer der Berliner\n         der Familie, als sie                    Kroatien nach Deutschland       Software- und Telekomfirma\n         verheiratet werden sollte;              gekommen; arbeitet in der       teta; seit 30 Jahren in\n         Geburt ihres Sohnes, verdient           Produktion eines großen         Deutschland; 1982 Ankunft in\n         Lebensunterhalt mit dem                 Automobilherstellers; fühlt     Deutschland, keine Aner-\n         Verkauf von Feuerholz und               sich als Ausländer, Deutsche    kennung seines Eliteschul-\n         Keksen; nach Odyssee                    sehen ihn als „Fremden“;        abschlusses; Deutsch lernen,\n         kommt sie nach Berlin; BWL-             private Kontakte zu Kroaten,    Nachholen des Abiturs,\n         Studium; Leitung einer                  fast gar nicht zu Deutschen;    gleichzeitig Leitung des\n         Hausverwaltung in Berlin mit            auch die Kinder fühlen sich     Familiengeschäftes;\n         ihrem Mann, Sohn: Ingenieur;            zerrissen; will als Rentner     einjährige Wartezeit auf\n         fühlt sich in Deutschland zu            nach Kroatien zurück            Studienplatz, dann Informatik-\n         Hause, keine Erfahrung mit                                              Studium und Gründung\n         Diskriminierung                                                         seiner ersten Firma;\n                                                                                 deutscher Staatsbürger\n\nFilm Ganz von vorn beginnen","fields":[{"label":"20","answers":["Jahren mit Familie aus Gründer der Berliner der Familie, als sie Kroatien nach Deutschland Software- und Telekomfirma verheiratet werden sollte; gekommen; arbeitet in der teta; seit"]},{"label":"30","answers":["Jahren in Geburt ihres Sohnes, verdient Produktion eines großen Deutschland"]},{"label":"19","answers":["82 Ankunft in Lebensunterhalt mit dem Automobilherstellers; fühlt Deutschland, keine Aner- Verkauf von Feuerholz und sich als Ausländer, Deutsche kennung seines Eliteschul- Keksen; nach Odyssee sehen ihn als „Fremden“; abschlusses; Deutsch lernen, kommt sie nach Berlin; BWL- private Kontakte zu Kroaten, Nachholen des Abiturs, Studium; Leitung einer fast gar nicht zu Deutschen; gleichzeitig Leitung des Hausverwaltung in Berlin mit auch die Kinder fühlen sich Familiengeschäftes; ihrem Mann, Sohn: Ingenieur; zerrissen; will als Rentner einjährige Wartezeit auf fühlt sich in Deutschland zu nach Kroatien zurück Studienplatz, dann Informatik- Hause, keine Erfahrung mit Studium und Gründung Diskriminierung seiner ersten Firma; deutscher Staatsbürger Film Ganz von vorn beginnen"]}],"film":false,"y0":0,"y1":900},{"id":"b2-ex-020","solutionId":"b2-sol-020","chapter":1,"module":"Film · Ganz von vorn beginnen","moduleIndex":4,"label":"A1A","title":"Ganz von vorn beginnen","page":25,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Mögliche Gründe für Auswanderung: Hoffnung auf eine bessere Ausbildung; Aussicht auf eine\n        gute Arbeitsstelle; Liebe; Familienzusammenführung; niedrigere Lebenshaltungskosten;\n        ruhigere, stressärmere Lebensweise; angenehmere klimatische Bedingungen; Abenteuerlust,\n        Exotik; schwierige politische Lage im Heimatland","fields":[],"film":true,"y0":0,"y1":760},{"id":"b2-ex-021","solutionId":"b2-sol-021","chapter":1,"module":"Film · Ganz von vorn beginnen","moduleIndex":4,"label":"A2A","title":"Ganz von vorn beginnen","page":25,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Es geht um eine deutsche Familie, die v. a. wegen geringer beruflicher Perspektiven in\n        Deutschland vor sieben Jahren einen Neubeginn in Alicante, Spanien, gewagt hat. Alle haben\n        sich an das neue Leben gewöhnt. Obwohl sie in bescheidenen Verhältnissen leben und die\n        Eltern hart arbeiten müssen, haben sie nicht die Absicht, nach Deutschland zurückzukehren.\n        Der Umzug in ein größeres Haus ermöglicht vielleicht ein bequemeres Leben.","fields":[],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-022","solutionId":"b2-sol-022","chapter":1,"module":"Film · Ganz von vorn beginnen","moduleIndex":4,"label":"A2B","title":"Ganz von vorn beginnen","page":25,"kind":"fill","tags":["Practice","Listening"],"modelAnswer":"1. Vater Uwe; 2. Tochter Yvonne; 3. Tochter Denise; 4. Mutter Eva; 5. Tochter Janine","fields":[{"label":"1","answers":["Vater Uwe"]},{"label":"2","answers":["Tochter Yvonne"]},{"label":"3","answers":["Tochter Denise"]},{"label":"4","answers":["Mutter Eva"]},{"label":"5","answers":["Tochter Janine"]}],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-023","solutionId":"b2-sol-023","chapter":1,"module":"Film · Ganz von vorn beginnen","moduleIndex":4,"label":"A3","title":"Ganz von vorn beginnen","page":26,"kind":"choice","tags":["Practice","Reading","Listening"],"modelAnswer":"1. e, 2. f, 3. d, 4. a, 5. b, 6. c","fields":[{"label":"1","answers":["e"]},{"label":"2","answers":["f"]},{"label":"3","answers":["d"]},{"label":"4","answers":["a"]},{"label":"5","answers":["b"]},{"label":"6","answers":["c"]}],"film":true,"y0":0,"y1":650,"options":["A","B","C","D","E","F"]},{"id":"b2-ex-024","solutionId":"b2-sol-024","chapter":1,"module":"Film · Ganz von vorn beginnen","moduleIndex":4,"label":"A4","title":"Ganz von vorn beginnen","page":26,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Gruppe A: Vater Uwe hatte in Deutschland ein kleines Computer-Geschäft. Wegen der\n          Konkurrenz mit den großen Discountern konnte er nicht genug verdienen und musste das\n          Geschäft schließen. Mutter Eva hatte eine Tierheilpraxis, die sie auch aufgegeben hat. Für\n          ihren Neustart haben die Knells die Mittelmeerküste Spaniens gewählt, weil sie die Gegend\n          aus früheren Urlauben kannten. Sie fühlten sich noch nicht zu alt, um etwas zu\n          ändern/beruflich noch mal durchzustarten.\n          Gruppe B: Yvonne, die ältere der beiden, war sofort begeistert. Sie sagte damals: „Einmal\n          müssen wir noch nach Hause, ich muss meine Spielsachen und meine Katze mitnehmen, und\n          dann können wir runter.“ Bei Denise, der jüngsten Tochter, war es schwieriger, denn sie war\n          noch klein (zwölfeinhalb Jahre) und es fiel ihr schwer, ihre Schulfreunde zurückzulassen.","fields":[],"film":true,"y0":320,"y1":980},{"id":"b2-ex-025","solutionId":"b2-sol-025","chapter":1,"module":"Film · Ganz von vorn beginnen","moduleIndex":4,"label":"A5A","title":"Ganz von vorn beginnen","page":26,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Mögliche Lösung:\n          Sprache: Eva spricht gut Spanisch, übernimmt Gänge auf Ämter; Uwe spricht immer noch\n          kein Spanisch; Yvonne konnte die Sprache anfangs nicht, jetzt spricht sie die Sprache gut.\n          Behörden: gutes Spanisch nötig; Anmeldung von Wohnsitz, Auto, Firma ist schwierig\n          („Behördenalptraum“), da alles anders ist als in Deutschland (z. B. Öffnungszeiten)\n          Integration: Töchter sind in Spanien Ausländerinnen; Yvonne besucht zehnte Klasse einer\n          weiterführenden Schule; kannte anfangs keinen und konnte die Sprache nicht, hat geweint;\n          gewöhnt sich aber schnell ein, hat jetzt Freunde, kann die Sprache inzwischen gut, macht in\n          drei Jahren Abitur; Familie will nicht mehr in Deutschland wohnen, höchstens Urlaub dort\n          machen: „viel zu kalt!“\n          Arbeit und Einkommen: Eva hat Job als Hausmeisterin/Verwalterin von Ferienhäusern, sieht\n          nach schönen Zweitwohnsitzen von Deutschen; kann hart arbeiten und will sich durchbeißen;\n          kann ihren ursprünglichen Beruf nicht mehr ausüben, denn er wird dort nicht gebraucht; hat\n          zur Sicherung des Lebensunterhalts für die Familie kürzlich noch Vertrieb mit spanischen\n          Spezialitäten begonnen. Uwe findet in seinem alten Job keine Arbeit; ist handwerklich begabt,\n          erledigt kleine Bauarbeiten („Mann für alle Fälle“) für deutsche Dauerurlauber in Alicante.\n          Beide haben immer neue Ideen.\n          Wohnverhältnisse: (bekannt aus Sequenz 1: vier Personen in 75-Quadratmeter-Wohnung in\n          einer Ferienanlage bei Alicante; nicht viel Platz, aber reicht für den Anfang); Familie besichtigt\n          größeres Haus, das sie sich nach sieben Jahren harter Arbeit leisten könnten; älteste Tochter\n          mit Familie könnte mit einziehen, zögert aber noch","fields":[],"film":true,"y0":610,"y1":1320},{"id":"b2-ex-026","solutionId":"b2-sol-026","chapter":1,"module":"Film · Ganz von vorn beginnen","moduleIndex":4,"label":"A5C","title":"Ganz von vorn beginnen","page":26,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Janine will nicht alleine mit ihrem Sohn nach Spanien ziehen. Man kann über Janines Zögern\n          weiter spekulieren: Sie hat einen guten Job oder gute berufliche Perspektiven in Deutschland;\n          sie sieht zu viele Probleme im Ausland (Job, Sprache, …); sie möchte, dass ihr Sohn in\n          Deutschland aufwächst und zur Schule geht; sie möchte wegen ihrem Partner in Deutschland\n          bleiben; sie möchte auf Dauer nicht zu nahe bei ihren Eltern leben; …","fields":[],"film":true,"y0":610,"y1":1320},{"id":"b2-ex-027","solutionId":"b2-sol-027","chapter":2,"module":"Auftakt","moduleIndex":0,"label":"A1A","title":"Auftakt","page":27,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n          Bitte beachten Sie hier, dass es bei diesen Aufgaben um die subjektive Wahrnehmung der L\n          geht, es kann also unterschiedliche Assoziationen geben.\n          1: Die Frau möchte dem Mann sagen, dass sie gerne mit ihm nach Paris fahren möchte.\n          2: Bild A: demütig, traurig, leidend; Bild B: arrogant, hochnäsig\n          3: Bild A: Man darf hier nicht parken (sondern nur ganz kurz halten, wenn jemand ein- oder\n          aussteigen will oder das Fahrzeug be- oder entladen wird; „eingeschränktes Halteverbot“). –\n          Bild B: Hier kann Blut gespendet werden. – Bild C: Bitte den Mülleimer benutzen. – Bild D:\n          Notausgang.\n          4: A – Ärger; B – Zufriedenheit; C – Neid; D – Überraschung; E – Ernst; F – Fröhlichkeit\n          5: A: 50. Geburtstag; B: Geburt; C: Hochzeitstag/Valentinstag/Geburtstag\n          6: Szene A: positiv; Szene B: negativ; Szene C: negativ; Szene D: positiv; Szene E: negativ;\n          Szene F: positiv; Szene G: negativ","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-028","solutionId":"b2-sol-028","chapter":2,"module":"Auftakt","moduleIndex":0,"label":"A2","title":"Auftakt","page":28,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Andeutungen machen – Körperhaltung – Piktogramme/Schilder – Mimik – Symbolik –\n       Geräusche\n       Weitere Kommunikationswege: z. B. Gestik, Stimmlage, Körperkontakt wie Umarmung,\n       Küsschen, etc.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-029","solutionId":"b2-sol-029","chapter":2,"module":"Modul 1 · Gesten sagen mehr als tausend Worte …","moduleIndex":1,"label":"A1A","title":"Gesten sagen mehr als tausend Worte …","page":29,"kind":"fill","tags":["Practice"],"modelAnswer":"A5 – B6 – C3 – D4 – E2 – F1","fields":[{"label":"Answer","answers":["A5 – B6 – C3 – D4 – E2 – F1"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-030","solutionId":"b2-sol-030","chapter":2,"module":"Modul 1 · Gesten sagen mehr als tausend Worte …","moduleIndex":1,"label":"A2B","title":"Gesten sagen mehr als tausend Worte …","page":29,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n       • wesentlich für zwischenmenschliche Kommunikation\n       • kein Verwendung von verbalen Ausdrucksmitteln\n       • man achtet instinktiv darauf\n       • umfasst z. B. Körperbewegungen, Haltungen, Gesten, Mimik und Tonfall\n       • ist schlecht zu kontrollieren („Der Körper lügt nicht.“)\n       • wird genauso schnell wahrgenommen wie Worte\n       • genetisch vorgegebene Verhaltensmuster werden mit kulturellen erweitert\n       • Menschen: gleiche Mimik, aber Gesten sind kulturspezifisch\n       • zeigt, wie man sich fühlt","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-031","solutionId":"b2-sol-031","chapter":2,"module":"Modul 1 · Gesten sagen mehr als tausend Worte …","moduleIndex":1,"label":"A2C","title":"Gesten sagen mehr als tausend Worte …","page":29,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. … zwischenmenschlicher Verständigung. 2. … Körperbewegungen, Haltungen, Gesten und\n       Mimik (und Tonfall) … . 3. … unser Körper (durch die Ausdrucksformen) nicht lügen kann.\n       4. was die Körpersignale bedeuten / wie sich der andere fühlt. 5. … die gleiche Mimik.\n       6. … etwas Positives. 7. … kulturspezifischer (als die Mimik). 8. … bedeuten oft etwas\n       anderes, als man denkt.","fields":[{"label":"1","answers":["… zwischenmenschlicher Verständigung."]},{"label":"2","answers":["… Körperbewegungen, Haltungen, Gesten und Mimik (und Tonfall) … ."]},{"label":"3","answers":["… unser Körper (durch die Ausdrucksformen) nicht lügen kann."]},{"label":"4","answers":["was die Körpersignale bedeuten / wie sich der andere fühlt."]},{"label":"5","answers":["… die gleiche Mimik."]},{"label":"6","answers":["… etwas Positives."]},{"label":"7","answers":["… kulturspezifischer (als die Mimik)."]},{"label":"8","answers":["… bedeuten oft etwas anderes, als man denkt."]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-032","solutionId":"b2-sol-032","chapter":2,"module":"Modul 1 · Gesten sagen mehr als tausend Worte …","moduleIndex":1,"label":"A3A","title":"Gesten sagen mehr als tausend Worte …","page":30,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"-c A3a: 1b. als, 2a. wie, 3c. als","fields":[{"label":"1","answers":["b. als"]},{"label":"2","answers":["a. wie"]},{"label":"3","answers":["c. als"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-033","solutionId":"b2-sol-033","chapter":2,"module":"Modul 1 · Gesten sagen mehr als tausend Worte …","moduleIndex":1,"label":"A3B","title":"Gesten sagen mehr als tausend Worte …","page":30,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":": Ende – wie – als – Grundform – Komparativ\n      Mögliche Lösung für A3c: 1. …, wie ich erwartet habe. 2. …, als du meinst. 3. …, als man\n      denkt.","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-034","solutionId":"b2-sol-034","chapter":2,"module":"Modul 1 · Gesten sagen mehr als tausend Worte …","moduleIndex":1,"label":"A4A","title":"Gesten sagen mehr als tausend Worte …","page":30,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"-b 1. Je eindeutiger die Signale sind (Nebensatz), desto besser verstehen wir sie. (Hauptsatz)\n      2. Je länger ein Gespräch dauert (Nebensatz), umso klarer wird die Bedeutung der\n      Körpersignale. (Hauptsatz)\n\n       Regel: je … – Nebensatz, desto/umso … – Hauptsatz\n       Nach je und desto/umso steht immer ein Komparativ …","fields":[{"label":"1","answers":["Je eindeutiger die Signale sind (Nebensatz), desto besser verstehen wir sie. (Hauptsatz)"]},{"label":"2","answers":["Je länger ein Gespräch dauert (Nebensatz), umso klarer wird die Bedeutung der Körpersignale. (Hauptsatz) Regel: je … – Nebensatz, desto/umso … – Hauptsatz Nach je und desto/umso steht immer ein Komparativ …"]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-035","solutionId":"b2-sol-035","chapter":2,"module":"Modul 1 · Gesten sagen mehr als tausend Worte …","moduleIndex":1,"label":"A4C","title":"Gesten sagen mehr als tausend Worte …","page":30,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. Je besser man Körpersprache versteht, desto/umso weniger Missverständnisse gibt es.\n       2. Je schneller man Körpersignale wahrnimmt, desto/umso angemessener kann man\n       reagieren.\n       3. Je leichter man die Reaktionen des Gesprächspartners erkennt, desto/umso besser kann\n       man sich unterhalten.","fields":[{"label":"1","answers":["Je besser man Körpersprache versteht, desto/umso weniger Missverständnisse gibt es."]},{"label":"2","answers":["Je schneller man Körpersignale wahrnimmt, desto/umso angemessener kann man reagieren."]},{"label":"3","answers":["Je leichter man die Reaktionen des Gesprächspartners erkennt, desto/umso besser kann man sich unterhalten."]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-036","solutionId":"b2-sol-036","chapter":2,"module":"Modul 2 · Sprachen kinderleicht?!","moduleIndex":2,"label":"A2A","title":"Sprachen kinderleicht?!","page":31,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"Seine Meinung: Das frühe Fremdsprachenlernen ist gut, nicht schwer und bringt viele Vorteile.","fields":[{"label":"Answer","answers":["Seine Meinung: Das frühe Fremdsprachenlernen ist gut, nicht schwer und bringt viele Vorteile."]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-037","solutionId":"b2-sol-037","chapter":2,"module":"Modul 2 · Sprachen kinderleicht?!","moduleIndex":2,"label":"A2B","title":"Sprachen kinderleicht?!","page":31,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Sprachen früh lernen\n       • in Afrika/Asien weit verbreitet (Zeile 26–30)\n       • Gehirn kann Mehrsprachigkeit verarbeiten (Zeile 31–34)\n       • Forschungsergebnisse zeigen, dass kleine Kinder Fremdsprachen am besten lernen (Zeile\n       35–40)\n       • Geduld bei Problemen in der Zeit des frühen Fremdsprachenlernens lohnt sich: weitere\n       Fähigkeiten werden damit erworben (Zeile 57–68)","fields":[{"label":"30","answers":["• Gehirn kann Mehrsprachigkeit verarbeiten (Zeile"]},{"label":"34","answers":["• Forschungsergebnisse zeigen, dass kleine Kinder Fremdsprachen am besten lernen (Zeile"]},{"label":"40","answers":["• Geduld bei Problemen in der Zeit des frühen Fremdsprachenlernens lohnt sich: weitere Fähigkeiten werden damit erworben (Zeile"]},{"label":"68","answers":[")"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-038","solutionId":"b2-sol-038","chapter":2,"module":"Modul 2 · Sprachen kinderleicht?!","moduleIndex":2,"label":"A3B","title":"Sprachen kinderleicht?!","page":32,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n         Eigene Argumente nennen                                      Gegenargumente nennen\n         Ich bin der Ansicht/Meinung, dass …                          Es stimmt zwar, dass …, aber …\n         Ein großer/wichtiger Vorteil von … ist, dass …               Ich sehe ein Problem bei …\n         Ein weiterer Aspekt ist …                                    Das Gegenteil ist der Fall: …\n         Es ist (auch) anzunehmen, dass …                             Im Prinzip ist das richtig, trotzdem …\n         Gerade bei … ist wichtig, dass …                             Dagegen spricht, dass …\n         Viel wichtiger als … finde ich …\n         Es ist logisch, dass …\n         Untersuchungen/Studien zeigen, dass …\n         Sicher sollten …\n         An erster Stelle steht für mich, dass …\n         Zustimmung ausdrücken                                        Eigene Erfahrungen beschreiben\n         Der Meinung/Ansicht bin ich auch.                            Ich habe ähnliche Erfahrungen gemacht, als …\n         Ich bin ganz deiner/Ihrer Meinung.                           Es gibt viele Leute, die …\n         Das stimmt. / Das ist richtig. / Ja, genau.                  Mir ging es ganz ähnlich, als …\n         Da hast du / haben Sie völlig recht.                         Bei mir war das damals so: …\n         Es ist mit Sicherheit so, dass …                             Wir haben oft bemerkt, dass …\n         Ich stimme dir/Ihnen/… zu, denn/da …                         Uns ging es mit/bei … so, dass …\n         Ja, das sehe ich auch so / genauso …                         Wir haben gute/schlechte Erfahrungen mit …\n         Ich finde es auch (nicht) richtig, dass …                    gemacht.\n         Ich finde, … hat damit recht, dass …                         Meine Erfahrungen haben mir gezeigt, dass …\n         Ich bin der gleichen Meinung wie …                           In meiner Kindheit habe ich …\n         Da kann ich mich nur anschließen.                            Im Umgang mit … habe ich erlebt, dass …\n         Sie haben recht damit, dass …                                Ich habe die Erfahrung gemacht, dass …\n                                                                      Ich habe festgestellt, dass …","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-039","solutionId":"b2-sol-039","chapter":2,"module":"Modul 3 · Smalltalk – die Kunst der kleinen Worte …","moduleIndex":3,"label":"A2A","title":"Smalltalk – die Kunst der kleinen Worte …","page":33,"kind":"fill","tags":["Practice"],"modelAnswer":"2 Orte für Smalltalk – 3 Gründe für Ablehnung von Smalltalk – 4 Entspannt bleiben beim\n        Smalltalk – 5 Gesprächspartner als Basis für Smalltalk","fields":[{"label":"2","answers":["Orte für Smalltalk"]},{"label":"3","answers":["Gründe für Ablehnung von Smalltalk"]},{"label":"4","answers":["Entspannt bleiben beim Smalltalk"]},{"label":"5","answers":["Gesprächspartner als Basis für Smalltalk"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-040","solutionId":"b2-sol-040","chapter":2,"module":"Modul 3 · Smalltalk – die Kunst der kleinen Worte …","moduleIndex":3,"label":"A2B","title":"Smalltalk – die Kunst der kleinen Worte …","page":33,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":"Mögliche Lösung:\n        1. gegenseitiges „Beschnuppern“ / Aufnehmen von Kontakt\n        2. peinlich, so belanglos und oberflächlich zu reden / vermeintlich nichtssagendes Gespräch","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-041","solutionId":"b2-sol-041","chapter":2,"module":"Modul 3 · Smalltalk – die Kunst der kleinen Worte …","moduleIndex":3,"label":"A2C","title":"Smalltalk – die Kunst der kleinen Worte …","page":33,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"1., 6., 7., 8.","fields":[{"label":"Answer","answers":["1., 6., 7., 8."]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-042","solutionId":"b2-sol-042","chapter":2,"module":"Modul 3 · Smalltalk – die Kunst der kleinen Worte …","moduleIndex":3,"label":"A3A","title":"Smalltalk – die Kunst der kleinen Worte …","page":34,"kind":"fill","tags":["Practice"],"modelAnswer":"Satz 1–6: es","fields":[{"label":"Answer","answers":["Satz 1–6: es"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-043","solutionId":"b2-sol-043","chapter":2,"module":"Modul 3 · Smalltalk – die Kunst der kleinen Worte …","moduleIndex":3,"label":"A3B","title":"Smalltalk – die Kunst der kleinen Worte …","page":34,"kind":"fill","tags":["Practice"],"modelAnswer":"1. Objekt – 2. Subjekt – 3. Objekt – 4. Subjekt – 5. Subjekt – 6. Objekt","fields":[{"label":"1","answers":["Objekt"]},{"label":"2","answers":["Subjekt"]},{"label":"3","answers":["Objekt"]},{"label":"4","answers":["Subjekt"]},{"label":"5","answers":["Subjekt"]},{"label":"6","answers":["Objekt"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-044","solutionId":"b2-sol-044","chapter":2,"module":"Modul 3 · Smalltalk – die Kunst der kleinen Worte …","moduleIndex":3,"label":"A3C","title":"Smalltalk – die Kunst der kleinen Worte …","page":34,"kind":"fill","tags":["Practice"],"modelAnswer":"das Wetter – Tages- und Jahreszeiten – Natur- und Zeiterscheinungen","fields":[{"label":"Answer","answers":["das Wetter – Tages- und Jahreszeiten – Natur- und Zeiterscheinungen"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-045","solutionId":"b2-sol-045","chapter":2,"module":"Modul 3 · Smalltalk – die Kunst der kleinen Worte …","moduleIndex":3,"label":"A4A","title":"Smalltalk – die Kunst der kleinen Worte …","page":34,"kind":"fill","tags":["Practice"],"modelAnswer":"Position 1 – es","fields":[{"label":"Answer","answers":["Position 1 – es"]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-046","solutionId":"b2-sol-046","chapter":2,"module":"Modul 4 · Wenn zwei sich streiten, …","moduleIndex":4,"label":"A1A","title":"Wenn zwei sich streiten, …","page":35,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"-b Mögliche Lösung:\n      Übt viel Kritik: Manager(in), Hotelchef(in), Friseurmeister, Bauleiter(in), Literaturkritiker(in),\n      Theaterkritiker(in), Personalchef(in), …\n      Steckt viel Kritik ein: Arzt/Ärztin, Servicekräfte, Altenpfleger(in), Kindergärtner(in),\n      Verkäufer(in), Beschäftigte an Informationsstellen, Mitarbeiter im Call Center, Politiker(in),\n      Regisseur(in), Schauspieler(in), …","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-047","solutionId":"b2-sol-047","chapter":2,"module":"Modul 4 · Wenn zwei sich streiten, …","moduleIndex":4,"label":"A2A","title":"Wenn zwei sich streiten, …","page":35,"kind":"truefalse","tags":["Practice","Vocabulary"],"modelAnswer":"1. r, 2. f, 3. f, 4. f, 5. r, 6. f, 7. f, 8. f, 9. r, 10. f","fields":[{"label":"1","answers":["r"]},{"label":"2","answers":["f"]},{"label":"3","answers":["f"]},{"label":"4","answers":["f"]},{"label":"5","answers":["r"]},{"label":"6","answers":["f"]},{"label":"7","answers":["f"]},{"label":"8","answers":["f"]},{"label":"9","answers":["r"]},{"label":"10","answers":["f"]}],"film":false,"y0":430,"y1":1403,"options":["R","F"]},{"id":"b2-ex-048","solutionId":"b2-sol-048","chapter":2,"module":"Modul 4 · Wenn zwei sich streiten, …","moduleIndex":4,"label":"A2B","title":"Wenn zwei sich streiten, …","page":35,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Tanja Block: nimmt Beschimpfungen nicht persönlich; wartet, bis die Leute mit dem Schimpfen\n          fertig sind, zeigt dann Verständnis und bietet ihre Hilfe an; Choleriker verbindet sie mit dem\n          Chef.\n          Tony Trifft: ist gerne kritisch; übt mal mit Humor, mal ironisch, mal direkt Kritik; kritisiert alle:\n          Politiker genauso wie Durchschnittsbürger; findet Kritik wichtig, um gegen Unehrlichkeit\n          vorzugehen; hat kein Mitleid mit den Kritisierten, weil sie Kritik verdienen\n          Simone Ritterbusch: musste sich ans Kritiküben (besonders bei älteren Schülern) erst\n          gewöhnen; versucht durch Fragebögen herauszufinden, was ihre Schüler/innen kritisch\n          sehen; kritisiert ihre Schüler/innen respektvoll, um ihnen nicht das Selbstvertrauen zu nehmen\n          (Simone Ritterbuschs Schüler/innen: können Kritik gut ertragen, reagieren ruhig; üben nur\n          selten selbst Kritik am Unterricht; kritisieren nur, wenn sie in Fragebögen gefragt werden.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-049","solutionId":"b2-sol-049","chapter":2,"module":"Modul 4 · Wenn zwei sich streiten, …","moduleIndex":4,"label":"A3B","title":"Wenn zwei sich streiten, …","page":36,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1 Immer mit der Ruhe – 2 Immer bei einer Sache bleiben – 3 Alles zu seiner Zeit – 4 Genau\n          hinhören – 5 „Ich“ statt „Du“ – 6 Kein Konsens? Dann Kompromiss! – 7 Entschuldigungen sind\n          keine Schwäche – 8 Wie war‘s heute?\n\nFilm Was man mit dem Körper sagen kann","fields":[{"label":"1","answers":["Immer mit der Ruhe"]},{"label":"2","answers":["Immer bei einer Sache bleiben"]},{"label":"3","answers":["Alles zu seiner Zeit"]},{"label":"4","answers":["Genau hinhören"]},{"label":"5","answers":["„Ich“ statt „Du“"]},{"label":"6","answers":["Kein Konsens? Dann Kompromiss!"]},{"label":"7","answers":["Entschuldigungen sind keine Schwäche"]},{"label":"8","answers":["Wie war‘s heute? Film Was man mit dem Körper sagen kann"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-050","solutionId":"b2-sol-050","chapter":2,"module":"Film · Was man mit dem Körper sagen kann","moduleIndex":4,"label":"A1A","title":"Was man mit dem Körper sagen kann","page":41,"kind":"choice","tags":["Practice","Reading","Listening"],"modelAnswer":"1. D, 2. C, 3. A, 4. B, 5. E","fields":[{"label":"1","answers":["D"]},{"label":"2","answers":["C"]},{"label":"3","answers":["A"]},{"label":"4","answers":["B"]},{"label":"5","answers":["E"]}],"film":true,"y0":0,"y1":760,"options":["A","B","C","D","E"]},{"id":"b2-ex-051","solutionId":"b2-sol-051","chapter":2,"module":"Film · Was man mit dem Körper sagen kann","moduleIndex":4,"label":"A2A","title":"Was man mit dem Körper sagen kann","page":41,"kind":"fill","tags":["Practice","Reading","Listening"],"modelAnswer":"-b A2a: 1. Mimik (Gesichtsausdruck), Gestik (Ausdruck durch andere Körperteile, bes. der\n      Hände), Haltung (Ausdruck durch den gesamten Körper); 2. Lachen, Wut, Angst, Ekel, 3.\n      Nachahmung","fields":[{"label":"1","answers":["Mimik (Gesichtsausdruck), Gestik (Ausdruck durch andere Körperteile, bes. der Hände), Haltung (Ausdruck durch den gesamten Körper)"]},{"label":"2","answers":["Lachen, Wut, Angst, Ekel"]},{"label":"3","answers":["Nachahmung"]}],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-052","solutionId":"b2-sol-052","chapter":2,"module":"Film · Was man mit dem Körper sagen kann","moduleIndex":4,"label":"A2B","title":"Was man mit dem Körper sagen kann","page":41,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":": Einen Fremden zu berühren ist in westlichen Ländern ein Zeichen von Sympathie – in\n      Japan aber eine grobe Unhöflichkeit. Ein Lächeln eines Asiaten bedeutet oft nicht wie bei uns\n      freundliche Ermunterung, sondern Verlegenheit.","fields":[],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-053","solutionId":"b2-sol-053","chapter":2,"module":"Film · Was man mit dem Körper sagen kann","moduleIndex":4,"label":"A3","title":"Was man mit dem Körper sagen kann","page":42,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"misslungenes Gespräch                               gelungenes Gespräch\n           Arzt sucht keinen Blickkontakt, reagiert nicht      Arzt begrüßt Patienten freundlich, setzt die\n           auf den Patienten, schaut ihn über die Brille       Brille ab, sucht Blickkontakt, lehnt den\n           hinweg an, Handflächen beim Überreichen             Oberkörper vor und signalisiert so Interesse,\n           zeigen nach unten, öffnet am Ende weit die          zeigt lebendige Körpersprache\n           Arme (Überheblichkeit)                              Patient spiegelt Vorlehnen: Gespräch\n           Patient schlägt Beine übereinander: Abwehr          funktioniert","fields":[],"film":true,"y0":0,"y1":650},{"id":"b2-ex-054","solutionId":"b2-sol-054","chapter":2,"module":"Film · Was man mit dem Körper sagen kann","moduleIndex":4,"label":"A4A","title":"Was man mit dem Körper sagen kann","page":42,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"-b A4a: An diesem Seminar nehmen Manager teil. Das Ziel ist es, überzeugender zu wirken, die\n      Körpersprache als Werkzeug für den Erfolg einzusetzen; bewusst den Körper einzusetzen,\n      Hemmungen abzubauen/Schwellen zu überwinden, Ausdrucksfähigkeit zurückzuerlangen","fields":[],"film":true,"y0":320,"y1":980},{"id":"b2-ex-055","solutionId":"b2-sol-055","chapter":2,"module":"Film · Was man mit dem Körper sagen kann","moduleIndex":4,"label":"A4B","title":"Was man mit dem Körper sagen kann","page":42,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":": Hier wird eine Schauspieltechnik demonstriert: Wenn ein Schauspieler für eine\n      bestimmte Zeit eine bestimmte (emotionale) Haltung einnimmt, verändert sich seine Stimmung\n      entsprechend dieser Haltung. Man kann sich also durch Körpersprache selbst beeinflussen.","fields":[],"film":true,"y0":320,"y1":980},{"id":"b2-ex-056","solutionId":"b2-sol-056","chapter":3,"module":"Auftakt","moduleIndex":0,"label":"A1B","title":"Auftakt","page":43,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1E, 2F, 3B, 4A, 5C, 6D","fields":[{"label":"1","answers":["E"]},{"label":"2","answers":["F"]},{"label":"3","answers":["B"]},{"label":"4","answers":["A"]},{"label":"5","answers":["C"]},{"label":"6","answers":["D"]}],"film":false,"y0":0,"y1":760,"options":["A","B","C","D","E","F"]},{"id":"b2-ex-057","solutionId":"b2-sol-057","chapter":3,"module":"Modul 1 · Mein Weg zum Job","moduleIndex":1,"label":"A1B","title":"Mein Weg zum Job","page":45,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"A: Webseite der Uni, Praktikumsbörse – B: Agentur für Zeitarbeit – C: Stellenanzeigen im\n          Internet – D: Selbstständig gemacht – E: Tipp eines Freundes – F: Agentur für Arbeit –\n          G: Praktikum – H: Kontakte durch ein Karrierenetzwerk online, später: Stellenportal im Internet","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-058","solutionId":"b2-sol-058","chapter":3,"module":"Modul 1 · Mein Weg zum Job","moduleIndex":1,"label":"A1C","title":"Mein Weg zum Job","page":45,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"A: Ferienjob/Studentenjob, Praktikum für Berufserfahrung – B: arbeitslos, Firma musste\n          schließen – C: Job war langweilig – D: Traum, selbstständig zu sein – E: wurde nach der\n          Lehre nicht übernommen – F: wurde nach Aufkauf der Firma entlassen – G: Studium fertig /\n          wollte feste Stelle finden – H: brauchte neue Herausforderung","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-059","solutionId":"b2-sol-059","chapter":3,"module":"Modul 1 · Mein Weg zum Job","moduleIndex":1,"label":"A3A","title":"Mein Weg zum Job","page":46,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"1. nicht nur …, sondern auch, 2. weder … noch, 3. Je …, desto, 4. Entweder … oder,\n      5. zwar …, aber, 6. Einerseits …, andererseits, 7. sowohl … als auch","fields":[{"label":"1","answers":["nicht nur …, sondern auch"]},{"label":"2","answers":["weder … noch"]},{"label":"3","answers":["Je …, desto"]},{"label":"4","answers":["Entweder … oder"]},{"label":"5","answers":["zwar …, aber"]},{"label":"6","answers":["Einerseits …, andererseits"]},{"label":"7","answers":["sowohl … als auch"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-060","solutionId":"b2-sol-060","chapter":3,"module":"Modul 1 · Mein Weg zum Job","moduleIndex":1,"label":"A3B","title":"Mein Weg zum Job","page":46,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Aufzählung          „negative“           Vergleich           Alternative              Einschränkung/\n                           Aufzählung                                                        Gegensatz\n       nicht nur …,        weder … noch         je …, desto         entweder …               zwar …, aber\n       sondern auch                                                 oder                     einerseits …,\n       sowohl …., als                                                                        andererseits\n       auch","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-061","solutionId":"b2-sol-061","chapter":3,"module":"Modul 1 · Mein Weg zum Job","moduleIndex":1,"label":"A3C","title":"Mein Weg zum Job","page":46,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. Je mehr Erfahrung man hat, desto leichter findet man eine Stelle.\n      2. Bei einer Bewerbung ist nicht nur der Lebenslauf wichtig, sondern auch das\n      Bewerbungsschreiben. / Bei einer Bewerbung ist sowohl der Lebenslauf wichtig als auch das\n      Bewerbungsschreiben.\n      3. Man bewirbt sich entweder per E-Mail oder über Online-Formulare. / Man bewirbt sich zwar\n      meistens per E-Mail, aber Bewerbungen über Online-Formulare sind auch möglich.\n      4. Für viele Stellen ist nicht nur eine Ausbildung wichtig, sondern auch genügend\n      Berufserfahrung. / Für viele Stellen ist sowohl eine Ausbildung wichtig als auch genügend\n      Berufserfahrung.\n      5. Manche Berufe sind weder interessant noch gut bezahlt.\n      6. Sich selbstständig zu machen ist einerseits anstrengend, andererseits macht es auch\n      Spaß. / Sich selbstständig zu machen ist zwar anstrengend, aber es macht auch Spaß.\n      7. Es gibt zwar viele freie Stellen, aber trotzdem finden viele Leute keine Arbeit.","fields":[{"label":"1","answers":["Je mehr Erfahrung man hat, desto leichter findet man eine Stelle."]},{"label":"2","answers":["Bei einer Bewerbung ist nicht nur der Lebenslauf wichtig, sondern auch das Bewerbungsschreiben. / Bei einer Bewerbung ist sowohl der Lebenslauf wichtig als auch das Bewerbungsschreiben."]},{"label":"3","answers":["Man bewirbt sich entweder per E-Mail oder über Online-Formulare. / Man bewirbt sich zwar meistens per E-Mail, aber Bewerbungen über Online-Formulare sind auch möglich."]},{"label":"4","answers":["Für viele Stellen ist nicht nur eine Ausbildung wichtig, sondern auch genügend Berufserfahrung. / Für viele Stellen ist sowohl eine Ausbildung wichtig als auch genügend Berufserfahrung."]},{"label":"5","answers":["Manche Berufe sind weder interessant noch gut bezahlt."]},{"label":"6","answers":["Sich selbstständig zu machen ist einerseits anstrengend, andererseits macht es auch Spaß. / Sich selbstständig zu machen ist zwar anstrengend, aber es macht auch Spaß."]},{"label":"7","answers":["Es gibt zwar viele freie Stellen, aber trotzdem finden viele Leute keine Arbeit."]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-062","solutionId":"b2-sol-062","chapter":3,"module":"Modul 2 · Glücklich im Job?","moduleIndex":2,"label":"A1B","title":"Glücklich im Job?","page":47,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1E – 2A – 3D – 4B – 5C","fields":[{"label":"1","answers":["E"]},{"label":"2","answers":["A"]},{"label":"3","answers":["D"]},{"label":"4","answers":["B"]},{"label":"5","answers":["C"]}],"film":false,"y0":0,"y1":760,"options":["A","B","C","D","E"]},{"id":"b2-ex-063","solutionId":"b2-sol-063","chapter":3,"module":"Modul 2 · Glücklich im Job?","moduleIndex":2,"label":"A2","title":"Glücklich im Job?","page":47,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"1b (Zeile 2–5 + 11–12), 2a (Zeile 16–17 + 26–28), 3a (Zeile 29–30), 4a (Zeile 47–48), 5b\n      (Zeile 54–58)","fields":[{"label":"1","answers":["b"]},{"label":"5","answers":["+"]},{"label":"2","answers":["a"]},{"label":"17","answers":["+"]},{"label":"3","answers":["a"]},{"label":"4","answers":["a"]},{"label":"5","answers":["b"]},{"label":"58","answers":[")"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-064","solutionId":"b2-sol-064","chapter":3,"module":"Modul 2 · Glücklich im Job?","moduleIndex":2,"label":"A2B","title":"Glücklich im Job?","page":47,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"zufrieden machen: wirklich zu machen, was man möchte; ein der Leistung angemessenes\n      Gehalt; das Gefühl, das Leben selbst in der Hand zu haben, z. B. durch Flexibilität oder die\n      Möglichkeit, Teilzeit zu arbeiten; der richtige Arbeitsplatz: positive und kooperative\n      Unternehmenskultur; ein guter Chef: bietet fachliche Unterstützung, sorgt für schnelle Lösung\n      von Konflikten und kann eigene Fehler eingestehen; anspruchsvolle Aufgaben; genug Zeit für\n      die Aufgaben / kein Stress; Gefühl, etwas Sinnvolles zu tun\n      unzufrieden machen: keine Arbeit zu haben (wegen Verlust von Ansehen und sozialen\n      Kontakten und fehlende Strukturierung des Tages); wenn der Chef auf Dauer Druck ausübt;\n      ständige Angst um den Job ohne Aussicht auf einen Ausweg","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-065","solutionId":"b2-sol-065","chapter":3,"module":"Modul 3 · Teamgeist","moduleIndex":3,"label":"A2A","title":"Teamgeist","page":49,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Event: mit dem ganzen Team an den See fahren, gemeinsam ein Boot bauen und grillen\n      Problem: nicht alle sind begeistert von dem Angebot\n      • ein Kollege findet den Freitagstermin nicht gut, weil er da lieber Zeit mit seiner Familie oder\n      Freunden verbringen möchte\n      • eine Kollegin fährt ungern Boot, ist handwerklich nicht begabt und fühlt sich gezwungen,\n      mitzumachen","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-066","solutionId":"b2-sol-066","chapter":3,"module":"Modul 3 · Teamgeist","moduleIndex":3,"label":"A2B","title":"Teamgeist","page":49,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Für: Sinn: mit den Kolleginnen und Kollegen als Team zusammenarbeiten und gemeinsam ein\n      Problem lösen; gute Möglichkeit der Teambildung; Angebot vonseiten der Firma ist nicht\n      selbstverständlich; Spaß; andere, die es ausprobiert haben, fanden es toll/lustig; Abwechslung\n      (mal was Konkretes, machen, statt wie sonst immer vorm Computer)\n      Gegen: Freitag – früh nach Haus/bei Familie sein; wenn man nicht mitmacht, macht das\n      keinen guten Eindruck; Arbeitgeber drängt einen zur Teilnahme / Teilnahme ist keine freie\n      Entscheidung; Angst auf dem Wasser; handwerklich unbegabt; zusätzlicher Termin am\n      Freitagabend; Job ist Job und keine Freizeit","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-067","solutionId":"b2-sol-067","chapter":3,"module":"Modul 3 · Teamgeist","moduleIndex":3,"label":"A3B","title":"Teamgeist","page":50,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"Ziel/Absicht: um … zu, 2. Einschränkung: ohne … zu, 3. Gegensatz: (an)statt … zu","fields":[{"label":"2","answers":["Einschränkung: ohne … zu"]},{"label":"3","answers":["Gegensatz: (an)statt … zu"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-068","solutionId":"b2-sol-068","chapter":3,"module":"Modul 3 · Teamgeist","moduleIndex":3,"label":"A3C","title":"Teamgeist","page":50,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. … um das Teamevent für die Firma zu buchen, 2. … ohne das Teamevent zu buchen,\n       3. … um Informationen zum Teamevent zu bekommen, 4. Anstatt anzurufen, hat sie das\n       Event per Mail gebucht.","fields":[{"label":"1","answers":["… um das Teamevent für die Firma zu buchen"]},{"label":"2","answers":["… ohne das Teamevent zu buchen"]},{"label":"3","answers":["… um Informationen zum Teamevent zu bekommen"]},{"label":"4","answers":["Anstatt anzurufen, hat sie das Event per Mail gebucht."]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-069","solutionId":"b2-sol-069","chapter":3,"module":"Modul 3 · Teamgeist","moduleIndex":3,"label":"A4A","title":"Teamgeist","page":50,"kind":"fill","tags":["Practice"],"modelAnswer":"1. Viele Firmen – ihre Mitarbeiter; 2. Sie – die Firma; 3. Sie – wir","fields":[{"label":"1","answers":["Viele Firmen – ihre Mitarbeiter"]},{"label":"2","answers":["Sie – die Firma"]},{"label":"3","answers":["Sie – wir"]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-070","solutionId":"b2-sol-070","chapter":3,"module":"Modul 3 · Teamgeist","moduleIndex":3,"label":"A4B","title":"Teamgeist","page":50,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":"Subjekt im Hauptsatz = Subjekt im Nebensatz: um … zu, anstatt zu, ohne zu\n       Subjekt im Hauptsatz ≠ Subjekt im Nebensatz: damit, anstatt dass , ohne dass","fields":[],"film":false,"y0":320,"y1":980},{"id":"b2-ex-071","solutionId":"b2-sol-071","chapter":3,"module":"Modul 4 · Werben Sie für sich!","moduleIndex":4,"label":"A1A","title":"Werben Sie für sich!","page":51,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1j, 3i, 4d, 5b, 6h, 7g, 8e, 9c, 10f","fields":[{"label":"1","answers":["J"]},{"label":"3","answers":["I"]},{"label":"4","answers":["D"]},{"label":"5","answers":["B"]},{"label":"6","answers":["H"]},{"label":"7","answers":["G"]},{"label":"8","answers":["E"]},{"label":"9","answers":["C"]},{"label":"10","answers":["F"]}],"film":false,"y0":0,"y1":760,"options":["A","B","C","D","E","F","G","H","I","J"]},{"id":"b2-ex-072","solutionId":"b2-sol-072","chapter":3,"module":"Modul 4 · Werben Sie für sich!","moduleIndex":4,"label":"A2","title":"Werben Sie für sich!","page":51,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Arbeitsbereich der Firma: Organisation von Veranstaltungen für nationale und internationale\n       Kunden\n       Aufgaben: Kampagnen entwickeln und betreuen, Veranstaltungen planen, Angebote erstellen,\n       Budgetverwaltung\n       Anforderungen: abgeschlossenes Studium, 2–3 Jahre Berufserfahrung, Konzeptionsstärke,\n       kommunikativ sein, selbstständige und zielorientierte Arbeitsweise, fließendes Englisch;\n       zusätzliches Plus: weitere Fremdsprachen","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-073","solutionId":"b2-sol-073","chapter":3,"module":"Modul 4 · Werben Sie für sich!","moduleIndex":4,"label":"A3A","title":"Werben Sie für sich!","page":52,"kind":"fill","tags":["Practice"],"modelAnswer":"H–B–C–G–F–J–E–K–I–A–L–D","fields":[{"label":"Answer","answers":["H–B–C–G–F–J–E–K–I–A–L–D"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-074","solutionId":"b2-sol-074","chapter":3,"module":"Modul 4 · Werben Sie für sich!","moduleIndex":4,"label":"A3B","title":"Werben Sie für sich!","page":52,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":"ausgebildete Eventmanagerin, umfangreiche Berufserfahrung, teamfähig, Konzeption und\n       Leitung, Budgetverantwortung, Englisch, weitere Fremdsprachen Französisch und Arabisch","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-075","solutionId":"b2-sol-075","chapter":3,"module":"Modul 4 · Werben Sie für sich!","moduleIndex":4,"label":"A3C","title":"Werben Sie für sich!","page":52,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Einleitung: Sie suchen …\n       Bisherige Berufserfahrung/Erfolge: Als … habe ich umfangreiche Erfahrungen in …\n       gesammelt; Meine bisherige berufliche Erfahrung hat mir gezeigt, dass ich gerne … / … dass\n       mir … ebenso liegt wie …\n       Erwartungen an die Stelle: Von meinem Eintritt in Ihr Unternehmen verspreche ich mir …\n       Eintrittstermin: Die Tätigkeit als … in Ihrem Unternehmen könnte ich ab dem … aufnehmen.\n       Schlusssatz: Über eine Einladung zu einem persönlichen Vorstellungsgespräch freue ich mich\n       sehr.","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-076","solutionId":"b2-sol-076","chapter":3,"module":"Modul 4 · Werben Sie für sich!","moduleIndex":4,"label":"A5A","title":"Werben Sie für sich!","page":52,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"• Wirkt unsicher: fragt, womit sie beginnen soll, nimmt eine Aussage als „zu ehrlich“ zurück\n       • Erzählt zu viel Privates (eigene Wohnung, Details zur Abifeier)\n       • Sie erzählt Dinge, die nichts mit der Stelle / dem Job zu tun haben\n       • Sie nennt zwar ihre Ausbildung, geht aber nicht auf wichtige/konkrete Stationen ihrer\n       bisherigen Karriere / an ihrer bisherigen Arbeitsstelle ein.\n       • Sie redet schlecht über ihre Chefin und wird auch da zu privat.\n       • Sie sagt nicht (bzw. nur floskelhaft), warum sie genau diese Stelle haben möchte.\n\nFilm Gleicher Lohn für gleiche Arbeit?","fields":[],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-077","solutionId":"b2-sol-077","chapter":3,"module":"Film · Gleicher Lohn für gleiche Arbeit?","moduleIndex":4,"label":"A2","title":"Gleicher Lohn für gleiche Arbeit?","page":57,"kind":"fill","tags":["Practice","Reading","Listening"],"modelAnswer":"Gruppe A: Kerstin Reschke            Gruppe B: Belgin Tanriverdi\n        beruflicher Weg              erst Ausbildung zur                  arbeitet als Vertriebsmanagerin\n                                     Bürokauffrau, dann noch              bei IBM, Studium: Chemie und\n                                     Friseurausbildung, arbeitet seit 8   Internationales Marketing,\n                                     Jahren als Friseurin                 Studium war super\n                                                                          Voraussetzung für einen\n                                                                          gutbezahlten Job, hat für eine\n                                                                          Frau untypische Studiengänge\n                                                                          gewählt\n\n\n\n\n\n\n           Einkommen                für größere Anschaffungen spart       Bezahlung nach Leistung,\n                                    sie ihr Trinkgeld; arbeitet im        verdient so gut wie männliche\n                                    Niedriglohnsektor                     Kollegen in derselben Position,\n                                                                          kommt wohl in ein paar Jahren\n                                                                          auf über 100.000 Euro im Jahr\n           Familienverhältnisse     (keine Angabe)                        zwei Kinder, nach Geburt gleich\n                                                                          wieder gearbeitet, zählt sich zu\n                                                                          den „glücklichen Eltern“\n           Zufriedenheit im Job     für sie ist es eine Erfüllung, wenn   ist zufrieden und glücklich, jeder\n                                    ihre Kunden zufrieden lächeln         wird dort gerecht nach\n                                                                          Leistungen bezahlt\n           Sonstiges                schlecht bezahlter typischer          hat kein eigenes Büro, loggt sich\n                                    Frauenberuf; Frauen verdienen         von irgendwo ein, arbeitet zwei\n                                    durchschnittlich ein Viertel          Tage pro Woche von zu Hause\n                                    weniger als Männer                    aus","fields":[{"label":"8","answers":["Internationales Marketing, Jahren als Friseurin Studium war super Voraussetzung für einen gutbezahlten Job, hat für eine Frau untypische Studiengänge gewählt Einkommen für größere Anschaffungen spart Bezahlung nach Leistung, sie ihr Trinkgeld; arbeitet im verdient so gut wie männliche Niedriglohnsektor Kollegen in derselben Position, kommt wohl in ein paar Jahren auf über"]},{"label":"10","answers":["0."]},{"label":"00","answers":["0 Euro im Jahr Familienverhältnisse (keine Angabe) zwei Kinder, nach Geburt gleich wieder gearbeitet, zählt sich zu den „glücklichen Eltern“ Zufriedenheit im Job für sie ist es eine Erfüllung, wenn ist zufrieden und glücklich, jeder ihre Kunden zufrieden lächeln wird dort gerecht nach Leistungen bezahlt Sonstiges schlecht bezahlter typischer hat kein eigenes Büro, loggt sich Frauenberuf; Frauen verdienen von irgendwo ein, arbeitet zwei durchschnittlich ein Viertel Tage pro Woche von zu Hause weniger als Männer aus"]}],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-078","solutionId":"b2-sol-078","chapter":3,"module":"Film · Gleicher Lohn für gleiche Arbeit?","moduleIndex":4,"label":"A3A","title":"Gleicher Lohn für gleiche Arbeit?","page":58,"kind":"open","tags":["Practice","Writing","Listening"],"modelAnswer":"Mögliche Lösung:\n          1. … typische Frauenberufe meist schlechter bezahlt sind. 2 … sie wegen der Familie oft\n          Teilzeit arbeiten. 3. … weniger Berufsjahre haben. 4. … ans Geld denken.","fields":[],"film":true,"y0":0,"y1":650},{"id":"b2-ex-079","solutionId":"b2-sol-079","chapter":4,"module":"Auftakt","moduleIndex":0,"label":"A1A","title":"Auftakt","page":59,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n          A: Jugendliche/Erziehung/Generationenkonflikte; B: Dienstleistungen/Gastronomie/\n          Beschwerden/Höflichkeit; C: Schule/Erziehung/Respekt; D: Arbeit/Beruf/Stress;\n          E: Natur/Umwelt/Geschäftsidee/Erfolg/Geld; F: Medien/Belästigung/Rücksichtnahme","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-080","solutionId":"b2-sol-080","chapter":4,"module":"Modul 1 · Sport gegen Gewalt","moduleIndex":1,"label":"A1B","title":"Sport gegen Gewalt","page":61,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Fahim Yusufzai:\n          • gebürtiger Afghane\n          • arbeitete als Sicherheitsleiter im Einkaufszentrum Jenfeld\n          • war frustriert, weil er immer wieder dieselben Jugendlichen wegen Diebstahl, Randalieren\n          oder Leute-Ärgern der Polizei übergeben musste\n          • lernte als 13-Jähriger Taekwondo\n          • seit 1989 schwarzer Gürtel\n          • gründete Verein „Sport gegen Gewalt“ und bringt Jugendlichen Taekwondo, Kickboxen,\n          Fußball und Basketball bei\n          • die im Einkaufszentrum erwischten Jugendlichen können wählen, ob er sie zur Polizei bringt\n          oder ob sie zu ihm in den Verein kommen\n          • seit dem Training sind Zahl der Diebstähle und Sachbeschädigungen zurückgegangen\n          • sein Verein ist ein Vorbild für viele andere Projekte mit ähnlichen Zielen","fields":[{"label":"13","answers":["Jähriger Taekwondo • seit"]},{"label":"19","answers":["89 schwarzer Gürtel • gründete Verein „Sport gegen Gewalt“ und bringt Jugendlichen Taekwondo, Kickboxen, Fußball und Basketball bei • die im Einkaufszentrum erwischten Jugendlichen können wählen, ob er sie zur Polizei bringt oder ob sie zu ihm in den Verein kommen • seit dem Training sind Zahl der Diebstähle und Sachbeschädigungen zurückgegangen • sein Verein ist ein Vorbild für viele andere Projekte mit ähnlichen Zielen"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-081","solutionId":"b2-sol-081","chapter":4,"module":"Modul 1 · Sport gegen Gewalt","moduleIndex":1,"label":"A1C","title":"Sport gegen Gewalt","page":61,"kind":"fill","tags":["Practice"],"modelAnswer":"3–1–4–2–6–5","fields":[{"label":"Answer","answers":["3–1–4–2–6–5"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-082","solutionId":"b2-sol-082","chapter":4,"module":"Modul 1 · Sport gegen Gewalt","moduleIndex":1,"label":"A2A","title":"Sport gegen Gewalt","page":61,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"-b\n           Nebensatz                                       Hauptsatz\n           Wer   erwischt wurde,                           der  bekam zunächst Hausverbot.\n           Wen Fahim Yusufzai der Polizei übergeben        dem begegnete er am nächsten Tag\n                 hatte,                                         garantiert wieder im Einkaufszentrum.\n           Wer   diesen Sport treibt,                      dem sind Eigenschaften wie Disziplin,\n                                                                Selbstbeherrschung und\n                                                                Verantwortung nicht … fremd.\n           Wer    einmal solche Eintragungen hat,          der  hat sich seine Zukunft verbaut.\n           Wer    zu ihm in sein Taekwondo-Training        den bringt er nicht zur Polizei.\n                  kommt,\n\n\n\n       Wer      im Training flucht oder jemanden        der     muss Liegestütze machen.\n                beleidigt,\n       Wen      Probleme plagen,                        der     hat die Möglichkeit, jederzeit mit ihm\n                                                                zu sprechen.\n       Wem      er Taekwondo beibringt,                 der     merkt schnell, dass es keinen Sinn\n                                                                macht, Mist zu bauen.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-083","solutionId":"b2-sol-083","chapter":4,"module":"Modul 1 · Sport gegen Gewalt","moduleIndex":1,"label":"A2C","title":"Sport gegen Gewalt","page":61,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"1. Person, 2. Nebensatz, Hauptsatz, 3. Kasus, 4. der/den/dem","fields":[{"label":"1","answers":["Person"]},{"label":"2","answers":["Nebensatz, Hauptsatz"]},{"label":"3","answers":["Kasus"]},{"label":"4","answers":["der/den/dem"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-084","solutionId":"b2-sol-084","chapter":4,"module":"Modul 2 · Armut","moduleIndex":2,"label":"A2","title":"Armut","page":63,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1A – 2G – 3E – 4D","fields":[{"label":"1","answers":["A"]},{"label":"2","answers":["G"]},{"label":"3","answers":["E"]},{"label":"4","answers":["D"]}],"film":false,"y0":430,"y1":1403,"options":["A","B","C","D","E","F","G"]},{"id":"b2-ex-085","solutionId":"b2-sol-085","chapter":4,"module":"Modul 3 · Im Netz","moduleIndex":3,"label":"A1B","title":"Im Netz","page":65,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"A: Suche nach Rezepten und Bücherkauf für den eReader\n      B: Freunde im Netz treffen: chatten, Austausch von Infos zu neuen Spielen und Filmen,\n      spielen\n      C: skypen\n      D: Informationen einholen zu Reisen oder Produkten, Hotelbewertungen ansehen,\n      Verschiedenes im Netz buchen","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-086","solutionId":"b2-sol-086","chapter":4,"module":"Modul 3 · Im Netz","moduleIndex":3,"label":"A1C","title":"Im Netz","page":65,"kind":"fill","tags":["Practice"],"modelAnswer":"1. – 3. – 6. – 4.","fields":[{"label":"Answer","answers":["1. – 3. – 6. – 4."]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-087","solutionId":"b2-sol-087","chapter":4,"module":"Modul 3 · Im Netz","moduleIndex":3,"label":"A1D","title":"Im Netz","page":65,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Zahlen                                Merkmale einer Onlinesucht\n       1. 10 % der Kinder zwischen 11 und 14            1. Onlinewelt dominiert Denken und\n       Jahren computerspielsüchtig                      Verhalten / Tätigkeit am Computer am\n                                                        wichtigsten im Leben\n       2. 12 % erste Anzeichen von Onlinesucht          2. ohne Computer Entzugserscheinungen\n       3. 10–20 % Internetnutzer süchtig                3. Verlust der Kontrolle über die Zeit","fields":[{"label":"10","answers":["% der Kinder zwischen"]},{"label":"11","answers":["und"]},{"label":"1","answers":["Onlinewelt dominiert Denken und Jahren computerspielsüchtig Verhalten / Tätigkeit am Computer am wichtigsten im Leben"]},{"label":"12","answers":["% erste Anzeichen von Onlinesucht"]},{"label":"2","answers":["ohne Computer Entzugserscheinungen"]},{"label":"20","answers":["% Internetnutzer süchtig"]},{"label":"3","answers":["Verlust der Kontrolle über die Zeit"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-088","solutionId":"b2-sol-088","chapter":4,"module":"Modul 3 · Im Netz","moduleIndex":3,"label":"A2A","title":"Im Netz","page":65,"kind":"fill","tags":["Practice"],"modelAnswer":"Untersuchungen – 2. Aufregung – 3. Frage – 4. Flucht","fields":[{"label":"2","answers":["Aufregung"]},{"label":"3","answers":["Frage"]},{"label":"4","answers":["Flucht"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-089","solutionId":"b2-sol-089","chapter":4,"module":"Modul 3 · Im Netz","moduleIndex":3,"label":"A2B","title":"Im Netz","page":65,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"2. aufregen: Die Ergebnisse regten nicht nur Eltern und Lehrer auf.\n      3. fragen: Da möchte ich Sie gleich weiter fragen.\n      4. fliehen: Die Jugendlichen fliehen in virtuelle Parallelwelten.","fields":[{"label":"2","answers":["aufregen: Die Ergebnisse regten nicht nur Eltern und Lehrer auf."]},{"label":"3","answers":["fragen: Da möchte ich Sie gleich weiter fragen."]},{"label":"4","answers":["fliehen: Die Jugendlichen fliehen in virtuelle Parallelwelten."]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-090","solutionId":"b2-sol-090","chapter":4,"module":"Modul 3 · Im Netz","moduleIndex":3,"label":"A2C","title":"Im Netz","page":65,"kind":"fill","tags":["Practice"],"modelAnswer":"1. B: Bei der Entstehung einer Sucht ist Stress sehr relevant.\n      2. C: Jugendliche sind heute enorm gestresst.\n      3. A: Da sind mehrere Merkmale möglich.","fields":[{"label":"1","answers":["B: Bei der Entstehung einer Sucht ist Stress sehr relevant."]},{"label":"2","answers":["C: Jugendliche sind heute enorm gestresst."]},{"label":"3","answers":["A: Da sind mehrere Merkmale möglich."]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-091","solutionId":"b2-sol-091","chapter":4,"module":"Modul 3 · Im Netz","moduleIndex":3,"label":"A2D","title":"Im Netz","page":65,"kind":"fill","tags":["Practice","Grammar"],"modelAnswer":"Verb – Nomen – Präposition – gleiche – Bedeutung","fields":[{"label":"Answer","answers":["Verb – Nomen – Präposition – gleiche – Bedeutung"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-092","solutionId":"b2-sol-092","chapter":4,"module":"Modul 4 · Der kleine Unterschied","moduleIndex":4,"label":"A2B","title":"Der kleine Unterschied","page":67,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      Wertewandel bei Männern: fühlen sich heute seltener als Alleinernährer.\n      91 % der Frauen finden Erwerbsarbeit und eigenes Geld sehr wichtig.\n      Frauen wollen heute noch weniger den Rückzug in die Familie als vor 5 Jahren.\n      Unter 5 % der Frauen finden die Familie wichtiger als die eigene Erwerbstätigkeit.\n      93 % der Frauen wollen Kinder.\n      Über die Hälfte der befragten Frauen sieht durch Kinder immer noch ihre Chance auf Karriere\n      gefährdet.\n      Frauen mit Kindern fühlen sich beruflich benachteiligt.\n      Männer erleben die Gesellschaft als kinderfeindlich.\n      Familiengründung wird immer länger hinausgeschoben.\n      Frauen mit und ohne Kinder übernehmen mehr Hausarbeit als Männer.\n      Ein Drittel der Männer würde nicht für die Kindererziehung zum Hausmann werden.\n      Frauen und Männer mit schlechter Bildung bewerten heute ihre Chancen schlecht.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-093","solutionId":"b2-sol-093","chapter":4,"module":"Modul 4 · Der kleine Unterschied","moduleIndex":4,"label":"A2C","title":"Der kleine Unterschied","page":67,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      Finanzielles:\n      Männer: Wertewandel: wünschen sich heute stärker, dass Frauen viel verdienen; 76 % wollen,\n      dass die Frauen ihren Lebensunterhalt selbst verdienen / wollen nicht mehr Alleinverdiener\n      sein → verändert\n      Frauen: wollen Männer, die ihren Lebensunterhalt selbst verdienen; 91 % wollen selbst\n      erwerbstätig sein / eigenes Geld sehr wichtig → gleich geblieben\n      Karriere:\n      Männer: 1/3 würde nicht für Kindererziehung die Erwerbsarbeit unterbrechen → (keine\n      genaue Angabe. eher gleich geblieben)\n      Frauen: Trend nimmt zu: wollen auch weiter mit Familie berufstätig sein; heute mehr als\n      früher; unter 5 % ist Familie wichtiger als eigener Job; meinen, dass Unternehmen heute mehr\n      auf die Wünsche von Eltern eingehen; aber auch immer mehr Frauen glauben, dass man mit\n      Kindern keine Karriere machen kann (2007: 36 %, 2012: 53 %) → verändert\n      Kinder:\n      Frauen: Kinderwunsch auch heute noch gleich groß / 93 % wollen Nachwuchs → gleich\n      geblieben\n      Männer: Erleben die Gesellschaft als kinderfeindlich, bleiben deshalb unentschlossen →\n      (keine Angabe, ob gleich oder verändert)\n      Männer und Frauen: Denken zu über 70 %, dass sie es bereuen werden, keine Kinder zu\n      haben; schieben Kinderwunsch aber immer länger auf → verändert\n      Haushalt/Familie:\n      Frauen: übernehmen weiter die meisten Arbeiten sowie Pflege und Erziehung → gleich\n      geblieben\n      Männer: würden auch heute nicht oder nur kurz das Arbeitsleben mit der Kindererziehung\n      tauschen → gleich geblieben („bleiben Frauensache“)\n      Ausbildung:\n      Männer und Frauen: 2007 waren auch schlechter Ausgebildete noch selbstbewusst und\n      zufriedener, 2012 sehen sie nur schlechte Chancen für sich → verändert","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-094","solutionId":"b2-sol-094","chapter":4,"module":"Modul 4 · Der kleine Unterschied","moduleIndex":4,"label":"A3A","title":"Der kleine Unterschied","page":68,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"Inhalte wiedergeben            interessante Inhalte nennen     zustimmen\n      die eigene Meinung äußern      über eigene Erfahrungen         widersprechen/bezweifeln\n                                     berichten","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-095","solutionId":"b2-sol-095","chapter":4,"module":"Modul 4 · Der kleine Unterschied","moduleIndex":4,"label":"A5B","title":"Der kleine Unterschied","page":68,"kind":"fill","tags":["Practice"],"modelAnswer":"b–c–e","fields":[{"label":"Answer","answers":["b–c–e"]}],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-096","solutionId":"b2-sol-096","chapter":4,"module":"Modul 4 · Der kleine Unterschied","moduleIndex":4,"label":"A5C","title":"Der kleine Unterschied","page":68,"kind":"fill","tags":["Practice"],"modelAnswer":"1. getragene Socken ins Kopfkissen stecken und darauf schlafen\n      2. große Carrera-Bahn im Flur aufbauen\n\nFilm Blind geboren","fields":[{"label":"1","answers":["getragene Socken ins Kopfkissen stecken und darauf schlafen"]},{"label":"2","answers":["große Carrera-Bahn im Flur aufbauen Film Blind geboren"]}],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-097","solutionId":"b2-sol-097","chapter":4,"module":"Film · Blind geboren","moduleIndex":4,"label":"A2A","title":"Blind geboren","page":73,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Mögliche Lösung:\n      Kevin ist ein 11 Jahre alter Junge und seit der Geburt blind. Trotzdem fährt er, auch zum\n      Erstaunen seiner Eltern, Fahrrad, denn er kennt die Umgebung und hört, wo er langfährt, fährt\n      „nach Gefühl“. Als Kevin vier Monate alt war, erfuhren seine Eltern, dass er nie sehen würde –\n      und waren geschockt.","fields":[],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-098","solutionId":"b2-sol-098","chapter":4,"module":"Film · Blind geboren","moduleIndex":4,"label":"A2B","title":"Blind geboren","page":73,"kind":"fill","tags":["Practice","Listening"],"modelAnswer":"normal – Keyboard – sieben – Keyboard – E-Gitarre – ersten – chatten","fields":[{"label":"Answer","answers":["normal – Keyboard – sieben – Keyboard – E-Gitarre – ersten – chatten"]}],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-099","solutionId":"b2-sol-099","chapter":4,"module":"Film · Blind geboren","moduleIndex":4,"label":"A2C","title":"Blind geboren","page":73,"kind":"fill","tags":["Practice","Reading","Listening"],"modelAnswer":"1 Wie „sieht“ Kevin?: „sich vortasten und ausprobieren“ als Devise, „sieht“/tastet mit den\n      Händen, macht ein spezielles Mobilitätstraining, benutzt in unbekannter Umgebung einen\n      besonderen Stock, um Hindernisse zu erspüren\n      2 Wie verstehen sich Kevin und sein Bruder Dennis?: Dennis ist eine große Hilfe, stehen sich\n      nahe, Dennis ist stolz auf Kevin, findet ihn einen „guten Bruder“\n      3 Was machen die Eltern, um Kevin zu unterstützen?: ein Blindenerfahrungsseminar, in dem\n      sie mit verbundenen Augen in Kevins Welt eintauchen","fields":[{"label":"1","answers":["Wie „sieht“ Kevin?: „sich vortasten und ausprobieren“ als Devise, „sieht“/tastet mit den Händen, macht ein spezielles Mobilitätstraining, benutzt in unbekannter Umgebung einen besonderen Stock, um Hindernisse zu erspüren"]},{"label":"2","answers":["Wie verstehen sich Kevin und sein Bruder Dennis?: Dennis ist eine große Hilfe, stehen sich nahe, Dennis ist stolz auf Kevin, findet ihn einen „guten Bruder“"]},{"label":"3","answers":["Was machen die Eltern, um Kevin zu unterstützen?: ein Blindenerfahrungsseminar, in dem sie mit verbundenen Augen in Kevins Welt eintauchen"]}],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-100","solutionId":"b2-sol-100","chapter":4,"module":"Film · Blind geboren","moduleIndex":4,"label":"A3","title":"Blind geboren","page":74,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Mögliche Lösung (manche Adjektive passen auf mehrere Personen):\n          Kevin: entschieden – begabt – konzentriert – glücklich – schnell – vielseitig – neugierig –\n          leidenschaftlich – sicher – musikalisch – interessiert – selbstständig\n          Dennis: bewundernd – glücklich – stolz – verständnisvoll – hilfsbereit\n          Eltern: liebevoll – besorgt – bewundernd – geschockt – glücklich – stolz – vorausschauend –\n          ruhig – fürsorglich","fields":[],"film":true,"y0":0,"y1":650},{"id":"b2-ex-101","solutionId":"b2-sol-101","chapter":4,"module":"Film · Blind geboren","moduleIndex":4,"label":"A4","title":"Blind geboren","page":74,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Mögliche Lösung:\n          Gefühle: manchmal Sehnsucht, doch sehen zu können / er vermisst das Sehen, wenn er\n          traurig ist; sonst aber meistens optimistisch\n          Zukunftspläne: Programmierer (später als Hobby) und Musiker (später als Beruf)","fields":[],"film":true,"y0":320,"y1":980},{"id":"b2-ex-102","solutionId":"b2-sol-102","chapter":4,"module":"Film · Blind geboren","moduleIndex":4,"label":"A6A","title":"Blind geboren","page":74,"kind":"open","tags":["Practice","Vocabulary","Writing","Listening"],"modelAnswer":"Was kann man hier machen?: 90-minütige Tour komplett im Dunkeln, die Sinne schärfen\n          Idee der Ausstellung: Eintauchen in die Welt der Blinden/Sehbehinderten","fields":[],"film":true,"y0":0,"y1":900},{"id":"b2-ex-103","solutionId":"b2-sol-103","chapter":5,"module":"Auftakt","moduleIndex":0,"label":"A1C","title":"Auftakt","page":75,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. Geschichte, 2. Biologie/Medizin, 3. Biologie/Zoologie, 4. Physik/Mathematik,\n          5. Geschichte/Physik/Ingenieurwissenschaften, 6.Ernährungswissenschaft,\n          7. Archäologie/Geschichte/Kulturwissenschaft/Anthropologie, 8. Kulturwissenschaft/\n          Statistik/Soziologie/Medizin, 9. Biologie/Zoologie, 10. Geografie","fields":[{"label":"1","answers":["Geschichte"]},{"label":"2","answers":["Biologie/Medizin"]},{"label":"3","answers":["Biologie/Zoologie"]},{"label":"4","answers":["Physik/Mathematik"]},{"label":"5","answers":["Geschichte/Physik/Ingenieurwissenschaften"]},{"label":"6","answers":["Ernährungswissenschaft"]},{"label":"7","answers":["Archäologie/Geschichte/Kulturwissenschaft/Anthropologie"]},{"label":"8","answers":["Kulturwissenschaft/ Statistik/Soziologie/Medizin"]},{"label":"9","answers":["Biologie/Zoologie"]},{"label":"10","answers":["Geografie"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-104","solutionId":"b2-sol-104","chapter":5,"module":"Modul 1 · Wissenschaft für Kinder","moduleIndex":1,"label":"A1","title":"Wissenschaft für Kinder","page":77,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1 E, 2 D, 3 B, 4 A, 5 C","fields":[{"label":"1","answers":["E"]},{"label":"2","answers":["D"]},{"label":"3","answers":["B"]},{"label":"4","answers":["A"]},{"label":"5","answers":["C"]}],"film":false,"y0":0,"y1":760,"options":["A","B","C","D","E"]},{"id":"b2-ex-105","solutionId":"b2-sol-105","chapter":5,"module":"Modul 1 · Wissenschaft für Kinder","moduleIndex":1,"label":"A2A","title":"Wissenschaft für Kinder","page":77,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"Mögliche Lösung:\n          Kinder werden in Experimentierkursen an die Wissenschaft herangeführt und so wird ihre\n          Neugier für die Wissenschaft geweckt.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-106","solutionId":"b2-sol-106","chapter":5,"module":"Modul 1 · Wissenschaft für Kinder","moduleIndex":1,"label":"A2B","title":"Wissenschaft für Kinder","page":77,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. Sie experimentieren im Labor und führen wissenschaftliche Versuche durch. So verlieren\n          sie ihre Scheu vor der Forscherwelt.\n          2. Es gibt einen großen Bedarf an qualifiziertem Personal, aber zu wenig junge Deutsche in\n          den Studiengängen der Natur- oder Ingenieurswissenschaft; Mathematische und analytische\n          Fähigkeiten müssen früh erworben werden, damit sie sich voll entfalten können; Kinder sollten\n          also möglichst früh für die Wissenschaft begeistert werden.\n          3. Ganz praktisch und spielerisch: Erst stellen sie das Phänomen in einem einfachen\n          Experiment nach und sehen, was das Besondere daran ist. Dann erleben sie die Ursache für\n          das Verhalten des Wassers, indem sie sich selbst in einem Spiel wie „Wasserteilchen“\n          verhalten.","fields":[{"label":"1","answers":["Sie experimentieren im Labor und führen wissenschaftliche Versuche durch. So verlieren sie ihre Scheu vor der Forscherwelt."]},{"label":"2","answers":["Es gibt einen großen Bedarf an qualifiziertem Personal, aber zu wenig junge Deutsche in den Studiengängen der Natur- oder Ingenieurswissenschaft; Mathematische und analytische Fähigkeiten müssen früh erworben werden, damit sie sich voll entfalten können; Kinder sollten also möglichst früh für die Wissenschaft begeistert werden."]},{"label":"3","answers":["Ganz praktisch und spielerisch: Erst stellen sie das Phänomen in einem einfachen Experiment nach und sehen, was das Besondere daran ist. Dann erleben sie die Ursache für das Verhalten des Wassers, indem sie sich selbst in einem Spiel wie „Wasserteilchen“ verhalten."]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-107","solutionId":"b2-sol-107","chapter":5,"module":"Modul 1 · Wissenschaft für Kinder","moduleIndex":1,"label":"A3A","title":"Wissenschaft für Kinder","page":78,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"Präsens: werden + herangeführt\n          Präteritum: wurde + gegründet\n          Perfekt: ist + konzipiert worden\n          mit Modalverb: müssen + erworben werden","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-108","solutionId":"b2-sol-108","chapter":5,"module":"Modul 1 · Wissenschaft für Kinder","moduleIndex":1,"label":"A3B","title":"Wissenschaft für Kinder","page":78,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. Die Begeisterung der Kinder für die Wissenschaft muss möglichst früh geweckt werden.\n          (Z. 36/37)\n          2. In diesem Umfeld lässt sich die Scheu der Kinder vor der Forscherwelt leicht abbauen.\n          (Z. 13–15)\n          3. Auch im Kindergartenalter können bereits naturwissenschaftliche Experimente durchgeführt\n          werden. (Z. 44/45)\n          4. Naturwissenschaftliche Phänomene sind so viel besser verständlich. (Z. 18/19)","fields":[{"label":"1","answers":["Die Begeisterung der Kinder für die Wissenschaft muss möglichst früh geweckt werden. (Z."]},{"label":"36","answers":["/"]},{"label":"2","answers":["In diesem Umfeld lässt sich die Scheu der Kinder vor der Forscherwelt leicht abbauen. (Z."]},{"label":"3","answers":["Auch im Kindergartenalter können bereits naturwissenschaftliche Experimente durchgeführt werden. (Z."]},{"label":"44","answers":["/"]},{"label":"4","answers":["Naturwissenschaftliche Phänomene sind so viel besser verständlich. (Z."]},{"label":"18","answers":["/"]},{"label":"19","answers":[")"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-109","solutionId":"b2-sol-109","chapter":5,"module":"Modul 1 · Wissenschaft für Kinder","moduleIndex":1,"label":"A4","title":"Wissenschaft für Kinder","page":78,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      1. Kinder lassen sich leicht motivieren. / Kinder sind leicht zu motivieren. / Kinder sind leicht\n      motivierbar.\n      2. Viele Projekte für Kinder sind ohne staatliche Hilfe nicht finanzierbar. / Viele Projekte für\n      Kinder lassen sich ohne …. nicht finanzieren. / Viele Projekte sind ohne … nicht finanzierbar.\n      3. Die Aufgaben sind von den Kindern zu lösen.","fields":[],"film":false,"y0":320,"y1":980},{"id":"b2-ex-110","solutionId":"b2-sol-110","chapter":5,"module":"Modul 2 · Wer einmal lügt, …","moduleIndex":2,"label":"A1C","title":"Wer einmal lügt, …","page":79,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n                             wahr                                            nicht wahr\n       die Wahrheit, wahr, die Wahrheit sagen,             lügen, die Lüge, falsch, täuschen,\n       wahrsagen, die Wahrsagerin, richtig,                schwindeln, lügt wie gedruckt, Lügner,\n       wahrheitsgemäß, ungelogen, glaubhaft,               anlügen, belügen, das ist erlogen/das ist\n       sicher, aufrichtig, wahrhaftig, wahrlich,           erfunden, das ist geflunkert, unwahr, die\n       glaubhaft versichern, …                             Unwahrheit (sagen), lügnerisch, die\n                                                           Lügengeschichte, …","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-111","solutionId":"b2-sol-111","chapter":5,"module":"Modul 2 · Wer einmal lügt, …","moduleIndex":2,"label":"A2B","title":"Wer einmal lügt, …","page":79,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1b – 2c – 3a – 4b – 5a – 6a – 7c – 8a – 9b – 10b","fields":[{"label":"1","answers":["B"]},{"label":"2","answers":["C"]},{"label":"3","answers":["A"]},{"label":"4","answers":["B"]},{"label":"5","answers":["A"]},{"label":"6","answers":["A"]},{"label":"7","answers":["C"]},{"label":"8","answers":["A"]},{"label":"9","answers":["B"]},{"label":"10","answers":["B"]}],"film":false,"y0":430,"y1":1403,"options":["A","B","C"]},{"id":"b2-ex-112","solutionId":"b2-sol-112","chapter":5,"module":"Modul 3 · Ist da jemand?","moduleIndex":3,"label":"A1B","title":"Ist da jemand?","page":81,"kind":"fill","tags":["Practice"],"modelAnswer":"D1 – B2 – F3 – E4 – C5 – A6","fields":[{"label":"Answer","answers":["D1 – B2 – F3 – E4 – C5 – A6"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-113","solutionId":"b2-sol-113","chapter":5,"module":"Modul 3 · Ist da jemand?","moduleIndex":3,"label":"A1C","title":"Ist da jemand?","page":81,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Was?                              Wie?                               Warum?\n       Großstadt                         • U-Bahn voll mit                  • Pumpen fallen aus\n                                           Grundwasser                      • Natur erobert Städte zurück\n                                         • Häuser stürzen ein\n                                         • Straßen versinken, werden\n                                           zu neuen Flussbetten\n       Atomkraftwerke                    • fallen aus                       • niemand tankt Diesel auf\n                                         • Ansiedlung von Tieren            • Kühlsystem fällt aus\n       Tierwelt                          • Tiere vermehren sich             • keine Stromleitungen und\n                                         • Läuse, Ratten, Kakerlaken          Lichter mehr\n                                           etc. sterben aus                 • keiner, der sie mehr direkt\n                                                                              oder indirekt ernährt\n       Architektur                       • Brücke, Dämme, Städte etc.       • Natur erobert alles zurück\n                                           fallen zusammen, brechen\n                                           ein\n                                         • Tunnel unter Atlantik bleibt\n                                           bestehen\n       Metalle/Farben / radioaktives     • Blei, Plutonium und              • brauchen zig Tausende bis\n       Material / Kunststoffe              Plastiktüten gäbe es noch          Millionen Jahre, um\n                                           immer                              abgebaut zu werden\n                                                                            • für den Abbau von Plastik\n                                                                              müsste sich erst eine neue\n                                                                              Art von Bakterien entwickeln","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-114","solutionId":"b2-sol-114","chapter":5,"module":"Modul 3 · Ist da jemand?","moduleIndex":3,"label":"A2A","title":"Ist da jemand?","page":81,"kind":"open","tags":["Practice","Grammar","Writing"],"modelAnswer":"Indefinitpronomen\n       Nominativ      man              (k)einer/(k)eins/   niemand          jemand                irgendwer\n                                       (k)eine\n       Akkusativ      (k)einen/ (k)eins/ (k)eine           niemanden        jemanden              irgendwen\n       Dativ          (k)einem/ (k)einem/ (k)einer         niemandem        jemandem              irgendwem","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-115","solutionId":"b2-sol-115","chapter":5,"module":"Modul 3 · Ist da jemand?","moduleIndex":3,"label":"A2B","title":"Ist da jemand?","page":81,"kind":"open","tags":["Practice","Grammar","Writing"],"modelAnswer":"Die Indefinitpronomen beziehen sich auf Personen: man/jemand/irgendwer, Orte:\n      irgendwo/irgendwoher/irgendwohin sowie Zeiten: irgendwann und Dinge: irgendwas/etwas,\n      die nicht genauer definiert werden. einer/eins/eine können Personen und Dinge beschreiben.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-116","solutionId":"b2-sol-116","chapter":5,"module":"Modul 3 · Ist da jemand?","moduleIndex":3,"label":"A2D","title":"Ist da jemand?","page":81,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Person                           man, jemand, einer,              niemand, keiner\n                                        irgendwer\n       Ort                              irgendwo                         nirgendwo, nirgends\n                                        irgendwoher                      nirgendwoher\n                                        irgendwohin                      nirgendwohin\n       Zeit                             irgendwann                       nie, niemals\n       Dinge                            irgendetwas, etwas               nichts","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-117","solutionId":"b2-sol-117","chapter":5,"module":"Modul 4 · Gute Nacht","moduleIndex":4,"label":"A1B","title":"Gute Nacht","page":83,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n       verschlafen – zu spät aufwachen (Vorsilbe ver- weist darauf hin, dass etwas schiefgegangen\n       ist); noch einmal über etwas schlafen – noch einmal darüber nachdenken (man braucht und\n       erbittet noch einen Tag bzw. eine Nacht Zeit)\n       wie ein Murmeltier schlafen – tief und fest schlafen (Murmeltiere sind fürs Schlafen bekannt)\n       ausschlafen – so lange schlafen, bis man von selbst aufwacht und nicht mehr müde ist\n       (Vorsilbe aus- weist darauf hin, dass etwas zu Ende geführt wurde)\n       dösen – in der passenden Umgebung nicht richtig schlafen, aber fast, obwohl man eigentlich\n       keinen Schlaf brauchen würde (z. B. am Strand in der Sonne dösen, Adjektiv rammdösig)\n       ein Nickerchen machen – kurz schlafen, um sich auszuruhen (Verb (versehentlich) einnicken,\n       beim Nicken bewegt man den Kopf nach unten auf die Brust wie beim Schlafen, Nachsilbe\n       -chen deutet auf etwas Kleineres, Kurzes hin)\n       übernachten – über Nacht an einem Ort bleiben und schlafen (über weist darauf hin, dass eine\n       Zeitspanne überbrückt wird)\n       mit offenen Augen schlafen – nicht bei der Sache sein (man sieht aus, als wäre man wach,\n       reagiert aber nicht so)","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-118","solutionId":"b2-sol-118","chapter":5,"module":"Modul 4 · Gute Nacht","moduleIndex":4,"label":"A2A","title":"Gute Nacht","page":83,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"-b Mögliche Fragen:\n      Wie hat sich die Schlafdauer in den letzten 100 Jahren verändert? Warum gehen viele\n      Menschen spät ins Bett? Warum ist zu frühes Aufstehen nicht ratsam? Was kann man gegen\n      zu wenig Schlaf unternehmen? Wie gehen andere Kulturen mit Schlafmangel um?","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-119","solutionId":"b2-sol-119","chapter":5,"module":"Modul 4 · Gute Nacht","moduleIndex":4,"label":"A2C","title":"Gute Nacht","page":83,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n       • Keine Antwort: Warum schlafen Menschen ein Drittel ihres Lebens?\n       • Vor 100 Jahren: 9 Stunden Schlaf; vor 20 Jahren: 8; heute: 7 Stunden.\n       • Eine Nacht durcharbeiten → Zeichen der Leistungsfähigkeit\n       • Bis spät ausgehen → Lebenskunst\n       • Zu frühes Aufstehen: vor 8 Uhr kein vernünftiges Denken möglich.\n       • Dauerhafter Schlafmangel → Krankheit und Übergewicht.\n       • steigende Zahl von Menschen mit Schlafstörungen\n       • Kultur des Nickerchens: 20 Minuten helfen\n       • Japan: Mittagsschlaf im Büro positiv\n       • China: Schulkinder Mittagsschlaf\n       • Zu viel Schlaf → auch nicht gesund","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-120","solutionId":"b2-sol-120","chapter":5,"module":"Modul 4 · Gute Nacht","moduleIndex":4,"label":"A3A","title":"Gute Nacht","page":84,"kind":"fill","tags":["Practice"],"modelAnswer":"A–C–D–F","fields":[{"label":"Answer","answers":["A–C–D–F"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-121","solutionId":"b2-sol-121","chapter":5,"module":"Modul 4 · Gute Nacht","moduleIndex":4,"label":"A3B","title":"Gute Nacht","page":84,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Abschnitt 1: 1. f (haben … gehalten) – 2. r – 3. f (zweimal) – 4. r – 5. r\n       Abschnitt 2A:\n        Japan                            China                               USA\n        • Mittagsschlaf erwünscht        • Chinesen schlafen mittags         • Nickerchen üblicher als in\n        • er zeigt, dass die Leute hart • Grundrecht auf Mittags-            Deutschland\n        gearbeitet haben                 schlaf in der Verfassung            • große Firmen haben\n        • gehört zur Kultur              festgeschrieben                     Ruhezonen\n                                                                             • 1/3 der Unternehmen\n                                                                             erlauben „naps“ (Nickerchen)\n                                                                             zwischendurch\n\n\n\n\n      Abschnitt 2B:\n      1. 10–30 Minuten, 2. 30 %, 3. vor dem Schlafen Kaffee trinken, um nach ½ Stunde, wenn das\n      Koffein wirkt, gut wach zu werden","fields":[{"label":"1","answers":[":"]},{"label":"1","answers":["f"]},{"label":"2","answers":["r"]},{"label":"3","answers":["f"]},{"label":"4","answers":["r"]},{"label":"5","answers":["r Abschnitt"]},{"label":"2","answers":["A: Japan China USA • Mittagsschlaf erwünscht • Chinesen schlafen mittags • Nickerchen üblicher als in • er zeigt, dass die Leute hart • Grundrecht auf Mittags- Deutschland gearbeitet haben schlaf in der Verfassung • große Firmen haben • gehört zur Kultur festgeschrieben Ruhezonen •"]},{"label":"1","answers":["/"]},{"label":"3","answers":["der Unternehmen erlauben „naps“ (Nickerchen) zwischendurch Abschnitt"]},{"label":"2","answers":["B:"]},{"label":"30","answers":["Minuten"]},{"label":"30","answers":["%"]},{"label":"3","answers":["vor dem Schlafen Kaffee trinken, um nach ½ Stunde, wenn das Koffein wirkt, gut wach zu werden"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-122","solutionId":"b2-sol-122","chapter":5,"module":"Modul 4 · Gute Nacht","moduleIndex":4,"label":"A5A","title":"Gute Nacht","page":84,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"eine Reaktion einleiten\n      Meinung äußern und Argumente abwägen       Beispiele und eigene Erfahrungen anführen\n                                        zusammenfassen","fields":[],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-123","solutionId":"b2-sol-123","chapter":5,"module":"Modul 4 · Gute Nacht","moduleIndex":4,"label":"A6A","title":"Gute Nacht","page":85,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      Idee                                             Argumente\n      Entspannungskurse anbieten                       Stressabbau\n      Eigenes Fitnessstudio                            Gesundheit der Mitarbeiter fördern,\n                                                       Stressabbau\n      Firmenbus einführen                              umweltfreundlicher, Mitarbeiter kommen\n                                                       entspannter an\n      Kaffee-/Teeküche einrichten                      sozialer Treffpunkt, Förderung des\n                                                       Miteinanders, „die besten Ideen entstehen in\n                                                       der Küche“\n      gemeinsames Frühstück                            besseres Miteinander, Abbau von\n                                                       Spannungen unter einzelnen Mitarbeitern\n      Gleitzeit                                        Mitarbeiter können sich besser konzentrieren,\n                                                       Zufriedenheit wird gefördert, bessere Leistung\n      mehr Heimarbeit                                  bessere Familienverträglichkeit\n      Kinderbetreuung                                  bessere Familienverträglichkeit\n\nFilm An der Nase herumgeführt","fields":[],"film":false,"y0":0,"y1":900},{"id":"b2-ex-124","solutionId":"b2-sol-124","chapter":5,"module":"Film · An der Nase herumgeführt","moduleIndex":4,"label":"A2A","title":"An der Nase herumgeführt","page":89,"kind":"fill","tags":["Practice","Listening"],"modelAnswer":"A: 2. – 3. –5.\n      B: 1. – 4. – 6. – 7.","fields":[{"label":"5","answers":["B:"]},{"label":"7","answers":["."]}],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-125","solutionId":"b2-sol-125","chapter":5,"module":"Film · An der Nase herumgeführt","moduleIndex":4,"label":"A2B","title":"An der Nase herumgeführt","page":89,"kind":"open","tags":["Practice","Writing","Listening"],"modelAnswer":"stinken          schlecht riechen        gut riechen    duften\n      der Gestank                      riechen                der Duft / der Wohlgeruch","fields":[],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-126","solutionId":"b2-sol-126","chapter":5,"module":"Film · An der Nase herumgeführt","moduleIndex":4,"label":"A3","title":"An der Nase herumgeführt","page":90,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Über das Riechen: sind überall von Gerüchen umgeben; haben ca. 30 Mio. Riechzellen\n      (Nase); was wir riechen, beeinflusst uns, ob wir es wollen oder nicht\n      Wirkung: Düfte wirken unbewusst; führen zu ältesten Teilen des Gehirns (limbisches System),\n      dort sitzen Gedächtnis, Empfindungen, Emotionen, Stimmungen; unsere Entscheidungen\n      werden deshalb durch Düfte beeinflusst\n      Industrie: nutzt das mit Duftmarketing","fields":[],"film":true,"y0":0,"y1":650},{"id":"b2-ex-127","solutionId":"b2-sol-127","chapter":5,"module":"Film · An der Nase herumgeführt","moduleIndex":4,"label":"A4A","title":"An der Nase herumgeführt","page":90,"kind":"fill","tags":["Practice","Listening"],"modelAnswer":"Hans Hatt: 1. – 3. – 5.\n      Hans Voit: 2. – 4.","fields":[{"label":"5","answers":["Hans Voit:"]},{"label":"4","answers":["."]}],"film":true,"y0":320,"y1":980},{"id":"b2-ex-128","solutionId":"b2-sol-128","chapter":5,"module":"Film · An der Nase herumgeführt","moduleIndex":4,"label":"A4B","title":"An der Nase herumgeführt","page":90,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Duft Sonnencreme im Reisebüro: Erinnerung an letzten Urlaub\n      Geruch von Backwaren: Appetit anregen\n      Orangenduft beim Zahnarzt: Angst vorm Bohrer nehmen\n      Klimaanlage mit Pfefferminz: Ausdünstungen vieler Menschen bekämpfen\n      Mögliche weitere Beispiele: Sprühduft von reifen Früchten im Supermarkt auf noch unreifem\n      Obst: Käufer denken, die Frucht ist reif und aromatisch und kaufen sie.","fields":[],"film":true,"y0":320,"y1":980},{"id":"b2-ex-129","solutionId":"b2-sol-129","chapter":5,"module":"Film · An der Nase herumgeführt","moduleIndex":4,"label":"A5A","title":"An der Nase herumgeführt","page":90,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Mögliche Lösung:\n      Allergien; Übelkeit; Gewöhnung an Intensität des künstlichen Duftes / Abstumpfung der\n      Wahrnehmung bei normalen Gerüchen; gefährliche oder alarmierende Gerüche könnten\n      überlagert werden","fields":[],"film":true,"y0":610,"y1":1320},{"id":"b2-ex-130","solutionId":"b2-sol-130","chapter":5,"module":"Film · An der Nase herumgeführt","moduleIndex":4,"label":"A5B","title":"An der Nase herumgeführt","page":90,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Verbraucher/Menschen wissen nicht, dass sie beduftet werden, der Bürger hat aber immer\n      das Recht zu erfahren, was mit seinem Körper gemacht wird;\n      Forderung: Beduftung kenntlich machen (kann zu Problemen führen, z. B. Allergien); Risiken\n      muss man minimieren, also Stoffe nicht in die Luft einführen; Gesetzeslücke schließen","fields":[],"film":true,"y0":610,"y1":1320},{"id":"b2-ex-131","solutionId":"b2-sol-131","chapter":5,"module":"Film · An der Nase herumgeführt","moduleIndex":4,"label":"A7A","title":"An der Nase herumgeführt","page":90,"kind":"choice","tags":["Practice","Reading","Listening"],"modelAnswer":"1b – 2f – 3d – 4a – 5c – 6e","fields":[{"label":"1","answers":["B"]},{"label":"2","answers":["F"]},{"label":"3","answers":["D"]},{"label":"4","answers":["A"]},{"label":"5","answers":["C"]},{"label":"6","answers":["E"]}],"film":true,"y0":560,"y1":1403,"options":["A","B","C","D","E","F"]},{"id":"b2-ex-132","solutionId":"b2-sol-132","chapter":6,"module":"Auftakt","moduleIndex":0,"label":"A1B","title":"Auftakt","page":91,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Beispiele für Lösungsstrategien:\n          • Schlussfolgerungen ziehen durch lösungsrelevante Informationen (z. B. bei A Kurioses Nr. 2\n          „Der Vater von Monika“);\n          • System/Regel erkennen und weiterführen (z. B. bei D Buchstabenreihen ergänzen, Nr. 1\n          immer ein Buchstabe von hinten und einer von vorne des Alphabets);\n          • Spiegelungen erkennen und umsetzen (z. B. bei E Analogien bilden: Nr. 4 Wind : Sturm,\n          Sturm ist stärker als Wind, also muss das Verb stärker als reden sein),\n          • Basisfertigkeiten anwenden (alle kognitiven Fertigkeiten, Aufmerksamkeit, Konzentration,\n          genaues Lesen, Sprachverarbeitung, Kombination, Weltwissen)","fields":[{"label":"2","answers":["„Der Vater von Monika“); • System/Regel erkennen und weiterführen (z. B. bei D Buchstabenreihen ergänzen, Nr."]},{"label":"1","answers":["immer ein Buchstabe von hinten und einer von vorne des Alphabets); • Spiegelungen erkennen und umsetzen (z. B. bei E Analogien bilden: Nr."]},{"label":"4","answers":["Wind : Sturm, Sturm ist stärker als Wind, also muss das Verb stärker als reden sein), • Basisfertigkeiten anwenden (alle kognitiven Fertigkeiten, Aufmerksamkeit, Konzentration, genaues Lesen, Sprachverarbeitung, Kombination, Weltwissen)"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-133","solutionId":"b2-sol-133","chapter":6,"module":"Modul 1 · Fit für den Onlineeinkauf","moduleIndex":1,"label":"A1B","title":"Fit für den Onlineeinkauf","page":93,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Surfen im Internet                                  Einkaufen im Internet\n          der Browser                                         das Benutzerkonto\n          der Datenschutz                                     die Bestellung\n          der Doppelklick                                     die Bezahlung\n          die Firewall                                        der Datenschutz\n          das Passwort                                        der Doppelklick\n          die Startseite                                      die Kontodaten\n          die Suchmaschine                                    der Konsument\n          die Verschlüsselung                                 das Onlinebanking\n          das Virenschutzprogramm                             das Passwort\n          der Virus                                           der Rechnungsbetrag\n          die Webseite                                        die Verschlüsselung\n                                                              die Webseite","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-134","solutionId":"b2-sol-134","chapter":6,"module":"Modul 1 · Fit für den Onlineeinkauf","moduleIndex":1,"label":"A2A","title":"Fit für den Onlineeinkauf","page":93,"kind":"fill","tags":["Practice"],"modelAnswer":"1. Vorteile des Online-Shopping\n          2. Versand und Reklamation\n          3. Sicherheit im Netz\n          4. Zahlungsmöglichkeiten","fields":[{"label":"1","answers":["Vorteile des Online-Shopping"]},{"label":"2","answers":["Versand und Reklamation"]},{"label":"3","answers":["Sicherheit im Netz"]},{"label":"4","answers":["Zahlungsmöglichkeiten"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-135","solutionId":"b2-sol-135","chapter":6,"module":"Modul 1 · Fit für den Onlineeinkauf","moduleIndex":1,"label":"A2B","title":"Fit für den Onlineeinkauf","page":93,"kind":"fill","tags":["Practice"],"modelAnswer":"Vorteile: 1. – 3. – 5. (bis man bedient wird) – 7. – 9. – 10.\n          Nachteile: 1. – 5. – 6.","fields":[{"label":"5","answers":["(bis man bedient wird)"]},{"label":"10","answers":["Nachteile:"]},{"label":"6","answers":["."]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-136","solutionId":"b2-sol-136","chapter":6,"module":"Modul 1 · Fit für den Onlineeinkauf","moduleIndex":1,"label":"A2C","title":"Fit für den Onlineeinkauf","page":93,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Zahlungsmöglichkeiten                               Tipps für die Datensicherheit\n          • Rechnung                                          • aktuelles Virenschutzprogramm\n          • Vorkasse                                          • Firewall\n          • Nachnahme                                         • sicheres Passwort (keine realen Wörter\n          • Kreditkarte                                       oder Namen, 12 oder mehr Zeichen/wahllose\n          • E-Payment-Verfahren (z. B. PayPal)                Mischung, Groß- und Kleinbuchstaben)","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-137","solutionId":"b2-sol-137","chapter":6,"module":"Modul 1 · Fit für den Onlineeinkauf","moduleIndex":1,"label":"A3A","title":"Fit für den Onlineeinkauf","page":94,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"links: Wichtig ist der Vorgang. / Die Ware wird verpackt.\n          rechts: Wichtig ist der neue Zustand. / Die Ware ist verpackt.","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-138","solutionId":"b2-sol-138","chapter":6,"module":"Modul 1 · Fit für den Onlineeinkauf","moduleIndex":1,"label":"A3B","title":"Fit für den Onlineeinkauf","page":94,"kind":"open","tags":["Practice","Grammar","Writing"],"modelAnswer":"Passiv mit werden               Passiv mit sein\n          Bildung                           werden + Partizip II            sein + Partizip II\n          Bedeutung                         Vorgang, Aktion                 neuer Zustand, Resultat\n                                                                            eines Vorgangs","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-139","solutionId":"b2-sol-139","chapter":6,"module":"Modul 1 · Fit für den Onlineeinkauf","moduleIndex":1,"label":"A3C","title":"Fit für den Onlineeinkauf","page":94,"kind":"fill","tags":["Practice"],"modelAnswer":"2 wird – 3 ist – 4 wird – 5 ist – 6 Ist – 7 werden – 8 wird","fields":[{"label":"2","answers":["wird"]},{"label":"3","answers":["ist"]},{"label":"4","answers":["wird"]},{"label":"5","answers":["ist"]},{"label":"6","answers":["Ist"]},{"label":"7","answers":["werden"]},{"label":"8","answers":["wird"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-140","solutionId":"b2-sol-140","chapter":6,"module":"Modul 1 · Fit für den Onlineeinkauf","moduleIndex":1,"label":"A3D","title":"Fit für den Onlineeinkauf","page":94,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"2. Das Passwort war dreimal falsch eingegeben. Das Kundenkonto war gesperrt.\n      3. Die Geschäftsbedingungen waren nicht akzeptiert.\n      4. Der Bestellvorgang war nicht korrekt abgeschlossen.\n      5. Der Bestellvorgang war unterbrochen.","fields":[{"label":"2","answers":["Das Passwort war dreimal falsch eingegeben. Das Kundenkonto war gesperrt."]},{"label":"3","answers":["Die Geschäftsbedingungen waren nicht akzeptiert."]},{"label":"4","answers":["Der Bestellvorgang war nicht korrekt abgeschlossen."]},{"label":"5","answers":["Der Bestellvorgang war unterbrochen."]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-141","solutionId":"b2-sol-141","chapter":6,"module":"Modul 1 · Fit für den Onlineeinkauf","moduleIndex":1,"label":"A4","title":"Fit für den Onlineeinkauf","page":94,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Beispiele:\n      Das Geländer ist frisch gestrichen. Die Tür ist abgesperrt. Die Karten sind ausverkauft. Der\n      Zug ist verspätet. Die Fenster sind geschlossen. Die Rechnung ist bezahlt. Die Straße ist\n      blockiert. Die Internetverbindung ist unterbrochen. Die Hose ist frisch gewaschen.","fields":[],"film":false,"y0":320,"y1":980},{"id":"b2-ex-142","solutionId":"b2-sol-142","chapter":6,"module":"Modul 2 · Fit am Telefon","moduleIndex":2,"label":"A1","title":"Fit am Telefon","page":95,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Beispiele:\n      Telefonat mit dem Chef, mit dem Lehrer, mit einer Behörde, wenn es um etwas\n      Unangenehmes geht (z. B. Beschwerde bei der Telefongesellschaft, vom Vermieter etwas\n      einfordern) Warum? Sorge, sich nicht korrekt ausdrücken zu können, dass Wörter fehlen,\n      dass man den Ton nicht trifft, dass man den anderen nicht versteht.","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-143","solutionId":"b2-sol-143","chapter":6,"module":"Modul 2 · Fit am Telefon","moduleIndex":2,"label":"A2A","title":"Fit am Telefon","page":95,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Dialog 1 -                                         Dialog 2 +\n      • klingt, als wäre das Telefonat eine              • klingt freundlich\n      unangenehme Aufgabe                                • spricht klar und deutlich\n      • Fenster offen und viel Lärm                      • keine Hintergrundgeräusche\n      • unterbricht Telefonat, spricht mit jemand        • stellt sich vor und beschreibt die Situation,\n      anderem, konzentriert sich nicht auf das           sagt klar, was sie will • ist vorbereitet und hat\n      Telefonat                                          konkrete Fragen (Stift)\n      • ist nicht gut vorbereitet: weiß nicht genau,     • hat einen Terminvorschlag und nennt die\n      was er will, hat keinen Stift                      Adresse\n      • verhält sich nicht zuvorkommend: gibt die        • versetzt sich in den anderen hinein, fragt\n      Adresse nicht direkt durch, sondern verweist       nach, bestätigt, ist aufmerksam\n      auf die Internetseite, nennt am Ende seinen        • beachtet Regeln der Höflichkeit: benutzt\n      Namen nicht noch mal                               höfliche Formulierungen und spricht den\n      • unhöflich, geht nicht auf mögliche               anderen mit dem Namen an\n      Bedürfnisse des anderen ein (legt z. B. direkt\n      auf und wartet nicht ab, ob der andere noch\n      etwas sagen möchte)\n      • wirkt uninteressiert am Zustandekommen\n      des Treffens, fragt bei Namen und\n      Telefonnummer nicht noch mal nach/bestätigt\n      nicht, dass er verstanden hat","fields":[{"label":"1","answers":["Dialog"]},{"label":"2","answers":["+ • klingt, als wäre das Telefonat eine • klingt freundlich unangenehme Aufgabe • spricht klar und deutlich • Fenster offen und viel Lärm • keine Hintergrundgeräusche • unterbricht Telefonat, spricht mit jemand • stellt sich vor und beschreibt die Situation, anderem, konzentriert sich nicht auf das sagt klar, was sie will • ist vorbereitet und hat Telefonat konkrete Fragen (Stift) • ist nicht gut vorbereitet: weiß nicht genau, • hat einen Terminvorschlag und nennt die was er will, hat keinen Stift Adresse • verhält sich nicht zuvorkommend: gibt die • versetzt sich in den anderen hinein, fragt Adresse nicht direkt durch, sondern verweist nach, bestätigt, ist aufmerksam auf die Internetseite, nennt am Ende seinen • beachtet Regeln der Höflichkeit: benutzt Namen nicht noch mal höfliche Formulierungen und spricht den • unhöflich, geht nicht auf mögliche anderen mit dem Namen an Bedürfnisse des anderen ein (legt z. B. direkt auf und wartet nicht ab, ob der andere noch etwas sagen möchte) • wirkt uninteressiert am Zustandekommen des Treffens, fragt bei Namen und Telefonnummer nicht noch mal nach/bestätigt nicht, dass er verstanden hat"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-144","solutionId":"b2-sol-144","chapter":6,"module":"Modul 2 · Fit am Telefon","moduleIndex":2,"label":"A2B","title":"Fit am Telefon","page":95,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Tipps/Ratschläge:\n      gute Rahmenbedingungen             ruhiger Ort, möglichst geringe Hintergrundgeräusche (Radio\n                                         aus, Fenster zu) → besser für Konzentration\n      Vorbereitung                       die wichtigsten Fragen/Punkte notieren, Stift und Papier\n                                         bereithalten → keine Hektik, nichts vergessen, Gespräch\n                                         besser lenkbar\n      Verhalten während des              entspannte, aufrechte Körperhaltung, Hörer nicht zwischen\n      Telefongesprächs                   Brust und Kopf klemmen, nur telefonieren und nichts\n                                         nebenbei machen, lächeln, nicht tippen oder zwischendurch\n                                         mit anderen sprechen, sondern aufs Telefonat konzentrieren\n      Missverständnisse vermeiden        den Namen langsam und deutlich sprechen, nicht nuscheln,\n                                         beachten, dass der andere Zeit braucht zum Verstehen,\n                                         zwischendurch immer mal wieder kurz resümieren, am Ende\n                                         das Ergebnis kurz zusammenfassen\n      Ende des Telefongesprächs          sich bedanken, Gesprächspartner beim Namen nennen,\n                                         warten, bis das letzte Wort gesprochen ist","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-145","solutionId":"b2-sol-145","chapter":6,"module":"Modul 2 · Fit am Telefon","moduleIndex":2,"label":"A3","title":"Fit am Telefon","page":96,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"falsch verbunden: D – sich verbinden lassen: G – eine Nachricht hinterlassen: F – das\n       Gespräch einleiten: C – Fragen stellen: B – sich vergewissern: I – auf Fragen antworten: H –\n       kurze Zusammenfassung/Rückversicherung: E – das Gespräch beenden und sich\n       verabschieden: A","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-146","solutionId":"b2-sol-146","chapter":6,"module":"Modul 3 · Fit für die Kollegen","moduleIndex":3,"label":"A1B","title":"Fit für die Kollegen","page":97,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"Mögliche Lösung:\n       A: 3./4./6. – B: 1./10. – C: 4./12./13. – D: 5./6./9. – E: 7.","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-147","solutionId":"b2-sol-147","chapter":6,"module":"Modul 3 · Fit für die Kollegen","moduleIndex":3,"label":"A2A","title":"Fit für die Kollegen","page":97,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Maria T.                                                    Markus S.\n       nicht zufrieden: noch nicht eingelebt, denkt,               zufrieden; gute Atmosphäre, alle verstehen\n       nicht ins Team zu passen; keine Hilfe und                   sich gut, arbeitet gern dort; Chef bezieht\n       Unterstützung bei Fragen, keiner nimmt sich                 Mitarbeiter in Entscheidungen mit ein wie\n       Zeit; belehrender Ton der Kollegen                          gleichberechtigte Partner","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-148","solutionId":"b2-sol-148","chapter":6,"module":"Modul 3 · Fit für die Kollegen","moduleIndex":3,"label":"A2B","title":"Fit für die Kollegen","page":97,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"1. als ob, 2. als, 3. als wenn, 4. als","fields":[{"label":"1","answers":["als ob"]},{"label":"2","answers":["als"]},{"label":"3","answers":["als wenn"]},{"label":"4","answers":["als"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-149","solutionId":"b2-sol-149","chapter":6,"module":"Modul 3 · Fit für die Kollegen","moduleIndex":3,"label":"A2C","title":"Fit für die Kollegen","page":97,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"Verbstellung (des konjugierten Verbs): bei als ob und als wenn am Ende und bei als in\n       Position 2","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-150","solutionId":"b2-sol-150","chapter":6,"module":"Modul 3 · Fit für die Kollegen","moduleIndex":3,"label":"A2D","title":"Fit für die Kollegen","page":97,"kind":"fill","tags":["Practice"],"modelAnswer":"Irreales","fields":[{"label":"Answer","answers":["Irreales"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-151","solutionId":"b2-sol-151","chapter":6,"module":"Modul 3 · Fit für die Kollegen","moduleIndex":3,"label":"A2E","title":"Fit für die Kollegen","page":97,"kind":"fill","tags":["Practice","Grammar"],"modelAnswer":"irrealen – Konjunktiv II – Position 2 – am Ende","fields":[{"label":"Answer","answers":["irrealen – Konjunktiv II – Position 2 – am Ende"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-152","solutionId":"b2-sol-152","chapter":6,"module":"Modul 3 · Fit für die Kollegen","moduleIndex":3,"label":"A3","title":"Fit für die Kollegen","page":98,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. …, als ob sie die Chefin wäre.\n       2. …, als wüsste sie alles.\n       3. …, als ob sie nicht kritikfähig wäre.\n       4. …, als ob das Büro ihr Zuhause wäre.\n       5. …, als wenn auch andere Kollegen Probleme mit ihr hätten.","fields":[{"label":"1","answers":["…, als ob sie die Chefin wäre."]},{"label":"2","answers":["…, als wüsste sie alles."]},{"label":"3","answers":["…, als ob sie nicht kritikfähig wäre."]},{"label":"4","answers":["…, als ob das Büro ihr Zuhause wäre."]},{"label":"5","answers":["…, als wenn auch andere Kollegen Probleme mit ihr hätten."]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-153","solutionId":"b2-sol-153","chapter":6,"module":"Modul 4 · Fit für die Prüfung","moduleIndex":4,"label":"A1","title":"Fit für die Prüfung","page":99,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Beispiele:\n       Durchführung – Nervosität – lernen – aufgeregt sein – ein Blackout haben – Lernstrategien –\n       Angst haben – zu wenig Zeit haben – gutes Zeitmanagement – auswendig lernen – etc.","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-154","solutionId":"b2-sol-154","chapter":6,"module":"Modul 4 · Fit für die Prüfung","moduleIndex":4,"label":"A2A","title":"Fit für die Prüfung","page":99,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"1. e; 2. f, (a); 3. a, (f); 4. g; 5. c, e, f; 6. d, 7. h, 8. b","fields":[{"label":"1","answers":["e"]},{"label":"2","answers":["f, (a)"]},{"label":"3","answers":["a, (f)"]},{"label":"4","answers":["g"]},{"label":"5","answers":["c, e, f"]},{"label":"6","answers":["d"]},{"label":"7","answers":["h"]},{"label":"8","answers":["b"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-155","solutionId":"b2-sol-155","chapter":6,"module":"Modul 4 · Fit für die Prüfung","moduleIndex":4,"label":"A2B","title":"Fit für die Prüfung","page":99,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"Joanna: 2., 6. Mats: 3., 4. Anja: 1., 5.","fields":[{"label":"6","answers":["Mats:"]},{"label":"4","answers":["Anja:"]},{"label":"5","answers":["."]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-156","solutionId":"b2-sol-156","chapter":6,"module":"Modul 4 · Fit für die Prüfung","moduleIndex":4,"label":"A3A","title":"Fit für die Prüfung","page":100,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Text A: Vorbereitung\n       genau über Prüfung informieren; Überblick über Stoff verschaffen; Liste mit Themen; Zeitplan\n       (realistisch!); Pausen einplanen; Wiederholungszeit und Puffertage einplanen; am letzten Tag:\n       kein neuer Stoff, Gesamtwiederholung; der Freizeit nachgehen – Ablenkung;\n       Verunsicherungen meiden: Freunde mit Prüfungsangst, Alleskönner; schlimmstmöglichen Fall\n       durchspielen: wegen Durchfallen geht Welt nicht unter\n       Text B: Prüfungstag:\n       gut frühstücken; Traubenzucker mitnehmen; rechtzeitiges Losgehen; dem Tag positiv\n       entgegensehen; Aufgaben in Ruhe durchlesen; erst leichte, dann schwere machen; Antworten\n       noch mal durchlesen; Zeit richtig einteilen; ordentlich schreiben; für mündliche Prüfung das\n       Positive bewusst machen: kürzer als schriftliche, Korrektur der Antworten leichter möglich,\n       Nachfragen möglich, Prüfer sind auch Menschen","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-157","solutionId":"b2-sol-157","chapter":6,"module":"Modul 4 · Fit für die Prüfung","moduleIndex":4,"label":"A4A","title":"Fit für die Prüfung","page":100,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"Prüfungsangst, vor allem vor der mündlichen Prüfung","fields":[{"label":"Answer","answers":["Prüfungsangst, vor allem vor der mündlichen Prüfung"]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-158","solutionId":"b2-sol-158","chapter":6,"module":"Modul 4 · Fit für die Prüfung","moduleIndex":4,"label":"A4B","title":"Fit für die Prüfung","page":100,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1e – 2d – 3b – 4c – 5a","fields":[{"label":"1","answers":["E"]},{"label":"2","answers":["D"]},{"label":"3","answers":["B"]},{"label":"4","answers":["C"]},{"label":"5","answers":["A"]}],"film":false,"y0":320,"y1":980,"options":["A","B","C","D","E"]},{"id":"b2-ex-159","solutionId":"b2-sol-159","chapter":6,"module":"Modul 4 · Fit für die Prüfung","moduleIndex":4,"label":"A4C","title":"Fit für die Prüfung","page":100,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösungsreihenfolge Schritt 1:\n          1: sich für die E-Mail bedanken, 2: Verständnis für Lukas’ Situation äußern, 3: über eigene\n          Erfahrung berichten, 4: Tipps gegen Prüfungsangst geben, 5: einen Terminvorschlag für den\n          Besuch bei Lukas’ machen, 6: Lukas viel Glück wünschen","fields":[],"film":false,"y0":320,"y1":980},{"id":"b2-ex-160","solutionId":"b2-sol-160","chapter":6,"module":"Modul 4 · Fit für die Prüfung","moduleIndex":4,"label":"A5A","title":"Fit für die Prüfung","page":100,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n          Gruppe – pro: in der Gruppe können Fragen geklärt werden; wenn einer den anderen etwas\n          erklärt, wird es ihm dadurch klarer; mehr Spaß am Lernen, Angst vergeht dadurch; Foto\n          signalisiert, dass niemand allein ist mit seinem Problem\n          Gruppe – contra: in einer großen Gruppe geht der Einzelne unter; man hat in der Prüfung\n          auch nicht die Unterstützung einer Gruppe; hier wird man leicht abgelenkt.\n          Yoga – pro: Entspannung; neue Kraft fürs Weiterlernen; sich Pausen zu gönnen ist wichtig;\n          Foto spricht den Einzelnen direkt an\n          Yoga – contra: Thema „Prüfungsprobleme“ nicht zu erkennen; nicht jeder kann sich bei Stress\n          entspannen\n          Lernender Mann – pro: zeigt, dass man lernen muss; wirkt entspannt, bedeutet, dass er eine\n          gute Zeiteinteilung hat; Foto spricht den Einzelnen direkt an\n          Lernender Mann – contra: Foto sendet falsches Signal: Problemen soll man nicht als\n          Einzelkämpfer entgegentreten; Lernen allein hilft nicht gegen Prüfungsangst\n\nFilm Faszination Freeclimbing","fields":[],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-161","solutionId":"b2-sol-161","chapter":6,"module":"Film · Faszination Freeclimbing","moduleIndex":4,"label":"A3","title":"Faszination Freeclimbing","page":106,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Mögliche Lösung:\n          Landschaft/Natur: hoch, Berge, Fluss, Bäume, schön, einsam\n          Sport/Bewegung: Freeclimbing, gefährlich, hoch, gute Schuhe, Fingerspitzengefühl,\n          anspruchsvoll\n          Gefahr: hoch, ohne Seil, Abgrund, Nervenkitzel\n          Gefühle/Emotionen: Nervenkitzel, gefährlich, sehr hoch, Adrenalin, souverän","fields":[],"film":true,"y0":0,"y1":650},{"id":"b2-ex-162","solutionId":"b2-sol-162","chapter":6,"module":"Film · Faszination Freeclimbing","moduleIndex":4,"label":"A4A","title":"Faszination Freeclimbing","page":106,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Was sagt Robert Hahn über den Sport?: Konzentration nur aufs Klettern; totale Freiheit beim\n          Bewegen am Fels; man ist auf sich allein gestellt\n          Was fasziniert ihn daran?: totale Freiheit; Ehrlichkeit und Bedingungslosigkeit: dauernde\n          Entscheidung zwischen Können und Nichtkönnen, dabei Wissen, dass Nichtkönnen\n          Konsequenzen hat; Ausreden gelten hier nicht\n          Was sagt er zum Thema „Gefahr“?: man hofft, dass es hält; Fühlen des Wechselspiels: Kann\n          ich Griff halten oder nicht?; wenn nicht, stürzt man ab und ist tot\n          Warum benutzt er kein Seil?: Kräftemessen mit dem Berg ohne Kompromisse: will keine\n          Ausreden haben, sondern Ehrlichkeit und Bedingungslosigkeit am Berg erleben","fields":[],"film":true,"y0":320,"y1":980},{"id":"b2-ex-163","solutionId":"b2-sol-163","chapter":7,"module":"Auftakt","moduleIndex":0,"label":"A2","title":"Auftakt","page":108,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Beispiele:\n          Film, Comic, Skulptur, Malerei, Graffiti, Performance, Videokunst, Installation, Fotografie,\n          Literatur, Theater, Oper, Musical, Klassikkonzerte, Pop- und Rockmusik, experimentelle\n          Musik, Volksmusik, Kirchenmusik, Mode/Schneiderkunst, Design, Architektur, Land Art. „alles,\n          was im Museum ist“, Kinderbilder, Werke von psychisch Kranken (z. B. Prinzhorn-Sammlung),\n          Musikvideos, Quilts, Klöppelei, Klein- und Straßenkunst, Kostümbildnerei, Schnitzerei etc. Vgl.\n          auch Begriffe wie Braukunst, Orgelbaukunst, Kochkunst, Goldschmiedekunst usw.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-164","solutionId":"b2-sol-164","chapter":7,"module":"Modul 1 · Weltkulturerbe","moduleIndex":1,"label":"A2A","title":"Weltkulturerbe","page":109,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1441 Zimmer, 1.600.000 m2 Parkfläche, 7,6 Mio. Besucher jährlich, 1996 in Liste des\n          Weltkulturerbes der UNESCO, 17. Jahrhundert: Quelle, die dem Schloss den Namen gab,\n          wurde entdeckt, um 1800 Bau als Jagdschloss","fields":[{"label":"14","answers":["41 Zimmer"]},{"label":"60","answers":["0."]},{"label":"00","answers":["0 m2 Parkfläche"]},{"label":"6","answers":["Mio. Besucher jährlich"]},{"label":"19","answers":["96 in Liste des Weltkulturerbes der UNESCO"]},{"label":"17","answers":["Jahrhundert: Quelle, die dem Schloss den Namen gab, wurde entdeckt, um"]},{"label":"18","answers":["00 Bau als Jagdschloss"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-165","solutionId":"b2-sol-165","chapter":7,"module":"Modul 1 · Weltkulturerbe","moduleIndex":1,"label":"A2B","title":"Weltkulturerbe","page":109,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Kaiserliche Familie               Palmenhaus                    Tiergarten\n         die Schulpflicht einführen, die   drei verschiedene             das Tiergehege, die erste\n         prominentesten Bewohner,          Klimazonen, das größte        Giraffe, durch Gittern und\n         die Regierungszeit, die           Glashaus Europas, exotische   Mauern getrennt, Tiere\n         Verwaltung reformieren, die       Pflanzen, die                 besichtigen\n         Staatsgeschäfte führen, das       Pflanzensammlung, der\n         Hofzeremoniell einhalten          Schlossgarten","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-166","solutionId":"b2-sol-166","chapter":7,"module":"Modul 1 · Weltkulturerbe","moduleIndex":1,"label":"A2C","title":"Weltkulturerbe","page":109,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"-d Mögliche Lösung:\n      1. Kaiserin Maria Theresia: eine der bedeutendsten Frauenpersönlichkeiten der Geschichte;\n      Thronbesteigung 1740 mit 23 Jahren; regierte 40 Jahre; Reformen: Verwaltung,\n      Neuorganisation des Militärs, Einführung der Schulpflicht; 16 Kinder (11 Mädchen + 5\n      Jungen); sehr impulsiv und lebenslustig; Deutsch, Latein, Spanisch, Französisch, Italienisch;\n      liebte Musik, Kinder lernten Instrumente; Familiensinn; so gemütlich wie möglich; Schönbrunn\n      war ihr Sommerschloss – jeder hatte fünf Räume, Ehepaare zehn\n      2. Kaiserpavillon im Tiergarten: Erbaut 1751 unter Kaiser Franz I.; um Pavillon dreizehn\n      Tierhöfe; Mittelpavillon 1759 fertig; Kaiserpaar frühstückte dort manchmal; ab 1779 Öffnung\n      des Schlossgartens für das Volk, Besichtigung der Tiere möglich; im 19. Jahrhundert laufend\n      neue Tiere; Attraktionen: Elefanten, Kamele, Kängurus und andere Exoten; Aufsehen: 1828\n      erste Giraffe (Geschenk vom ägyptischen Vizekönig); Ende 19. Jahrhundert Umwandlung zu\n      großem zoologischen Garten – statt Mauern Gitter, um die Tiere besser zu sehen\n      3. Kaiser Franz Joseph und Sissi: prominenteste Bewohner; Heirat 24.4.1854 – Sissi war 17\n      Jahre alt und freiheitsliebend; Auseinandersetzungen mit Schwiegermutter Erzherzogin\n      Sophie; wollte aus „dem Mädchen vom Land“ ein Kaiserin machen, strenge Einhaltung des\n      Hofzeremoniells; Elisabeth ängstlich und unsicher, kein Widerstand; drei Kinder: Sophie,\n      Gisela, Rudolph – Wegnahme direkt nach der Geburt und zur Schwiegermutter; Franz Joseph\n      akzeptierte und unterstützte dies; später viele Reisen, Sissi wurde selbstbewusst, aber immer\n      rastloser; mit 60 Jahren erstochen von Gegner der Monarchie – Schock in ganz Europa;\n      Mythos lebt, auch durch viele Verfilmungen\n      4. Palmenhaus: Vorliebe der Kaiserfamilie für exotische Pflanzen; 1882 Palmenhaus im\n      Auftrag von Franz Joseph; größtes Glashaus Europas; Grundfläche von 2500 m2, 111 m lang,\n      28 m breit und 25 m hoch; 45.000 Glasscheiben; drei Teile: Mittelpavillon + 2 Seitenpavillons;\n      drei verschiedene Klimazonen: Kalthaus, wärmeres und Tropenhaus; 4.500 Pflanzenarten aus\n      allen Teilen der Erde; Stars: 23 m hohe Palme und größte Seerose der Welt: Durchmesser\n      von 1,20 m","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-167","solutionId":"b2-sol-167","chapter":7,"module":"Modul 1 · Weltkulturerbe","moduleIndex":1,"label":"A3A","title":"Weltkulturerbe","page":110,"kind":"fill","tags":["Practice"],"modelAnswer":"viele Wortwiederholungen","fields":[{"label":"Answer","answers":["viele Wortwiederholungen"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-168","solutionId":"b2-sol-168","chapter":7,"module":"Modul 1 · Weltkulturerbe","moduleIndex":1,"label":"A3B","title":"Weltkulturerbe","page":110,"kind":"open","tags":["Practice","Grammar","Writing"],"modelAnswer":"Sätze wurden mithilfe von Pronomen, Konnektoren, Ortsangaben und Präpositionaladverbien\n       verbunden und Bezüge hergestellt, sodass der Text sich nun flüssig und abwechslungsreich\n       liest. Wortwiederholungen wurden, auch durch die Verwendung eines Synonyms, vermieden.","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-169","solutionId":"b2-sol-169","chapter":7,"module":"Modul 1 · Weltkulturerbe","moduleIndex":1,"label":"A3C","title":"Weltkulturerbe","page":110,"kind":"fill","tags":["Practice","Grammar"],"modelAnswer":"1. Artikelwörter: der, das, die\n       2. Pronomen: es, er, ihnen; Relativpronomen (in) dem, (auf) den\n       3. Orts- und Zeitangaben: dort\n       4. Konnektoren: denn, weil, nicht nur …, sondern auch\n       5. Präpositionaladverbien: dazu, dabei\n       6. Synonyme: dieses imposante Bauwerk","fields":[{"label":"1","answers":["Artikelwörter: der, das, die"]},{"label":"2","answers":["Pronomen: es, er, ihnen; Relativpronomen (in) dem, (auf) den"]},{"label":"3","answers":["Orts- und Zeitangaben: dort"]},{"label":"4","answers":["Konnektoren: denn, weil, nicht nur …, sondern auch"]},{"label":"5","answers":["Präpositionaladverbien: dazu, dabei"]},{"label":"6","answers":["Synonyme: dieses imposante Bauwerk"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-170","solutionId":"b2-sol-170","chapter":7,"module":"Modul 2 · Kunstraub","moduleIndex":2,"label":"A1A","title":"Kunstraub","page":111,"kind":"fill","tags":["Practice"],"modelAnswer":"Diebe haben mehrere Gemälde (aus einem Berliner Museum) gestohlen.","fields":[{"label":"Answer","answers":["Diebe haben mehrere Gemälde (aus einem Berliner Museum) gestohlen."]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-171","solutionId":"b2-sol-171","chapter":7,"module":"Modul 2 · Kunstraub","moduleIndex":2,"label":"A1B","title":"Kunstraub","page":111,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Wann? – vergangene Nacht\n      Wo? – Brücke-Museum in Berlin-Dahlem\n      Wer? – unbekannte Täter, Gelegenheitsdiebe\n      Was? – Bilder von Heckel, Pechstein, Kirchner und Nolde, die sich in der Nähe des Fensters\n      befanden\n      Wert: rund 3,6 Mio. Euro","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-172","solutionId":"b2-sol-172","chapter":7,"module":"Modul 2 · Kunstraub","moduleIndex":2,"label":"A2A","title":"Kunstraub","page":111,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Ich-Erzähler ist Anwalt/Vertreter/Strafverteidiger des Verdächtigten. Ihn überraschen, 1.) dass\n      man ihm den aufsehenerregenden Fall anbietet (Zeile 8/9) und 2.) dass der Angeklagte so\n      leise hereinkommt, dass er ihn nicht hört (Zeile 12/13). (Es überrascht ihn auch, dass sein\n      schweigsamer Mandant plötzlich sagt, er wisse, wo das Bild ist; Z. 14/15.)","fields":[{"label":"1","answers":[") dass man ihm den aufsehenerregenden Fall anbietet (Zeile"]},{"label":"8","answers":["/"]},{"label":"9","answers":["und"]},{"label":"2","answers":[") dass der Angeklagte so leise hereinkommt, dass er ihn nicht hört (Zeile"]},{"label":"12","answers":["/"]},{"label":"13","answers":[". (Es überrascht ihn auch, dass sein schweigsamer Mandant plötzlich sagt, er wisse, wo das Bild ist; Z."]},{"label":"14","answers":["/"]},{"label":"15","answers":[")"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-173","solutionId":"b2-sol-173","chapter":7,"module":"Modul 2 · Kunstraub","moduleIndex":2,"label":"A2B","title":"Kunstraub","page":111,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. steht nicht im Text (siehe Zeile 27); 2. steht im Text (Zeile 23 + 25/26); 3. steht nicht im Text\n      (siehe Zeile 28/29; Mandant hat offenbar nicht den Auftrag fürs Verstecken erteilt); 4. steht im\n      Text (Zeile 33)","fields":[{"label":"1","answers":["steht nicht im Text (siehe Zeile"]},{"label":"2","answers":["steht im Text (Zeile"]},{"label":"23","answers":["+"]},{"label":"25","answers":["/"]},{"label":"3","answers":["steht nicht im Text (siehe Zeile"]},{"label":"28","answers":["/"]},{"label":"29","answers":["Mandant hat offenbar nicht den Auftrag fürs Verstecken erteilt)"]},{"label":"4","answers":["steht im Text (Zeile"]},{"label":"33","answers":[")"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-174","solutionId":"b2-sol-174","chapter":7,"module":"Modul 2 · Kunstraub","moduleIndex":2,"label":"A2C","title":"Kunstraub","page":111,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"1: Die Geschichte wird von Anwalt Huld als Ich-Erzähler erzählt (z. B. Zeile 2: „Manchmal\n      denke ich, …“)\n      2: „Der Tag fing an wie die letzten Tage … Alptraum“ (Zeile 2); „… hatte ich es im Radio\n      gehört, …“ (Zeile 4); „Ich schwitzte.“ (Zeile 16); „Ich war gerade dabei, mit ein Brot zu machen,\n      …“ (Zeile 31)\n      3: „Welcher Idiot klaut denn so bekannte Bilder?“ (Zeile 6)\n      4: „Es gibt drei Verdächtige ..“ (Zeile 6/7); „… weiß, wo das ‚Mädchen‘ ist“ (Zeile 15); Telefonat\n      Hauptkommissar und Anwalt (Zeile 19–26)\n      5: „Die Nacht war ein einziger Alptraum“ (Erschöpfung, Zeile 2); „Manchmal denke ich …\n      meine Nerven machen das einfach nicht mehr mit“ (Überforderung; Zeile 3); „Welcher Idiot\n      …Bilder“ (Verwunderung, Zeile 5); „Damit hatte ich im Traum nicht gerechnet“ (Überraschung;\n      Zeile8/9); „fast fiel mir mein Notizblock runter – das war mir noch nie passiert“ (Erschrecken,\n      Zeile 13); „Ich schwitzte“ (Nervosität, Zeile 16); „Wollte er mir sagen, … war?“ (Gedanke,\n      17/18); „Der Anruf war mir nicht leicht gefallen“ (Zeile 27); „… als mir alles klar wurde … es\n      konnte also nur um Erpressung gehen …“ (Gedanken, Zeile 31)","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-175","solutionId":"b2-sol-175","chapter":7,"module":"Modul 3 · Sprachensterben","moduleIndex":3,"label":"A2A","title":"Sprachensterben","page":113,"kind":"fill","tags":["Practice"],"modelAnswer":"1 Ein Beispiel für das Sprachensterben; 2 Globale Sprachen auf dem Vormarsch; 3 Sich\n      anpassen oder sterben; 4 Gefühle sind nicht übersetzbar","fields":[{"label":"1","answers":["Ein Beispiel für das Sprachensterben"]},{"label":"2","answers":["Globale Sprachen auf dem Vormarsch"]},{"label":"3","answers":["Sich anpassen oder sterben"]},{"label":"4","answers":["Gefühle sind nicht übersetzbar"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-176","solutionId":"b2-sol-176","chapter":7,"module":"Modul 3 · Sprachensterben","moduleIndex":3,"label":"A2B","title":"Sprachensterben","page":113,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Gründe für das Sprachensterben:\n      Der letzte Sprecher stirbt. (Zeile 1/2)\n      Ein Volk entscheidet, die eigene Sprache nicht mehr an die nächste Generation\n      weiterzugeben, sondern eine „nützlichere“ mit mehr Sprechern (Zeile 14–19 und 48–50)\n      Sprachen, die sich nicht anpassen, sterben (Zeile 28–31)\n      Sprachen verändern sich so sehr, dass die Ursprungssprache von den modernen Sprechern\n      nicht mehr verstanden wird, z. B. Latein (Z. 39–41)\n      Sprachen werden überwiegend mündlich, ohne Schriftzeugnisse vermittelt (Zeile 52–56).","fields":[{"label":"1","answers":["/"]},{"label":"2","answers":["Ein Volk entscheidet, die eigene Sprache nicht mehr an die nächste Generation weiterzugeben, sondern eine „nützlichere“ mit mehr Sprechern (Zeile"]},{"label":"19","answers":["und"]},{"label":"50","answers":["Sprachen, die sich nicht anpassen, sterben (Zeile"]},{"label":"31","answers":["Sprachen verändern sich so sehr, dass die Ursprungssprache von den modernen Sprechern nicht mehr verstanden wird, z. B. Latein (Z."]},{"label":"41","answers":["Sprachen werden überwiegend mündlich, ohne Schriftzeugnisse vermittelt (Zeile"]},{"label":"56","answers":["."]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-177","solutionId":"b2-sol-177","chapter":7,"module":"Modul 3 · Sprachensterben","moduleIndex":3,"label":"A3A","title":"Sprachensterben","page":114,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. Dadurch, dass Samuel Taylor starb, starb auch seine Sprache.\n      2. Sprachen sterben oft dadurch, dass eine Muttersprache nicht an die nächste Generation\n      weitergegeben wird.\n      3. Oft schafft man eine genaue Übersetzung auch nicht, indem man ein Wörterbuch benutzt.\n      4. Die genauen Bedeutungsnuancen kann man nur erlernen, indem man unter den Eskimos\n      lebt.)","fields":[{"label":"1","answers":["Dadurch, dass Samuel Taylor starb, starb auch seine Sprache."]},{"label":"2","answers":["Sprachen sterben oft dadurch, dass eine Muttersprache nicht an die nächste Generation weitergegeben wird."]},{"label":"3","answers":["Oft schafft man eine genaue Übersetzung auch nicht, indem man ein Wörterbuch benutzt."]},{"label":"4","answers":["Die genauen Bedeutungsnuancen kann man nur erlernen, indem man unter den Eskimos lebt.)"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-178","solutionId":"b2-sol-178","chapter":7,"module":"Modul 3 · Sprachensterben","moduleIndex":3,"label":"A3B","title":"Sprachensterben","page":114,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"1. zwei, Hauptsatz, Nebensatz; 2. kausale; 3. Nebensatz","fields":[{"label":"1","answers":["zwei, Hauptsatz, Nebensatz"]},{"label":"2","answers":["kausale"]},{"label":"3","answers":["Nebensatz"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-179","solutionId":"b2-sol-179","chapter":7,"module":"Modul 4 · Das Haus am Meer","moduleIndex":4,"label":"A2B","title":"Das Haus am Meer","page":115,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1. a, 2. b, 3. b, 4. a, 5. a","fields":[{"label":"1","answers":["a"]},{"label":"2","answers":["b"]},{"label":"3","answers":["b"]},{"label":"4","answers":["a"]},{"label":"5","answers":["a"]}],"film":false,"y0":430,"y1":1403,"options":["A","B","C"]},{"id":"b2-ex-180","solutionId":"b2-sol-180","chapter":7,"module":"Modul 4 · Das Haus am Meer","moduleIndex":4,"label":"A3A","title":"Das Haus am Meer","page":116,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Betreten des Hauses: richtiges Haus, aber Schloss ausgetauscht/neu, Zugang über die\n      Terrasse, äußere Holztüren unverschlossen, innere Glastüren nur angelehnt, Tür schwingt\n      auf, Raum erwacht wie aus Mittagsschlaf, ihre Schatten „schleichen sich“ vor ihren Körpern\n      ins Haus\n      Im Haus: Haus wie beseelt/bewohnt, als wäre der Geist des Onkels noch da, als wäre der\n      Onkel nur kurz weg, frische Schuhabdrücke auf dem Boden","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-181","solutionId":"b2-sol-181","chapter":7,"module":"Modul 4 · Das Haus am Meer","moduleIndex":4,"label":"A3B","title":"Das Haus am Meer","page":116,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösungen:\n      der Onkel; ein Nachbar aus dem Dorf; jemand, der Felix kennt; eine vertraute Person, die der\n      Onkel kannte; ein Einbrecher; ein Untermieter, von dem sie nichts wussten; ein Hausbesetzer;\n      Felix‘ Vater","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-182","solutionId":"b2-sol-182","chapter":7,"module":"Modul 4 · Das Haus am Meer","moduleIndex":4,"label":"A3C","title":"Das Haus am Meer","page":116,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      1. Er fühlt sich plötzlich, als ob er wieder ein Kind wäre; viele Erinnerungen und Gefühle aus\n      seiner Kindheit sind plötzlich sehr präsent.\n      2. Er bemerkt in dem Moment, dass die Situation gefährlich sein könnte, und ist alarmiert.","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-183","solutionId":"b2-sol-183","chapter":7,"module":"Modul 4 · Das Haus am Meer","moduleIndex":4,"label":"A4A","title":"Das Haus am Meer","page":116,"kind":"fill","tags":["Practice"],"modelAnswer":"siegessicher – selbstbewusst – gepflegt – alternd","fields":[{"label":"Answer","answers":["siegessicher – selbstbewusst – gepflegt – alternd"]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-184","solutionId":"b2-sol-184","chapter":7,"module":"Modul 4 · Das Haus am Meer","moduleIndex":4,"label":"A5B","title":"Das Haus am Meer","page":116,"kind":"fill","tags":["Practice"],"modelAnswer":"Felix","fields":[{"label":"Answer","answers":["Felix"]}],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-185","solutionId":"b2-sol-185","chapter":7,"module":"Modul 4 · Das Haus am Meer","moduleIndex":4,"label":"A5C","title":"Das Haus am Meer","page":116,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      1. um ihn nicht mehr sehen zu müssen, er ist auf der Reise „erwachsener“ geworden, will\n      doch auch mal an etwas festhalten, will sich gegen seinen dominanten Vater durchsetzen\n      2. angriffslustig, bestimmt, aggressiv, verbissen, fordernd, konzentriert, am Ende ungläubig\n      3. Der Vater kann nicht verlieren (will keine Niederlage eingestehen) und hört deshalb vorher\n      auf.","fields":[],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-186","solutionId":"b2-sol-186","chapter":7,"module":"Modul 4 · Das Haus am Meer","moduleIndex":4,"label":"A7","title":"Das Haus am Meer","page":117,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      1967 in Hessen geboren; Eltern ließen sich scheiden, daher viel umgezogen; Schwierigkeiten\n      in der Schule, u. a. von einer Schule geflogen; ein Auslandsjahr in Amerika während der\n      Schulzeit; Studium verschiedener Fächer in Marburg und Berlin, hat einen Abschluss in\n      Musikwissenschaften und Anglistik; hat als Chorleiter, Basketballtrainer, Redakteur und\n      Handwerker gearbeitet; seit 2001 Schriftsteller (Buchveröffentlichungen u. a.: „Die\n      Gottespartitur“, „Wenn nicht, dann jetzt“); von 2003 bis 2008 Dozent für kreatives Schreiben\n      an der Freien Universität Berlin; arbeitet auch als Übersetzer; ist Mitinhaber der Buchhandlung\n      Uslar & Rai in Berlin","fields":[],"film":false,"y0":560,"y1":1403},{"id":"b2-ex-187","solutionId":"b2-sol-187","chapter":7,"module":"Modul 4 · Das Haus am Meer","moduleIndex":4,"label":"A8B","title":"Das Haus am Meer","page":118,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Sport-/Musikveranstaltung        Reise                            Buch/Film\n       Die Veranstaltung war letzten    Ich wollte nach … fahren.        Es geht um …\n       Sommer / letztes                 Ich war in …                     Dabei geht es um …\n       Wochenende / … im … / in         Ich bin mit dem Bus/Flug-        Die Schauspieler sind … / …\n       der …                            zeug/Zug/Schiff/Rad/ … nach      spielt mit.\n       Ich war in …                     … gefahren                       Der Autor/Regisseur ist …\n       Der FC … hat gegen …             Eine berühmte/bekannte           Natürlich habe ich mir auch\n       gespielt.                        Attraktion ist …                 … angesehen.\n       Das Konzert war von …            Natürlich habe ich mir auch      Das Buch / Der Film ist\n       … hat/haben gespielt.            … angesehen.                     von …\n       … war auch mit dabei.            Ich war … Wochen\n                                        unterwegs.\n                                        … war auch mit dabei.\n\nFilm Kunstwerke auf ehemaligen Abraumhalden","fields":[],"film":false,"y0":0,"y1":1403},{"id":"b2-ex-188","solutionId":"b2-sol-188","chapter":7,"module":"Film · Kunstwerke auf ehemaligen Abraumhalden","moduleIndex":4,"label":"A1C","title":"Kunstwerke auf ehemaligen Abraumhalden","page":121,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Mögliche Lösung:\n      Das Ruhrgebiet, in dem sehr viele Menschen wohnen, war früher ein bedeutendes Steinkohle-\n      abbaugebiet und eine Industrieregion, in der Stahl produziert wurde. Mit der Krise in den 60er-\n      Jahren mussten viele Zechen schließen, wodurch sich ein Strukturwandel ergab, so dass viele\n      Industrieanlagen heute Kultureinrichtungen sind und viele Freizeitmöglichkeiten bieten.","fields":[],"film":true,"y0":0,"y1":760},{"id":"b2-ex-189","solutionId":"b2-sol-189","chapter":7,"module":"Film · Kunstwerke auf ehemaligen Abraumhalden","moduleIndex":4,"label":"A2","title":"Kunstwerke auf ehemaligen Abraumhalden","page":121,"kind":"open","tags":["Practice","Vocabulary","Writing","Listening"],"modelAnswer":"Kunst, Sport, Bergbau, Veränderung, Abfall, Natur, Industrie, Geschichte, Vergangenheit,\n          Theater","fields":[],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-190","solutionId":"b2-sol-190","chapter":7,"module":"Film · Kunstwerke auf ehemaligen Abraumhalden","moduleIndex":4,"label":"A3A","title":"Kunstwerke auf ehemaligen Abraumhalden","page":122,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"A: gefällt: viel Grün; B: gefällt: dass so Schönes aus „Abfall“ hergestellt wurde; C: Halden als\n          Mountainbikerevier, es gibt natürliche Berge, aber auch die Halden, Biken dort macht Spaß","fields":[],"film":true,"y0":0,"y1":650},{"id":"b2-ex-191","solutionId":"b2-sol-191","chapter":7,"module":"Film · Kunstwerke auf ehemaligen Abraumhalden","moduleIndex":4,"label":"A3B","title":"Kunstwerke auf ehemaligen Abraumhalden","page":122,"kind":"fill","tags":["Practice","Reading","Listening"],"modelAnswer":"1. ca. 100 Halden\n          2. Die Natur war im Ruhgebiet nicht so wichtig wie die Industrie\n          3. wollen nicht mehr auf die Halden verzichten\n          4. Ende 2018 wird in Deutschland auch die Zeche Prosper-Haniel geschlossen.","fields":[{"label":"1","answers":["ca."]},{"label":"10","answers":["0 Halden"]},{"label":"2","answers":["Die Natur war im Ruhgebiet nicht so wichtig wie die Industrie"]},{"label":"3","answers":["wollen nicht mehr auf die Halden verzichten"]},{"label":"4","answers":["Ende"]},{"label":"20","answers":["18 wird in Deutschland auch die Zeche Prosper-Haniel geschlossen."]}],"film":true,"y0":0,"y1":650},{"id":"b2-ex-192","solutionId":"b2-sol-192","chapter":7,"module":"Film · Kunstwerke auf ehemaligen Abraumhalden","moduleIndex":4,"label":"A4B","title":"Kunstwerke auf ehemaligen Abraumhalden","page":122,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Name                Künstler           Ort                Bedeutung              Material\n           A    Himmelstreppe                          Halde Rhein-                              (zu sehen:)\n                                                       Elbe                                      Steine\n           B    Tiger and Turtle                       Duisburg           Gegensatz\n                                                                          Schnelligkeit\n                                                                          und\n                                                                          Langsamkeit\n           C                        der Baske          Halde Haniel       wie Totems             alte, bunt\n                                    Agustín Ibarolla                                             bemalte\n                                                                                                 Bahnschwellen","fields":[],"film":true,"y0":320,"y1":980},{"id":"b2-ex-193","solutionId":"b2-sol-193","chapter":8,"module":"Auftakt","moduleIndex":0,"label":"A1","title":"Auftakt","page":123,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n          A: Sport: Gewinn der Fußballweltmeisterschaft durch die deutsche Fußballelf im Jahr 2014)\n          B: Medizin/Physik: Entdeckung der Röntgenstrahlen\n          C: Wissenschaft/Psychologie (hier könnten L auch Politik oder Journalismus nennen, wenn sie\n          Freud nicht (er)kennen): Sigmund Freud begründet die Psychoanalyse\n          D: Politik/Geschichte: DDR-Bürger versuchen 1989 die Grenze zu überwinden\n          E: Politik/Geschichte: Unterzeichnung der Urkunde über die bedingungslose Kapitulation der\n          Deutschen am Ende des Zweiten Weltkriegs\n          F: Natur/Katastrophen: Jahrhunderthochwasser der Elbe im Jahr 2002, hier in Dresden\n          G: /Politik/Grundrechte/Verkehrswesen: Demonstration gegen den Neubau der Stuttgarter\n          Hauptbahnhofs\n          H: Ernährungswesen/Lebensmittelkunde: Erfindung der Maggi-Schnellgerichte","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-194","solutionId":"b2-sol-194","chapter":8,"module":"Auftakt","moduleIndex":0,"label":"A2A","title":"Auftakt","page":124,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1B – 2A – 3F – 4E – 5H – 6C – 7G – 8D","fields":[{"label":"1","answers":["B"]},{"label":"2","answers":["A"]},{"label":"3","answers":["F"]},{"label":"4","answers":["E"]},{"label":"5","answers":["H"]},{"label":"6","answers":["C"]},{"label":"7","answers":["G"]},{"label":"8","answers":["D"]}],"film":false,"y0":430,"y1":1403,"options":["A","B","C","D","E","F","G","H"]},{"id":"b2-ex-195","solutionId":"b2-sol-195","chapter":8,"module":"Modul 1 · Geschichte erleben","moduleIndex":1,"label":"A1B","title":"Geschichte erleben","page":125,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n          Orte: Burg, Stadt, Dorf\n          Personen: Bauer, Krieger, Ritter, Handwerker, Musikant, Knecht, Magd, Burgdame\n          Merkmale der Zeit: Armut, Kampf, Kälte, Krankheit\n          Besonderes Ereignis der Zeit: Turnier, Waffe, Kampf","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-196","solutionId":"b2-sol-196","chapter":8,"module":"Modul 1 · Geschichte erleben","moduleIndex":1,"label":"A1C","title":"Geschichte erleben","page":125,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n          1. … Schulklassen, Familien und andere Personen, aber auch für historische Romane und\n          Filme sowie für Forscher.\n          2. .. die Menschen hatten damals Angst vor Krankheit und Tod, lebten in Unfreiheit, in\n          Dunkelheit, Kälte und mit wenig Bildung.\n          3. … die Rollenspieler in unsere sichere Welt zurückkehren können und es nur für kurze Zeit\n          und ohne ernste Konsequenzen ist.","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-197","solutionId":"b2-sol-197","chapter":8,"module":"Modul 1 · Geschichte erleben","moduleIndex":1,"label":"A2A","title":"Geschichte erleben","page":125,"kind":"open","tags":["Practice","Grammar","Writing"],"modelAnswer":"Nomen                         Präposition             Nomen                   Präposition\n        das Interesse                 für + A.                das Maß                 an + D.\n        die Vorstellung               von + D.                die Erinnerung          an + A.\n        die Faszination               für + A.                der Beitrag             zu + D.\n        die Antwort                   auf + A.                der Gegensatz           zu + D.\n        die Angst                     vor + D.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-198","solutionId":"b2-sol-198","chapter":8,"module":"Modul 1 · Geschichte erleben","moduleIndex":1,"label":"A2B","title":"Geschichte erleben","page":125,"kind":"open","tags":["Practice","Grammar","Writing"],"modelAnswer":"Nomen                         Präposition             Verb                    Präposition\n        das Interesse                 für + A.                sich interessieren      für + A.\n        die Vorstellung               von + D.                sich vorstellen         -\n        die Faszination               für + A.                faszinieren             -\n        die Antwort                   auf + A.                antworten               auf + A.\n        die Angst                     vor + D.                sich ängstigen          vor + D.\n        das Maß                       an + D.                 messen                  von + D.\n        die Erinnerung                an + A.                 sich erinnern           an + A.\n        der Beitrag                   zu + D.                 beitragen               zu + D.\n        der Gegensatz                 zu + D.                 -                       -","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-199","solutionId":"b2-sol-199","chapter":8,"module":"Modul 1 · Geschichte erleben","moduleIndex":1,"label":"A2C","title":"Geschichte erleben","page":125,"kind":"fill","tags":["Practice"],"modelAnswer":"abhängig von – interessiert an (nicht: für!) – neugierig auf – hilfreich bei – verwundert über","fields":[{"label":"Answer","answers":["abhängig von – interessiert an (nicht: für!) – neugierig auf – hilfreich bei – verwundert über"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-200","solutionId":"b2-sol-200","chapter":8,"module":"Modul 2 · 26. 10. – Ein Tag in der Geschichte","moduleIndex":2,"label":"A1A","title":"26. 10. – Ein Tag in der Geschichte","page":127,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"1. Machtwechsel in Deutschland, 2. Ausgezeichnete Band, 3. Eine Republik feiert, 4. Hilfe aus\n       aller Welt, 5. Durchbruch in der Kommunikation","fields":[{"label":"1","answers":["Machtwechsel in Deutschland"]},{"label":"2","answers":["Ausgezeichnete Band"]},{"label":"3","answers":["Eine Republik feiert"]},{"label":"4","answers":["Hilfe aus aller Welt"]},{"label":"5","answers":["Durchbruch in der Kommunikation"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-201","solutionId":"b2-sol-201","chapter":8,"module":"Modul 2 · 26. 10. – Ein Tag in der Geschichte","moduleIndex":2,"label":"A1B","title":"26. 10. – Ein Tag in der Geschichte","page":127,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Wann?         Wo?                    Wer?                      Was?\n        1. 1998       Bonn/Deutschland       Gerhard Schröder,         SPD wird bei Bundestagswahl\n                                             Helmut Kohl               stärkste Fraktion, Bundeskanzler\n                                                                       Kohl wird aus Amt entlassen\n        2. 1965       England                Königin Elisabeth II.,    Auszeichnung der Beatles:\n                                             die Beatles, John         „Member of the British Empire“,\n                                             Lennon                    John Lennon: Rückgabe des\n                                                                       Ordens aus Protest an Beteiligung\n                                                                       von GB an Krieg\n        3. 1965       Österreich             alle                      Nationalfeiertag („Ehrentag des\n                                             Österreicher/innen        unabhängigen Landes Österreich“),\n                                                                       feiert die immerwährende\n                                                                       Neutralität des Landes nach einem\n                                                                       Gesetz von 1955, arbeitsfrei\n        4. 1863       Genf/Schweiz           sozial engagierte         internationale Konferenz sozial\n                                             Gruppen, Henri            engagierter Gruppen, Dunant\n                                             Dunant                    initiiert eine internationale\n                                                                       Hilfsorganisation: später das Rote\n                                                                       Kreuz / der Rote Halbmond\n        5. 1861       Frankfurt am Main/     Johann Philipp Reis       Präsentation eines\n                      Deutschland                                      „Fernsprechgerätes“: Telefon,\n                                                                       Sensation, Fachwelt begeistert","fields":[{"label":"19","answers":["98 Bonn/Deutschland Gerhard Schröder, SPD wird bei Bundestagswahl Helmut Kohl stärkste Fraktion, Bundeskanzler Kohl wird aus Amt entlassen"]},{"label":"19","answers":["65 England Königin Elisabeth II., Auszeichnung der Beatles: die Beatles, John „Member of the British Empire“, Lennon John Lennon: Rückgabe des Ordens aus Protest an Beteiligung von GB an Krieg"]},{"label":"19","answers":["65 Österreich alle Nationalfeiertag („Ehrentag des Österreicher/innen unabhängigen Landes Österreich“), feiert die immerwährende Neutralität des Landes nach einem Gesetz von"]},{"label":"19","answers":["55, arbeitsfrei"]},{"label":"18","answers":["63 Genf/Schweiz sozial engagierte internationale Konferenz sozial Gruppen, Henri engagierter Gruppen, Dunant Dunant initiiert eine internationale Hilfsorganisation: später das Rote Kreuz / der Rote Halbmond"]},{"label":"18","answers":["61 Frankfurt am Main/ Johann Philipp Reis Präsentation eines Deutschland „Fernsprechgerätes“: Telefon, Sensation, Fachwelt begeistert"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-202","solutionId":"b2-sol-202","chapter":8,"module":"Modul 2 · 26. 10. – Ein Tag in der Geschichte","moduleIndex":2,"label":"A2","title":"26. 10. – Ein Tag in der Geschichte","page":127,"kind":"truefalse","tags":["Practice","Vocabulary"],"modelAnswer":"1. r, 2. f, 3. f, 4. f, 5. r","fields":[{"label":"1","answers":["r"]},{"label":"2","answers":["f"]},{"label":"3","answers":["f"]},{"label":"4","answers":["f"]},{"label":"5","answers":["r"]}],"film":false,"y0":430,"y1":1403,"options":["R","F"]},{"id":"b2-ex-203","solutionId":"b2-sol-203","chapter":8,"module":"Modul 2 · 26. 10. – Ein Tag in der Geschichte","moduleIndex":2,"label":"A3A","title":"26. 10. – Ein Tag in der Geschichte","page":128,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n       Erfindung des Telefons von Philipp Reis: Vorführung mit seinem Schwager, der im Garten\n       stand und unsinnige Sätze sprechen musste, die Reis im Gebäude wiederholte, Publikum war\n       erst ungläubig, es scheint mehrere Erfinder des Telefons zu geben: Amerikaner Bell\n\n\n\n\n      Tour de France: Oktober 2012 schwarzer Monat für Radsport, Lance Armstrong wurden\n      wegen Doping seine sieben Titel der Tour aberkannt (1999–2005), am 26.10. Entscheidung\n      des Radsport-Weltverbands, diese auch nicht an andere zu vergeben, Entscheidung schlecht\n      für Image des Sports","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-204","solutionId":"b2-sol-204","chapter":8,"module":"Modul 3 · Irrtümer der Geschichte","moduleIndex":3,"label":"A1A","title":"Irrtümer der Geschichte","page":129,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1c – 2b – 3c – 4a","fields":[{"label":"1","answers":["C"]},{"label":"2","answers":["B"]},{"label":"3","answers":["C"]},{"label":"4","answers":["A"]}],"film":false,"y0":0,"y1":760,"options":["A","B","C"]},{"id":"b2-ex-205","solutionId":"b2-sol-205","chapter":8,"module":"Modul 3 · Irrtümer der Geschichte","moduleIndex":3,"label":"A2A","title":"Irrtümer der Geschichte","page":129,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"antworten, sind der Überzeugung, Es ist zwar richtig, das bedeutet aber nicht, Da liest man,\n      auf die Idee kam, sind davon überzeugt\n      weitere Ausdrücke: meinen, erzählen, berichten, behaupten, fragen, sagen etc.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-206","solutionId":"b2-sol-206","chapter":8,"module":"Modul 3 · Irrtümer der Geschichte","moduleIndex":3,"label":"A2B","title":"Irrtümer der Geschichte","page":129,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"2. …, dass die Lebenserwartung nicht sehr hoch gewesen sei.\n      3. …, dass man mit 40 Jahren ein alter Mensch gewesen sei.\n      4. …, Gutenberg habe den Buchdruck erfunden.","fields":[{"label":"2","answers":["…, dass die Lebenserwartung nicht sehr hoch gewesen sei."]},{"label":"3","answers":["…, dass man mit"]},{"label":"40","answers":["Jahren ein alter Mensch gewesen sei."]},{"label":"4","answers":["…, Gutenberg habe den Buchdruck erfunden."]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-207","solutionId":"b2-sol-207","chapter":8,"module":"Modul 3 · Irrtümer der Geschichte","moduleIndex":3,"label":"A2C","title":"Irrtümer der Geschichte","page":129,"kind":"fill","tags":["Practice","Grammar"],"modelAnswer":"Konjunktiv I\n      (Gegenwart)     Infinitiv-Stamm + Endung\n                      3. Person Sg. von sein: sei\n                      3. Person Sg. von haben: habe\n      (Vergangenheit) Konjunktiv I von haben oder sein + Partizip II","fields":[{"label":"3","answers":["Person Sg. von sein: sei"]},{"label":"3","answers":["Person Sg. von haben: habe (Vergangenheit) Konjunktiv I von haben oder sein + Partizip II"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-208","solutionId":"b2-sol-208","chapter":8,"module":"Modul 3 · Irrtümer der Geschichte","moduleIndex":3,"label":"A2D","title":"Irrtümer der Geschichte","page":129,"kind":"fill","tags":["Practice","Grammar"],"modelAnswer":"Konjunktiv I – anderen – Indikativ","fields":[{"label":"Answer","answers":["Konjunktiv I – anderen – Indikativ"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-209","solutionId":"b2-sol-209","chapter":8,"module":"Modul 3 · Irrtümer der Geschichte","moduleIndex":3,"label":"A3","title":"Irrtümer der Geschichte","page":130,"kind":"open","tags":["Practice","Grammar","Writing"],"modelAnswer":"Wenn die Formen von Konjunktiv I identisch mit den Formen des Indikativs sind, wird\n      Konjunktiv II oder die Ersatzform würde + Infinitiv verwendet.","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-210","solutionId":"b2-sol-210","chapter":8,"module":"Modul 3 · Irrtümer der Geschichte","moduleIndex":3,"label":"A4","title":"Irrtümer der Geschichte","page":130,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Die meisten Menschen denken,\n      … Wilhelm Tell sei der wichtigste Freiheitskämpfer der Schweiz.\n      … Charles Lindbergh sei als erster Mensch über den Atlantik geflogen.\n      … der Treibstoff „Benzin“ sei nach Carl Benz benannt.","fields":[],"film":false,"y0":320,"y1":980},{"id":"b2-ex-211","solutionId":"b2-sol-211","chapter":8,"module":"Modul 4 · Grenzen überwinden","moduleIndex":4,"label":"A1A","title":"Grenzen überwinden","page":131,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      Verändert: im Hintergrund sind neue Häuser dazugekommen, Mauer und Zäune sind nicht\n      mehr da, Wachturm ist verschwunden, man kann heute am Fluss entlanggehen/fahren, statt\n      Laternen stehen jetzt Bäume da, Straße ist frisch gepflastert, es ist kein Schwarzweißfoto,\n      sondern ein Farbfoto","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-212","solutionId":"b2-sol-212","chapter":8,"module":"Modul 4 · Grenzen überwinden","moduleIndex":4,"label":"A2A","title":"Grenzen überwinden","page":131,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"2. Z. 41–47, 3. Z. 12–18, 4. Z. 30–35, 5. Z. 18–22, 6. Z. 1–12, 7. Z. 36–40, 8. Z. 64–68","fields":[{"label":"2","answers":["Z."]},{"label":"3","answers":["Z."]},{"label":"4","answers":["Z."]},{"label":"5","answers":["Z."]},{"label":"6","answers":["Z."]},{"label":"7","answers":["Z."]},{"label":"8","answers":["Z."]},{"label":"6","answers":["8"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-213","solutionId":"b2-sol-213","chapter":8,"module":"Modul 4 · Grenzen überwinden","moduleIndex":4,"label":"A2B","title":"Grenzen überwinden","page":131,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      lag in Ost-Berlin; hier hielten S-Bahnen und U-Bahnen aus Ost- und West-Berlin; die\n      Haltestellen sind strikt getrennt voneinander; Vermutung: Westdeutsche konnten hier\n      durchreisen und dazu auch umsteigen; Vielleicht wurde der Bahnhof auch als Ein- und\n      Ausreisestation zwischen Westen und Osten benutzt.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-214","solutionId":"b2-sol-214","chapter":8,"module":"Modul 4 · Grenzen überwinden","moduleIndex":4,"label":"A2C","title":"Grenzen überwinden","page":131,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      Westdeutsche: Umsteigen ohne Kontrolle, konnten aber Bahnhof nicht verlassen (außer unter\n      strengen Kontrollen und mit Visum); Fotografieren verboten; Ausgangspunkt für\n      Tagesausflüge nach Ostberlin / in den Osten; emotionale Abschiede im Ost-Teil\n      („Tränenpalast“); getrennte Wege für West- und Ostbürger","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-215","solutionId":"b2-sol-215","chapter":8,"module":"Modul 4 · Grenzen überwinden","moduleIndex":4,"label":"A3B","title":"Grenzen überwinden","page":132,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"• Sommer 1989: Besetzung der Botschaften der BRD in Prag, Budapest, Warschau und Ost-\n       Berlin; Flüchtlinge wollten so Ausreise erzwingen\n       • Politik der Öffnung von Michail Gorbatschow → politische Veränderungen in Ungarn und\n       schließlich Öffnung der ungarischen Grenze zu Österreich\n       • Massenflucht über Österreich in die BRD\n       • September 1989: Aufgrund des Einlenkens der DDR-Regierung konnten auch Menschen\n       aus den Botschaften in Prag und Warschau ausreisen.\n       • Oktober 1989: Massenproteste in der DDR (friedliche Revolution) → Öffnung der Grenze","fields":[{"label":"19","answers":["89: Besetzung der Botschaften der BRD in Prag, Budapest, Warschau und Ost- Berlin; Flüchtlinge wollten so Ausreise erzwingen • Politik der Öffnung von Michail Gorbatschow → politische Veränderungen in Ungarn und schließlich Öffnung der ungarischen Grenze zu Österreich • Massenflucht über Österreich in die BRD • September"]},{"label":"19","answers":["89: Aufgrund des Einlenkens der DDR-Regierung konnten auch Menschen aus den Botschaften in Prag und Warschau ausreisen. • Oktober"]},{"label":"19","answers":["89: Massenproteste in der DDR (friedliche Revolution) → Öffnung der Grenze"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-216","solutionId":"b2-sol-216","chapter":8,"module":"Modul 4 · Grenzen überwinden","moduleIndex":4,"label":"A3C","title":"Grenzen überwinden","page":132,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"-d Zukunft, Reisen, sofort, Grenze, Westen, feiern","fields":[{"label":"Answer","answers":["-d Zukunft, Reisen, sofort, Grenze, Westen, feiern"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-217","solutionId":"b2-sol-217","chapter":8,"module":"Modul 4 · Grenzen überwinden","moduleIndex":4,"label":"A4A","title":"Grenzen überwinden","page":132,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Wo war die Person?         Was waren ihre Gefühle      Was denkt sie heute?\n                                               und Gedanken?\n        1. Mann     zu Hause (am Telefon)      maßloses Staunen, große     hätte auch anders\n                                               Freude                      ausgehen können\n                                                                           (Horrorszenario);\n                                                                           dankbar, dass es friedlich\n                                                                           abgelaufen ist\n        2. Frau     zu Hause, erst am          beim Martinsumzug,          besondere Erinnerung:\n                    Fenster, dann am           besondere Erinnerung: ihr   Verknüpfung von\n                    Fernseher                  Sohn sagt sein erstes       Mauerfall und erstem\n                                               Wort „Licht“                Wort ihres Sohnes\n        3. Frau     noch nicht auf der Welt    -                           ärgert sich über Kommen-\n                                                                           tare, dass Wiederver-\n                                                                           einigung zu teuer war,\n                                                                           empfindet friedliche\n                                                                           Wiedervereinigung als\n                                                                           etwas ganz Besonderes\n        4. Mann     Grundausbildung bei der    Zuversicht und Taten-       froh, dass es um ihn\n                    Nationalen Volksarmee      drang, dass sich im Land    herum kluge Offiziere gab\n                    der DDR war grade          etwas verbessern lässt,\n                    vorbei                     aber plötzlich auch das\n                                               Gefühl, dass das Vater-\n                                               land der Feind ist; Angst\n                                               und Unsicherheit, wer\n                                               Freund und wer Feind ist","fields":[{"label":"1","answers":["Mann zu Hause (am Telefon) maßloses Staunen, große hätte auch anders Freude ausgehen können (Horrorszenario); dankbar, dass es friedlich abgelaufen ist"]},{"label":"2","answers":["Frau zu Hause, erst am beim Martinsumzug, besondere Erinnerung: Fenster, dann am besondere Erinnerung: ihr Verknüpfung von Fernseher Sohn sagt sein erstes Mauerfall und erstem Wort „Licht“ Wort ihres Sohnes"]},{"label":"3","answers":["Frau noch nicht auf der Welt - ärgert sich über Kommen- tare, dass Wiederver- einigung zu teuer war, empfindet friedliche Wiedervereinigung als etwas ganz Besonderes"]},{"label":"4","answers":["Mann Grundausbildung bei der Zuversicht und Taten- froh, dass es um ihn Nationalen Volksarmee drang, dass sich im Land herum kluge Offiziere gab der DDR war grade etwas verbessern lässt, vorbei aber plötzlich auch das Gefühl, dass das Vater- land der Feind ist; Angst und Unsicherheit, wer Freund und wer Feind ist"]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-218","solutionId":"b2-sol-218","chapter":8,"module":"Modul 4 · Grenzen überwinden","moduleIndex":4,"label":"A5A","title":"Grenzen überwinden","page":132,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Geschichte der Teilung Deutschlands\n       1945         nach Kriegsende vier Wirtschaftssektoren unter der Verwaltung von USA,\n                    Großbritannien, Frankreich und Sowjetunion\n       1949         Gründung der BRD aus Sektoren der USA, Großbritanniens und Frankreichs;\n                    Gründung der DDR aus Sektor der Sowjetunion; Teilung Berlins\n       bis 1960     Menschen können leicht zwischen Osten und Westen hin- und herfahren;\n                    Auswanderung von 2,7 Millionen Menschen aus der DDR wegen schlechter\n                    Lebensbedingungen\n       13.8.1961    Beginn des Mauerbaus Schließung der Grenze\n       ab 1961      strenge Ein- und Ausreisebedingungen; Ausbau der Grenzgebiete, starke\n                    Grenzkontrollen; Bahnhof Friedrichstraße wird Symbol für schmerzliche\n                    Trennung von Familien und Freunden\n       Mauerfall und Grenzöffnung\n       Sommer 1989         Besetzung der Botschaften in Prag, Budapest und Warschau und Ost-\n                           Berlin von DDR-Flüchtlingen; Besetzer fordern Ausreiseerlaubnis;\n                           Öffnung der ungarischen Grenze nach Österreich\n       September 1989      Ausreise von 15.000 DDR-Bürgern aus Prag und Warschau in die BRD\n       Oktober 1989        Massenproteste in der DDR: Montagsdemonstrationen, friedliche\n                           Revolution\n       9.11.1989           Öffnung der Grenzen zwischen DDR und BRD; Menschen aus Ost und\n                           West feiern den Mauerfall\n\n\n\nFilm Ein Traum wird wahr","fields":[{"label":"19","answers":["45 nach Kriegsende vier Wirtschaftssektoren unter der Verwaltung von USA, Großbritannien, Frankreich und Sowjetunion"]},{"label":"19","answers":["49 Gründung der BRD aus Sektoren der USA, Großbritanniens und Frankreichs; Gründung der DDR aus Sektor der Sowjetunion; Teilung Berlins bis"]},{"label":"19","answers":["60 Menschen können leicht zwischen Osten und Westen hin- und herfahren; Auswanderung von"]},{"label":"7","answers":["Millionen Menschen aus der DDR wegen schlechter Lebensbedingungen"]},{"label":"19","answers":["61 Beginn des Mauerbaus Schließung der Grenze ab"]},{"label":"19","answers":["61 strenge Ein- und Ausreisebedingungen; Ausbau der Grenzgebiete, starke Grenzkontrollen; Bahnhof Friedrichstraße wird Symbol für schmerzliche Trennung von Familien und Freunden Mauerfall und Grenzöffnung Sommer"]},{"label":"19","answers":["89 Besetzung der Botschaften in Prag, Budapest und Warschau und Ost- Berlin von DDR-Flüchtlingen; Besetzer fordern Ausreiseerlaubnis; Öffnung der ungarischen Grenze nach Österreich September"]},{"label":"19","answers":["89 Ausreise von"]},{"label":"00","answers":["0 DDR-Bürgern aus Prag und Warschau in die BRD Oktober"]},{"label":"19","answers":["89 Massenproteste in der DDR: Montagsdemonstrationen, friedliche Revolution"]},{"label":"19","answers":["89 Öffnung der Grenzen zwischen DDR und BRD; Menschen aus Ost und West feiern den Mauerfall Film Ein Traum wird wahr"]}],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-219","solutionId":"b2-sol-219","chapter":8,"module":"Film · Ein Traum wird wahr","moduleIndex":4,"label":"A1","title":"Ein Traum wird wahr","page":137,"kind":"fill","tags":["Practice","Reading","Listening"],"modelAnswer":"Mai 1949           Gründung der Bundesrepublik Deutschland\n          Oktober 1990       Vereinigung von DDR und BRD\n          August 1961        Bau der Berliner Mauer\n          Oktober 1949       Gründung der Deutschen Demokratischen Republik\n          November 1989      Öffnung der Berliner Mauer für alle DDR-Bürger","fields":[{"label":"19","answers":["49 Gründung der Bundesrepublik Deutschland Oktober"]},{"label":"19","answers":["90 Vereinigung von DDR und BRD August"]},{"label":"19","answers":["61 Bau der Berliner Mauer Oktober"]},{"label":"19","answers":["49 Gründung der Deutschen Demokratischen Republik November"]},{"label":"19","answers":["89 Öffnung der Berliner Mauer für alle DDR-Bürger"]}],"film":true,"y0":0,"y1":760},{"id":"b2-ex-220","solutionId":"b2-sol-220","chapter":8,"module":"Film · Ein Traum wird wahr","moduleIndex":4,"label":"A2A","title":"Ein Traum wird wahr","page":137,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Was machen Militär und Polizei?: riegeln die drei Westsektoren der Stadt hermetisch ab;\n          sperren die Straße am Brandenburger Tor; der öffentliche Verkehr (Straßen- und U-Bahnen)\n          ist eingestellt; Polizei hindert Menschen an der Flucht in letzter Minute; Polizei versucht die\n          Demonstration mit Wasserwerfern aufzulösen\n          Warum fliehen einige Menschen?: Unmut/Unzufriedenheit; wollen in letzter Sekunde die\n          unübersichtliche Lage für die Flucht ausnutzen\n          Die Menschen rufen „Volksabstimmung“. Was wollen sie damit erreichen?: protestieren gegen\n          den Mauerbau; wollen Freizügigkeit / nicht eingesperrt sein","fields":[],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-221","solutionId":"b2-sol-221","chapter":8,"module":"Film · Ein Traum wird wahr","moduleIndex":4,"label":"A2B","title":"Ein Traum wird wahr","page":137,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Mögliche Lösung:\n          Atmosphäre/Gefühle/Gedanken: gefährliche/brisante Lage, entscheidende Momente,\n          Miterleben eines historischen Ereignisses, großes Durcheinander, Unsicherheit, höchst\n          angespannte, aufgeladene Stimmung","fields":[],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-222","solutionId":"b2-sol-222","chapter":8,"module":"Film · Ein Traum wird wahr","moduleIndex":4,"label":"A3","title":"Ein Traum wird wahr","page":138,"kind":"fill","tags":["Practice","Listening"],"modelAnswer":"D–F–C–E–A–B","fields":[{"label":"Answer","answers":["D–F–C–E–A–B"]}],"film":true,"y0":0,"y1":650},{"id":"b2-ex-223","solutionId":"b2-sol-223","chapter":8,"module":"Film · Ein Traum wird wahr","moduleIndex":4,"label":"A4A","title":"Ein Traum wird wahr","page":138,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"-b Mögliche Aussagen:\n      Mögliche Aussagen: Die Menschen sind von der Öffnung der Grenze völlig überrascht\n      worden, niemand hat gedacht, dass die Entwicklung in diese Richtung gehen wird. Stimmung\n      ist sehr emotional, fröhlich, die Menschen sind bewegt. Alle können offen ihre Meinung sagen.\n      Ein etwas älterer Mann erinnert sich an den Bau der Mauer und bricht in Tränen aus. Von\n      West- und Ostberlin kommen die Menschen zum Brandenburger Tor, klettern auf die Mauer\n      und feiern. Viele Ostberliner gehen in den Westen, um „mal zu schauen“, wollen die Mauer\n      von der anderen Seite sehen, fahren mit der U-Bahn zum Kurfürstendamm.","fields":[],"film":true,"y0":320,"y1":980},{"id":"b2-ex-224","solutionId":"b2-sol-224","chapter":8,"module":"Film · Ein Traum wird wahr","moduleIndex":4,"label":"A5","title":"Ein Traum wird wahr","page":138,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Eine Wiedervereinigung wird wegen der vielen damit verbundenen Probleme eher skeptisch\n          gesehen. Obwohl gesagt wird, dass alle die bisherige Situation in der DDR satt hätten, wollen\n          sie das Land nicht verlassen: „Im Prinzip wollen wir ja nichts anderes“, sondern „unsere Arbeit\n          machen, bisschen verreisen, bisschen was sehen, leben wie jeder andere“. Eine Frau sagt,\n          sie gehe auf jeden Fall zurück in die DDR, weil sie an dieses Land glaube. Ein Interviewter\n          sagt: „In zwei Jahren haben wir die Wiedervereinigung“. Ein anderer glaubt daran, dass in der\n          DDR nun durch Reformen eine neue, ökologische Gesellschaft geschaffen werden könne, die\n          besser ist als im Westen, sodass die Leute aus dem Westen bald in den Osten ziehen wollen.","fields":[],"film":true,"y0":610,"y1":1320},{"id":"b2-ex-225","solutionId":"b2-sol-225","chapter":9,"module":"Auftakt","moduleIndex":0,"label":"A1A","title":"Auftakt","page":139,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n          A: Vergänglichkeit/Lauf der Zeit/Trauer/Abschied, B: Leben/Freude/Optimismus, C: Hoffnung,\n          D: Freiheit, E: Bildung/Zweifel/Unsicherheit/, F: Arbeit/Überheblichkeit, G: Liebe/Verlangen,\n          H: Pläne/Vergeblichkeit/Nüchternheit","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-226","solutionId":"b2-sol-226","chapter":9,"module":"Auftakt","moduleIndex":0,"label":"A1C","title":"Auftakt","page":139,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":"Beispiele: Angst, Glück, Freude, Zorn, Wut, Ärger, Gleichgültigkeit, Zufriedenheit …","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-227","solutionId":"b2-sol-227","chapter":9,"module":"Modul 1 · Mit Musik geht alles besser","moduleIndex":1,"label":"A2A","title":"Mit Musik geht alles besser","page":141,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Zeitvertreib; Stressabbau; Beeinflussung des Empfindens durch Steuerung des Blutdrucks\n       und damit auch der Gehirnaktivität Sauerstoffverbrauch, Atmung und Stoffwechsel reagieren\n       auf Musik; Senkung des Schmerzempfindens durch Ablenkung und Durchbrechen des\n       Schmerz-Stress-Kreislaufs; Therapie von Bewegungs- und Sprachstörungen und bei\n       Alzheimer und Demenz, denn Erinnerungen werden reaktiviert; Einfluss auf Konzentration und\n       Lernerfolg, Inhalte werden mit Musik besser behalten, z. B. beim Lernen oder bei Werbung;\n       wohltuend, beruhigend und gesundheitsfördernd","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-228","solutionId":"b2-sol-228","chapter":9,"module":"Modul 1 · Mit Musik geht alles besser","moduleIndex":1,"label":"A2B","title":"Mit Musik geht alles besser","page":141,"kind":"fill","tags":["Practice"],"modelAnswer":"2–4–1–3–1–3","fields":[{"label":"Answer","answers":["2–4–1–3–1–3"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-229","solutionId":"b2-sol-229","chapter":9,"module":"Modul 1 · Mit Musik geht alles besser","moduleIndex":1,"label":"A3A","title":"Mit Musik geht alles besser","page":142,"kind":"open","tags":["Practice","Grammar","Writing"],"modelAnswer":"viele Nomen/Nominalisierungen, keine Verben verwendet\n       Verwendung von Zeichen wie = und /\n       Gliederung durch Spiegelstriche und a), b), ...","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-230","solutionId":"b2-sol-230","chapter":9,"module":"Modul 1 · Mit Musik geht alles besser","moduleIndex":1,"label":"A3B","title":"Mit Musik geht alles besser","page":142,"kind":"open","tags":["Practice","Grammar","Writing"],"modelAnswer":"Endung/Veränderung               Verb                           Nomen\n       Verb ohne Endung (mit/ohne       abbauen                        der Abbau\n       Vokaländerung)                   wählen                         die Wahl\n       das + Infinitiv                  erkennen                       das Erkennen\n       die + -ung                       entstehen                      die Entstehung\n                                        wahrnehmen                     die Wahrnehmung\n       der + -er                        lernen                         der Lerner\n       die/der + e- (mit/ohne           folgen                         die Folge\n       Vokaländerung)                   helfen                         die Hilfe\n       die/das + -(t)nis                erkennen                       die Erkenntnis\n                                        erleben                        das Erlebnis\n       die + -(t)ion                    reagieren                      die Reaktion","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-231","solutionId":"b2-sol-231","chapter":9,"module":"Modul 1 · Mit Musik geht alles besser","moduleIndex":1,"label":"A3C","title":"Mit Musik geht alles besser","page":142,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. Die Reaktion / Das Reagieren des Körpers auf Musik\n       2. Das Beeinflussen / Die Beeinflussung unseres Befindens durch die Musik\n       3. Die Wirkung / Das Wirken von Musik auf den Körper\n       4. Die Steuerung / Das Steuern des Blutdrucks\n       5. Die Nutzung / Das Nutzen der Musik in der Medizin","fields":[{"label":"1","answers":["Die Reaktion / Das Reagieren des Körpers auf Musik"]},{"label":"2","answers":["Das Beeinflussen / Die Beeinflussung unseres Befindens durch die Musik"]},{"label":"3","answers":["Die Wirkung / Das Wirken von Musik auf den Körper"]},{"label":"4","answers":["Die Steuerung / Das Steuern des Blutdrucks"]},{"label":"5","answers":["Die Nutzung / Das Nutzen der Musik in der Medizin"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-232","solutionId":"b2-sol-232","chapter":9,"module":"Modul 1 · Mit Musik geht alles besser","moduleIndex":1,"label":"A4","title":"Mit Musik geht alles besser","page":142,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n       Abschnitt 3:\n       • Senkung des Schmerzempfindens (Ablenkung, Schmerz-Stress-Kreislauf unterbrochen)\n       • Unterstützung von Therapien durch Reaktivierung von Gedächtnisinhalten\n                a) bei Bewegungs- u. Sprachstörungen nach Hirnschäden\n                b) bei Gedächtnisproblemen\n       Abschnitt 4:\n       • positive Beeinflussung von Konzentration und Lernerfolg\n\n       • man behält besser, v. a. bei Reproduktion\n       • Wiederholung von Vokabeln zu Rhythmus – besser/Lerneffekt größer","fields":[],"film":false,"y0":320,"y1":980},{"id":"b2-ex-233","solutionId":"b2-sol-233","chapter":9,"module":"Modul 2 · Farbenfroh","moduleIndex":2,"label":"A2A","title":"Farbenfroh","page":143,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Farbe 1: rot, Farbe 2: gelb, Farbe 3: blau\n       Möglich Informationen, die geholfen haben:\n       1: Schutz vor bösen Einflüssen, Krieger färbten Waffen, magische Kräfte; von Weitem gut\n       sichtbar (Fahnen/Flaggen), Straßenverkehr: Gefahr/Verbot; Gesicht wird so bei Ärger und\n       Wut; heilende Wirkung: wohltuend, warm, anregend; positiver Einfluss auf Konzentration\n       2: kräftig, hell wie das Tageslicht; macht fröhlich, Lebensfreude, Optimismus; Lieblingsfarbe\n       von van Gogh: Symbol für Sonne des Südens, Heiterkeit, Freundschaft und Liebe; Pestfarbe;\n       Eifersucht und Neid; Straßenverkehr: Postautos, Ampeln; Fußball: Verwarnung\n       3: beruhigend, entspannend, Farbe des Gemüts; positive Stimmung, Milderung von Sorgen;\n       oft in Werbung und Firmenlogos; Medizin: soll Blutdruck senken – kühl, rein und tief","fields":[{"label":"1","answers":[": rot, Farbe"]},{"label":"2","answers":[": gelb, Farbe"]},{"label":"3","answers":[": blau Möglich Informationen, die geholfen haben:"]},{"label":"1","answers":[": Schutz vor bösen Einflüssen, Krieger färbten Waffen, magische Kräfte; von Weitem gut sichtbar (Fahnen/Flaggen), Straßenverkehr: Gefahr/Verbot; Gesicht wird so bei Ärger und Wut; heilende Wirkung: wohltuend, warm, anregend; positiver Einfluss auf Konzentration"]},{"label":"2","answers":[": kräftig, hell wie das Tageslicht; macht fröhlich, Lebensfreude, Optimismus; Lieblingsfarbe von van Gogh: Symbol für Sonne des Südens, Heiterkeit, Freundschaft und Liebe; Pestfarbe; Eifersucht und Neid; Straßenverkehr: Postautos, Ampeln; Fußball: Verwarnung"]},{"label":"3","answers":[": beruhigend, entspannend, Farbe des Gemüts; positive Stimmung, Milderung von Sorgen; oft in Werbung und Firmenlogos; Medizin: soll Blutdruck senken – kühl, rein und tief"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-234","solutionId":"b2-sol-234","chapter":9,"module":"Modul 2 · Farbenfroh","moduleIndex":2,"label":"A2B","title":"Farbenfroh","page":143,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Bedeutung Farbe 1: Schutz von Gegenständen/Bäumen/Tieren, Gefahr und Verbot, Wut und\n      Ärger\n      Wirkung Farbe 1: magisch Kräfte gegen böse Einflüsse, von Weitem gut sichtbar,\n      Signalwirkung, heilend (wohltuend, wärmend, anregend, appetitfördernd), gut für\n      Konzentration\n      Bedeutung Farbe 2: Lebensfreude und Optimismus, Symbol für Sonne des Südens/Heiterkeit/\n      Freundschaft und Liebe bei van Gogh, Pestflagge, Neid und Eifersucht, umschaltende Ampel,\n      Post, Verwarnung im Fußball\n      Wirkung Farbe 2: macht fröhlich, Warnung, gut sichtbar\n      Bedeutung Farbe 3: Farbe des Gemüts, kühl/rein/tief\n      Wirkung Farbe 3: beruhigend/entspannend/Träume fördernd, verbreitet positive Stimmung,\n      mildert Sorgen, lässt schlechte Nachrichten eher akzeptieren, senkt Fieber und Blutdruck, gut\n      fürs Gleichgewicht","fields":[{"label":"1","answers":[": Schutz von Gegenständen/Bäumen/Tieren, Gefahr und Verbot, Wut und Ärger Wirkung Farbe"]},{"label":"1","answers":[": magisch Kräfte gegen böse Einflüsse, von Weitem gut sichtbar, Signalwirkung, heilend (wohltuend, wärmend, anregend, appetitfördernd), gut für Konzentration Bedeutung Farbe"]},{"label":"2","answers":[": Lebensfreude und Optimismus, Symbol für Sonne des Südens/Heiterkeit/ Freundschaft und Liebe bei van Gogh, Pestflagge, Neid und Eifersucht, umschaltende Ampel, Post, Verwarnung im Fußball Wirkung Farbe"]},{"label":"2","answers":[": macht fröhlich, Warnung, gut sichtbar Bedeutung Farbe"]},{"label":"3","answers":[": Farbe des Gemüts, kühl/rein/tief Wirkung Farbe"]},{"label":"3","answers":[": beruhigend/entspannend/Träume fördernd, verbreitet positive Stimmung, mildert Sorgen, lässt schlechte Nachrichten eher akzeptieren, senkt Fieber und Blutdruck, gut fürs Gleichgewicht"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-235","solutionId":"b2-sol-235","chapter":9,"module":"Modul 2 · Farbenfroh","moduleIndex":2,"label":"A3B","title":"Farbenfroh","page":144,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"A: In diesem Text geht es um … – Im Text wird behauptet, dass … – Die Haupaussage des\n      Textes ist: …\n      B: Dazu fällt mir folgendes Beispiel ein: … – Mir fällt als Beispiel sofort … ein. – Ich möchte\n      folgendes Beispiel anführen: …\n      C: Ich bin anderer Meinung, denn … – Meiner Meinung nach … – Ich halte diese Meinung für\n      richtige/falsch, weil … – Ich dem Text (nicht) zustimmen, weil …","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-236","solutionId":"b2-sol-236","chapter":9,"module":"Modul 2 · Farbenfroh","moduleIndex":2,"label":"A3C","title":"Farbenfroh","page":144,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Beispiele für die Einleitung: Das Thema meines Textes heißt … / Ich spreche jetzt\n      über einen Text mit dem Titel … / …\n      Mögliche Beispiele für den Schluss: Lassen Sie mich meine Argumente noch einmal\n      zusammenfassen … / Bevor ich meinen Vortrag beende, … / Ich möchte das Gesagte noch\n      einmal kurz zusammenfassen: … / …","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-237","solutionId":"b2-sol-237","chapter":9,"module":"Modul 3 · Sprache und Gefühl","moduleIndex":3,"label":"A1A","title":"Sprache und Gefühl","page":145,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"1. lebendiger und freundlicher, 2. stärker","fields":[{"label":"1","answers":["lebendiger und freundlicher"]},{"label":"2","answers":["stärker"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-238","solutionId":"b2-sol-238","chapter":9,"module":"Modul 3 · Sprache und Gefühl","moduleIndex":3,"label":"A1C","title":"Sprache und Gefühl","page":145,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":"A: Vorschlag/Ermunterung, B: Überraschung, C: Freundlichkeit/Interesse,\n      D: Aufforderung/Befehl, E: Empörung, F: Überraschung, G: Überraschung","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-239","solutionId":"b2-sol-239","chapter":9,"module":"Modul 3 · Sprache und Gefühl","moduleIndex":3,"label":"A2A","title":"Sprache und Gefühl","page":145,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Satzart                Partikel   Bedeutung                        Beispiel\n       Aussagen und           aber       Freundlichkeit                   Das ist aber schön, dich zu\n       Ausrufe                           Überraschung                     sehen.\n                                                                          Der sieht aber sympathisch aus!\n                              doch       Freundlichkeit                   Das mache ich doch gerne.\n                                         Empörung                         Das ist doch unmöglich!\n                                         Vorschlag/Ermunterung            Komm doch mit ins Kino!\n                              ja         Freundlichkeit                   Das ist ja nett.\n                                         Überraschung                     Du bist ja auch hier!\n                                         Empörung                         Das ist ja gemein!\n       Aufforderungen,        mal        Aufforderung/Befehl              Hilf mir mal!\n       Aussagen, Fragen\n       Fragen                 denn       Freundlichkeit/Interesse         Wie geht’s dir denn?\n                                         Überraschung                     Sprecht ihr denn wieder\n                                                                          miteinander?","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-240","solutionId":"b2-sol-240","chapter":9,"module":"Modul 3 · Sprache und Gefühl","moduleIndex":3,"label":"A2B","title":"Sprache und Gefühl","page":145,"kind":"fill","tags":["Practice"],"modelAnswer":"mündliche – verstärken – Verb – Kontext – Betonung","fields":[{"label":"Answer","answers":["mündliche – verstärken – Verb – Kontext – Betonung"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-241","solutionId":"b2-sol-241","chapter":9,"module":"Modul 3 · Sprache und Gefühl","moduleIndex":3,"label":"A3A","title":"Sprache und Gefühl","page":146,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":"Mögliche Lösung:\n      1. doch, 2. denn, 3. aber, 4. doch, 5. ja, 6. denn, 7. mal, 8. ja","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-242","solutionId":"b2-sol-242","chapter":9,"module":"Modul 4 · Gemischte Gefühle","moduleIndex":4,"label":"A1B","title":"Gemischte Gefühle","page":147,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n      1. Freundschaft, Gemeinschaftsgefühl, Loyalität, Unterstützung, Zuverlässigkeit,\n      Lebensfreude, Zusammenhalt, Fröhlichkeit, Feierlaune, Euphorie, Glück, Lust auf die\n      Zukunft/keine Angst vor der Zukunft, Beflügeltsein\n      2. positiv, optimistisch, fröhlich, euphorisch; „Ein Hoch auf …“ bedeutet, dass man etwas oder\n      jemanden feiert und gratuliert\n      3. „uns“: alle Menschen, er und seine Freunde, diejenigen, die jetzt dabei sind","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-243","solutionId":"b2-sol-243","chapter":9,"module":"Modul 4 · Gemischte Gefühle","moduleIndex":4,"label":"A2","title":"Gemischte Gefühle","page":147,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche pessimistische/ängstliche Einschätzungen:\n      Im Endeffekt ist man doch alleine.; Das sind schöne, große Worte, aber was ist, wenn das\n      erste Problem auftaucht? / wenn das „Feuerwerk“ abgebrannt ist?; Euphorie ist immer nur\n      kurzzeitig und verfliegt dann.; Auf Euphorie kann man nicht dauerhaft bauen / sich nicht\n      dauerhaft verlassen.","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-244","solutionId":"b2-sol-244","chapter":9,"module":"Modul 4 · Gemischte Gefühle","moduleIndex":4,"label":"A3B","title":"Gemischte Gefühle","page":148,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Seele – Körpers – Stressreaktion – vermeiden – schlägt schneller / weit geöffnet, mehr\n      sehen – ganz klein / gespannt – Panik – Gedanken durcheinander – Prüfung – 1. Tag in neuer\n      Firma – Unfälle/Schäden – Nacht/Dinge sehen anders aus – Versagen – Krankheiten – Tod –\n      bei Panikattacken – der Zukunft","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-245","solutionId":"b2-sol-245","chapter":9,"module":"Modul 4 · Gemischte Gefühle","moduleIndex":4,"label":"A4B","title":"Gemischte Gefühle","page":148,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Z. 15–18: Druck wegnehmen – nach dem suchen, was man wirklich braucht – sich schon\n      vorher überlegen, was man kaufen will\n      Z. 27–32: Wissen und Selbstbewusstsein: alle nötigen Informationen einholen: Internet,\n      Experten, Freunde, Ratgeber\n      Z. 34/35: keine Entscheidung muss endgültig sein\n      Z: 38/39: Fehler können bewusst machen, was man will\n      Z. 42/43: Gefühle nicht ignorieren\n      (Fazit: Z. 50/51: Nach bestem Wissen und Gewissen entscheiden)","fields":[{"label":"18","answers":[": Druck wegnehmen – nach dem suchen, was man wirklich braucht – sich schon vorher überlegen, was man kaufen will Z."]},{"label":"32","answers":[": Wissen und Selbstbewusstsein: alle nötigen Informationen einholen: Internet, Experten, Freunde, Ratgeber Z."]},{"label":"34","answers":["/"]},{"label":"35","answers":[": keine Entscheidung muss endgültig sein Z:"]},{"label":"38","answers":["/"]},{"label":"39","answers":[": Fehler können bewusst machen, was man will Z."]},{"label":"42","answers":["/"]},{"label":"43","answers":[": Gefühle nicht ignorieren (Fazit: Z."]},{"label":"50","answers":["/"]},{"label":"51","answers":[": Nach bestem Wissen und Gewissen entscheiden)"]}],"film":false,"y0":320,"y1":980},{"id":"b2-ex-246","solutionId":"b2-sol-246","chapter":9,"module":"Modul 4 · Gemischte Gefühle","moduleIndex":4,"label":"A4C","title":"Gemischte Gefühle","page":148,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":"Mögliche Vorschläge:\n      Pro/Contra- Listen; darüber schlafen, abwarten und wenn man die Anschaffung in 2 Monaten\n      auch noch haben möchte, kaufen","fields":[],"film":false,"y0":320,"y1":980},{"id":"b2-ex-247","solutionId":"b2-sol-247","chapter":9,"module":"Modul 4 · Gemischte Gefühle","moduleIndex":4,"label":"A5A","title":"Gemischte Gefühle","page":148,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"Jobwechsel – ja oder nein?\n\nFilm Musik macht klug","fields":[],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-248","solutionId":"b2-sol-248","chapter":9,"module":"Film · Musik macht klug","moduleIndex":4,"label":"A2A","title":"Musik macht klug","page":153,"kind":"fill","tags":["Practice","Listening"],"modelAnswer":"1. – 3. – 4. – 6.","fields":[{"label":"Answer","answers":["1. – 3. – 4. – 6."]}],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-249","solutionId":"b2-sol-249","chapter":9,"module":"Film · Musik macht klug","moduleIndex":4,"label":"A2B","title":"Musik macht klug","page":153,"kind":"fill","tags":["Practice","Vocabulary","Listening"],"modelAnswer":"1. ausgereift, 2. bin … ganz Ohr, 3. wirkt … begabend, 4. unbekümmert, 5. in die Wiege\n      gelegt","fields":[{"label":"1","answers":["ausgereift"]},{"label":"2","answers":["bin … ganz Ohr"]},{"label":"3","answers":["wirkt … begabend"]},{"label":"4","answers":["unbekümmert"]},{"label":"5","answers":["in die Wiege gelegt"]}],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-250","solutionId":"b2-sol-250","chapter":9,"module":"Film · Musik macht klug","moduleIndex":4,"label":"A3A","title":"Musik macht klug","page":154,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Mögliche Lösung:\n      1. Experten sagen, dass alle Kinder Musik mögen.\n      2. Kinder sind schon im Mutterleib musikalisch.\n      3. Der Gehörsinn ist mit 15 Wochen ausgeprägt.\n      4. Es ist wichtig, dass Kinder unbekümmert mit Musik umgehen können.\n      5. Falsche Töne gehören zur Musikalität. / Wenn man nicht den richtigen Ton trifft, ist man\n      trotzdem musikalisch.","fields":[],"film":true,"y0":0,"y1":650},{"id":"b2-ex-251","solutionId":"b2-sol-251","chapter":9,"module":"Film · Musik macht klug","moduleIndex":4,"label":"A3B","title":"Musik macht klug","page":154,"kind":"fill","tags":["Practice","Reading","Listening"],"modelAnswer":"1. die Kinder singen, tanzen, bewegen sich / machen Bewegungsspiele, hören einander zu,\n      entdecken Instrumente / spielen auf Instrumenten\n      2. körperliche Geschicklichkeit, aufeinander zu hören, andere zu führen; ganzheitliche\n      Förderung: stärkt räumliches und logisches Denken, Kreativität, seelisches Wohlbefinden,\n      Konzentration; Kinder lernen zuzuhören\n      3. Eltern merken es, am Verhalten des Kindes: ernsthaftes und leidenschaftliches Interesse an\n      einem Instrument (Kind probiert alleine aus und erfindet Tonfolgen); wenn Eltern bereit sind,\n      mitzumachen","fields":[{"label":"1","answers":["die Kinder singen, tanzen, bewegen sich / machen Bewegungsspiele, hören einander zu, entdecken Instrumente / spielen auf Instrumenten"]},{"label":"2","answers":["körperliche Geschicklichkeit, aufeinander zu hören, andere zu führen; ganzheitliche Förderung: stärkt räumliches und logisches Denken, Kreativität, seelisches Wohlbefinden, Konzentration; Kinder lernen zuzuhören"]},{"label":"3","answers":["Eltern merken es, am Verhalten des Kindes: ernsthaftes und leidenschaftliches Interesse an einem Instrument (Kind probiert alleine aus und erfindet Tonfolgen); wenn Eltern bereit sind, mitzumachen"]}],"film":true,"y0":0,"y1":650},{"id":"b2-ex-252","solutionId":"b2-sol-252","chapter":10,"module":"Auftakt","moduleIndex":0,"label":"A1A","title":"Auftakt","page":155,"kind":"fill","tags":["Practice"],"modelAnswer":"C–A–E–B–G–F–D","fields":[{"label":"Answer","answers":["C–A–E–B–G–F–D"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-253","solutionId":"b2-sol-253","chapter":10,"module":"Modul 1 · Roboterwelt","moduleIndex":1,"label":"A1","title":"Roboterwelt","page":157,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":"Mögliche Lösung:\n          A: Auto fahren, B: Arbeiten im Haushalt übernehmen, C: im Unterricht helfen, D: Informationen\n          recherchieren","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-254","solutionId":"b2-sol-254","chapter":10,"module":"Modul 1 · Roboterwelt","moduleIndex":1,"label":"A2A","title":"Roboterwelt","page":157,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n          1 Weniger menschliche Arbeit durch Roboter / Roboter ersetzen Arbeitskräfte\n          2 Roboterautos / Autos fahren ohne Menschen\n          3 Roboter in der Schule / Roboter helfen kranken Kindern\n          4 Roboter bei uns zu Hause / Service-Roboter im Haushalt","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-255","solutionId":"b2-sol-255","chapter":10,"module":"Modul 1 · Roboterwelt","moduleIndex":1,"label":"A2B","title":"Roboterwelt","page":157,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Vorteile                                       Nachteile\n          1   Qualität wird besser, bestimmte Dinge          Robotern fehlt Empathie, Einfühlungs-\n              gehen schneller, eintönige Jobs                vermögen, Verhandlungsgeschick, mehr\n              verschwinden                                   Arbeitslose, überflüssige Menschen, alles\n                                                             automatisiert, es darf nichts Unvorher-\n                                                             gesehenes passieren\n          2   Roboter zuverlässiger als Menschen,            kein Spaß mehr, keine eigene\n              weniger Unfälle, weniger Stress auf der        Entscheidung mehr\n              Straße, man kann die Zeit für etwas\n              anderes nutzen\n          3   Hilfe für kranke Kinder, verlieren durch die   keine persönliche/körperliche/echte\n              Krankheit keine Zeit, fühlen sich nicht        Interaktion möglich, nur virtuell, kann nicht\n              abgeschnitten von der Klasse, Roboter          an Lernspielen teilnehmen\n              steckt niemanden an\n          4   Zeitersparnis, unangenehme Arbeiten            mehr Stromverbrauch (Roboter verbraucht\n              übernimmt der Roboter, Hilfe für nicht mehr    Strom), kranke und alte Menschen mit so\n              mobile Menschen                                einem Roboter werden noch stärker isoliert","fields":[{"label":"1","answers":["Qualität wird besser, bestimmte Dinge Robotern fehlt Empathie, Einfühlungs- gehen schneller, eintönige Jobs vermögen, Verhandlungsgeschick, mehr verschwinden Arbeitslose, überflüssige Menschen, alles automatisiert, es darf nichts Unvorher- gesehenes passieren"]},{"label":"2","answers":["Roboter zuverlässiger als Menschen, kein Spaß mehr, keine eigene weniger Unfälle, weniger Stress auf der Entscheidung mehr Straße, man kann die Zeit für etwas anderes nutzen"]},{"label":"3","answers":["Hilfe für kranke Kinder, verlieren durch die keine persönliche/körperliche/echte Krankheit keine Zeit, fühlen sich nicht Interaktion möglich, nur virtuell, kann nicht abgeschnitten von der Klasse, Roboter an Lernspielen teilnehmen steckt niemanden an"]},{"label":"4","answers":["Zeitersparnis, unangenehme Arbeiten mehr Stromverbrauch (Roboter verbraucht übernimmt der Roboter, Hilfe für nicht mehr Strom), kranke und alte Menschen mit so mobile Menschen einem Roboter werden noch stärker isoliert"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-256","solutionId":"b2-sol-256","chapter":10,"module":"Modul 1 · Roboterwelt","moduleIndex":1,"label":"A3A","title":"Roboterwelt","page":158,"kind":"fill","tags":["Practice","Grammar"],"modelAnswer":"Partizip I: 1., 3.\n          Partizip II: 2, 4.\n          Regel: Adjektive, Adjektivendung","fields":[{"label":"3","answers":["Partizip II:"]},{"label":"4","answers":["Regel: Adjektive, Adjektivendung"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-257","solutionId":"b2-sol-257","chapter":10,"module":"Modul 1 · Roboterwelt","moduleIndex":1,"label":"A3B","title":"Roboterwelt","page":158,"kind":"fill","tags":["Practice","Vocabulary"],"modelAnswer":"2. …, der selbstständig denkt und arbeitet, …; 4. …, die von Robotern unterstützt werden, …;\n          6. …, die gestern eröffnet worden ist, …","fields":[{"label":"2","answers":["…, der selbstständig denkt und arbeitet, …"]},{"label":"4","answers":["…, die von Robotern unterstützt werden, …"]},{"label":"6","answers":["…, die gestern eröffnet worden ist, …"]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-258","solutionId":"b2-sol-258","chapter":10,"module":"Modul 1 · Roboterwelt","moduleIndex":1,"label":"A3C","title":"Roboterwelt","page":158,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"1. Emotionen zeigende Roboter faszinieren viele Menschen.\n          2. Ein lange geplantes Roboter-Auto soll bald auf den Markt kommen.\n          3. Von Robotern gebaute Geräte haben oft weniger Defekte.\n          4. Forscher wollen eigenständig denkende Roboter entwickeln.","fields":[{"label":"1","answers":["Emotionen zeigende Roboter faszinieren viele Menschen."]},{"label":"2","answers":["Ein lange geplantes Roboter-Auto soll bald auf den Markt kommen."]},{"label":"3","answers":["Von Robotern gebaute Geräte haben oft weniger Defekte."]},{"label":"4","answers":["Forscher wollen eigenständig denkende Roboter entwickeln."]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-259","solutionId":"b2-sol-259","chapter":10,"module":"Modul 1 · Roboterwelt","moduleIndex":1,"label":"A3D","title":"Roboterwelt","page":158,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Beispiele:\n          2. ein von Robotern gebautes Auto – ein neues von Robotern gebautes Auto\n          3. das auf der Messe präsentierte Modell – das heute auf der Messe präsentierte Modell\n          4. ein Fußball spielender Roboter – ein mit Kindern Fußball spielender Roboter","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-260","solutionId":"b2-sol-260","chapter":10,"module":"Modul 2 · Dr. Ich","moduleIndex":2,"label":"A1A","title":"Dr. Ich","page":159,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Lösung:\n       A (das Pulsmessgerät): den Puls nehmen/messen, etwas analysieren, eine Diagnose stellen,\n       Blutdruck kontrollieren, etwas diagnostizieren, steigenden/sinkenden Puls anzeigen, Werte\n       anzeigen\n       B (das Fieberthermometer): Körpertemperatur/Fieber anzeigen, eine Diagnose stellen, etwas\n       diagnostizieren, Werte anzeigen\n       C (die Personenwaage): wiegen, Werte anzeigen, Gewicht anzeigen","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-261","solutionId":"b2-sol-261","chapter":10,"module":"Modul 2 · Dr. Ich","moduleIndex":2,"label":"A1B","title":"Dr. Ich","page":159,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mit Dr. Ich sind die Patienten selbst gemeint, die mithilfe moderner Technik Untersuchungen\n       selber durchführen können und damit einen Teil der bisherigen Arbeit von Ärzten\n       selbstständig übernehmen können.","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-262","solutionId":"b2-sol-262","chapter":10,"module":"Modul 2 · Dr. Ich","moduleIndex":2,"label":"A2A","title":"Dr. Ich","page":159,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"Mögliche Notizen:\n       Teil 1: Gerät „Scanadu Scout“, klein wie ein Eishockey-Puck, bündelt Technik eines\n       Krankenhauses und Wissen von Ärzten, analysiert Körperdaten, stellt Diagnose, schickt Daten\n       an Smartphone, existiert noch nicht, gibt es „bald“\n       Teil 2: „Telemedizin“, soll Lösung für Problem des Ärztemangels sein: Patienten untersuchen\n       sich selbst, senden ihre Werte an ein Institut, dort reagieren Ärzte sofort, Kritik durch die\n       bisherigen Hausärzte, wird von den Krankenkassen nicht bezahlt, gibt es „in drei bis fünf\n       Jahren“\n       Teil 3: „mHealth“ = mobile Gesundheitsgeräte, z. B. Kontaktlinsen, die den Blutzucker messen\n       oder einpflanzbarer Chip zur Überwachung der Gesundheit, Arzt meldet sich beim Patienten\n       und nicht umgekehrt, schon jetzt große Nachfrage, gibt es „in fünf bis zehn Jahren“","fields":[{"label":"1","answers":[": Gerät „Scanadu Scout“, klein wie ein Eishockey-Puck, bündelt Technik eines Krankenhauses und Wissen von Ärzten, analysiert Körperdaten, stellt Diagnose, schickt Daten an Smartphone, existiert noch nicht, gibt es „bald“ Teil"]},{"label":"2","answers":[": „Telemedizin“, soll Lösung für Problem des Ärztemangels sein: Patienten untersuchen sich selbst, senden ihre Werte an ein Institut, dort reagieren Ärzte sofort, Kritik durch die bisherigen Hausärzte, wird von den Krankenkassen nicht bezahlt, gibt es „in drei bis fünf Jahren“ Teil"]},{"label":"3","answers":[": „mHealth“ = mobile Gesundheitsgeräte, z. B. Kontaktlinsen, die den Blutzucker messen oder einpflanzbarer Chip zur Überwachung der Gesundheit, Arzt meldet sich beim Patienten und nicht umgekehrt, schon jetzt große Nachfrage, gibt es „in fünf bis zehn Jahren“"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-263","solutionId":"b2-sol-263","chapter":10,"module":"Modul 2 · Dr. Ich","moduleIndex":2,"label":"A3","title":"Dr. Ich","page":160,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Mögliche Argumente:\n       Vorteile: wir müssen weniger zum Arzt gehen – sind besser informiert – Verknüpfung von\n       Daten – weniger Zeitverlust – mehr Prävention\n       Nachteile: weniger persönlicher Kontakt – transparent / gläserner Patient / möglicher\n       Datenmissbrauch – wir werden eher zu Hypochondern – zu viel Kontrolle","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-264","solutionId":"b2-sol-264","chapter":10,"module":"Modul 3 · Berufe der Zukunft","moduleIndex":3,"label":"A1A","title":"Berufe der Zukunft","page":161,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":"Mögliche Ideen:\n       Berufe, die es noch nicht gab: Mechatroniker, Coach, Social Media Manager, Weintechnologe,\n       Mediengestalter\n       Bereiche für neue Berufe: Informatik, Medizin, Bauwesen","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-265","solutionId":"b2-sol-265","chapter":10,"module":"Modul 3 · Berufe der Zukunft","moduleIndex":3,"label":"A1B","title":"Berufe der Zukunft","page":161,"kind":"fill","tags":["Practice"],"modelAnswer":"Berufswahl","fields":[{"label":"Answer","answers":["Berufswahl"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-266","solutionId":"b2-sol-266","chapter":10,"module":"Modul 3 · Berufe der Zukunft","moduleIndex":3,"label":"A1C","title":"Berufe der Zukunft","page":161,"kind":"fill","tags":["Practice"],"modelAnswer":"a –a – t","fields":[{"label":"Answer","answers":["a –a – t"]}],"film":false,"y0":0,"y1":760},{"id":"b2-ex-267","solutionId":"b2-sol-267","chapter":10,"module":"Modul 3 · Berufe der Zukunft","moduleIndex":3,"label":"A1D","title":"Berufe der Zukunft","page":161,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Beispiele:\n       1. …, hat mein Freund einen modernen Beruf gelernt. (a) / … musste ich viel lernen. (t)\n       2. …, trinke ich viel Kaffee. (t) / … verdienst du seit Monaten keinen Pfennig. (a)\n       3. …, gehe ich lieber ins Kino (a) / …, gehen sie nicht aus dem Haus (t).","fields":[],"film":false,"y0":0,"y1":760},{"id":"b2-ex-268","solutionId":"b2-sol-268","chapter":10,"module":"Modul 3 · Berufe der Zukunft","moduleIndex":3,"label":"A2A","title":"Berufe der Zukunft","page":161,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1b, 2b, 3a, 4a","fields":[{"label":"1","answers":["B"]},{"label":"2","answers":["B"]},{"label":"3","answers":["A"]},{"label":"4","answers":["A"]}],"film":false,"y0":430,"y1":1403,"options":["A","B","C"]},{"id":"b2-ex-269","solutionId":"b2-sol-269","chapter":10,"module":"Modul 3 · Berufe der Zukunft","moduleIndex":3,"label":"A2B","title":"Berufe der Zukunft","page":161,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Internet-Scout                       Wissensmanager                Location-Scout\n       weltweite Suche nach                 arbeitet innerhalb einer      Suche und Finden von Orten\n       Informationen; Recherche von         Firma mit dem Ziel, dass      für Veranstaltungen oder\n       Infos für Kunden; einfache           Mitarbeiter untereinander     Filmaufnahmen nach\n       Aufbereitung der Ergebnisse für      ihr Wissen kommunizieren;     bestimmten Vorgaben;\n       die Präsentation; Arbeitsfelder:     Sensibilisierung für          organisieren alles, was\n       Informationsbeschaffungsfirmen,      Bedeutung des Wissens;        dazugehört: Genehmi-\n       Dokumentationszentren,               organisiert Mitarbeiter-      gungen, Anmietung,\n       Nachrichtenagenturen,                tagungen; Koordination von    Absprachen etc.; Doku-\n       Marketingagenturen                   gemeinsamen Mittags-          mentation der Infrastruktur\n                                            pausen von Mitarbeitern       (Anfahrt? Parkmöglich-\n                                            aus verschiedenen             keiten? Wasser/Strom etc.?);\n                                            Bereichen für den             Budgetverwaltung; gibt noch\n                                            Austausch                     keine Ausbildung dafür","fields":[],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-270","solutionId":"b2-sol-270","chapter":10,"module":"Modul 3 · Berufe der Zukunft","moduleIndex":3,"label":"A2C","title":"Berufe der Zukunft","page":161,"kind":"fill","tags":["Practice"],"modelAnswer":"1–2–3–7–8–9","fields":[{"label":"Answer","answers":["1–2–3–7–8–9"]}],"film":false,"y0":430,"y1":1403},{"id":"b2-ex-271","solutionId":"b2-sol-271","chapter":10,"module":"Modul 3 · Berufe der Zukunft","moduleIndex":3,"label":"A3A","title":"Berufe der Zukunft","page":162,"kind":"open","tags":["Practice","Vocabulary","Writing"],"modelAnswer":"Zeit                     Ort                     Grund/Folge             Gegengrund\n       innerhalb                außerhalb               dank, aufgrund,         trotz\n       während                  innerhalb               wegen; infolge","fields":[],"film":false,"y0":0,"y1":650},{"id":"b2-ex-272","solutionId":"b2-sol-272","chapter":10,"module":"Modul 3 · Berufe der Zukunft","moduleIndex":3,"label":"A3B","title":"Berufe der Zukunft","page":162,"kind":"fill","tags":["Practice","Reading"],"modelAnswer":"2. Wegen des netten Chefs hat er Spaß an der Arbeit.\n       3. Dank einer guten Ausbildung habe ich problemlos einen Job gefunden.\n       4. Infolge der großen Belastung / Infolge großer Belastung werden viele Mitarbeiter krank.\n       5. Innerhalb der letzten Jahre sind neue Berufe entstanden.","fields":[{"label":"2","answers":["Wegen des netten Chefs hat er Spaß an der Arbeit."]},{"label":"3","answers":["Dank einer guten Ausbildung habe ich problemlos einen Job gefunden."]},{"label":"4","answers":["Infolge der großen Belastung / Infolge großer Belastung werden viele Mitarbeiter krank."]},{"label":"5","answers":["Innerhalb der letzten Jahre sind neue Berufe entstanden."]}],"film":false,"y0":0,"y1":650},{"id":"b2-ex-273","solutionId":"b2-sol-273","chapter":10,"module":"Modul 4 · Meine Zukunft – deine Zukunft","moduleIndex":4,"label":"A1A","title":"Meine Zukunft – deine Zukunft","page":163,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1f, 2g, 3b, 4e, 5d, 6a, 7c","fields":[{"label":"1","answers":["F"]},{"label":"2","answers":["G"]},{"label":"3","answers":["B"]},{"label":"4","answers":["E"]},{"label":"5","answers":["D"]},{"label":"6","answers":["A"]},{"label":"7","answers":["C"]}],"film":false,"y0":0,"y1":760,"options":["A","B","C","D","E","F","G"]},{"id":"b2-ex-274","solutionId":"b2-sol-274","chapter":10,"module":"Modul 4 · Meine Zukunft – deine Zukunft","moduleIndex":4,"label":"A2A","title":"Meine Zukunft – deine Zukunft","page":163,"kind":"choice","tags":["Practice","Reading"],"modelAnswer":"1B, 2D, 3A, 4C","fields":[{"label":"1","answers":["B"]},{"label":"2","answers":["D"]},{"label":"3","answers":["A"]},{"label":"4","answers":["C"]}],"film":false,"y0":430,"y1":1403,"options":["A","B","C","D"]},{"id":"b2-ex-275","solutionId":"b2-sol-275","chapter":10,"module":"Modul 4 · Meine Zukunft – deine Zukunft","moduleIndex":4,"label":"A4A","title":"Meine Zukunft – deine Zukunft","page":164,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"Themen: Lernen/Bildung – Arbeitsalltag/Arbeitsverhältnisse – Verkehrsmittel – Wohnen –\n       Einkaufen/Geschäfte","fields":[],"film":false,"y0":320,"y1":980},{"id":"b2-ex-276","solutionId":"b2-sol-276","chapter":10,"module":"Modul 4 · Meine Zukunft – deine Zukunft","moduleIndex":4,"label":"A5A","title":"Meine Zukunft – deine Zukunft","page":164,"kind":"open","tags":["Practice","Reading","Writing"],"modelAnswer":"Erwartungen: man lernt viele neue Berufe und Produkte kennen; man hat danach bessere\n       Zukunftschancen durch Informationsvorsprung; man erzählt viele Informationen; angenehmes\n       Umfeld durch schönes Hotel\n       Enttäuschungen: zu teuer für das, was geboten wird; nicht so viele Aussteller; alles „alte“\n       Berufe; keine guten Informationen; Hotel ungemütlich; zu weiter Weg zur Messe; Frühstück\n       nicht gut; Snack am Abend zu klein; Zutritt doch nicht allen Veranstaltungen möglich;\n       langweilige Veranstaltungen","fields":[],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-277","solutionId":"b2-sol-277","chapter":10,"module":"Modul 4 · Meine Zukunft – deine Zukunft","moduleIndex":4,"label":"A5B","title":"Meine Zukunft – deine Zukunft","page":164,"kind":"open","tags":["Practice","Writing"],"modelAnswer":"Erwartungen beschreiben – Probleme schildern – eine Forderung stellen\n\nFilm Vogelflug","fields":[],"film":false,"y0":610,"y1":1320},{"id":"b2-ex-278","solutionId":"b2-sol-278","chapter":10,"module":"Film · Vogelflug","moduleIndex":4,"label":"A2A","title":"Vogelflug","page":169,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Kraniche fliegen im Herbst (Oktober/November) in den Süden (z. B. nach Spanien oder\n       Frankreich), weil es dort wärmer ist, und im Frühling (Februar/März) wieder in den Norden\n       (Skandinavien, Polen, Baltikum, Russland; manche bleiben dann auch in Deutschland), um\n       dort zu brüten.","fields":[],"film":true,"y0":430,"y1":1403},{"id":"b2-ex-279","solutionId":"b2-sol-279","chapter":10,"module":"Film · Vogelflug","moduleIndex":4,"label":"A2B","title":"Vogelflug","page":169,"kind":"choice","tags":["Practice","Reading","Listening"],"modelAnswer":"1g, 2e, 3f, 4c, 5a, 6b, 7d","fields":[{"label":"1","answers":["G"]},{"label":"2","answers":["E"]},{"label":"3","answers":["F"]},{"label":"4","answers":["C"]},{"label":"5","answers":["A"]},{"label":"6","answers":["B"]},{"label":"7","answers":["D"]}],"film":true,"y0":430,"y1":1403,"options":["A","B","C","D","E","F","G"]},{"id":"b2-ex-280","solutionId":"b2-sol-280","chapter":10,"module":"Film · Vogelflug","moduleIndex":4,"label":"A3","title":"Vogelflug","page":170,"kind":"fill","tags":["Practice","Reading","Listening"],"modelAnswer":"1. Forscher zählen Vögel (Kraniche), wollen herausfinden, ob sich das Zugverhalten verändert\n      2. milde Winter, Wetter wärmer → Brutpaare kommen eher zurück und können eher mit Brut\n      beginnen\n      3. Hinweis auf Klimawandel, Anpassung der Vögel an die veränderten Klimabedingungen","fields":[{"label":"1","answers":["Forscher zählen Vögel (Kraniche), wollen herausfinden, ob sich das Zugverhalten verändert"]},{"label":"2","answers":["milde Winter, Wetter wärmer → Brutpaare kommen eher zurück und können eher mit Brut beginnen"]},{"label":"3","answers":["Hinweis auf Klimawandel, Anpassung der Vögel an die veränderten Klimabedingungen"]}],"film":true,"y0":0,"y1":650},{"id":"b2-ex-281","solutionId":"b2-sol-281","chapter":10,"module":"Film · Vogelflug","moduleIndex":4,"label":"A4","title":"Vogelflug","page":170,"kind":"fill","tags":["Practice","Reading","Listening"],"modelAnswer":"Vögel, die eigentlich im Mittelmeerraum heimisch sind, kommen nach Deutschland (Beispiel\n      Bienenfresser); vom Bienenfresser gibt es nun schon ca. 500 Paare, die in Deutschland\n      brüten; evtl. in 50 Jahren Flamingos und Papageienarten in Deutschland; diese Spekulation ist\n      in greifbare Nähe gerückt","fields":[{"label":"50","answers":["0 Paare, die in Deutschland brüten; evtl. in"]},{"label":"50","answers":["Jahren Flamingos und Papageienarten in Deutschland; diese Spekulation ist in greifbare Nähe gerückt"]}],"film":true,"y0":320,"y1":980},{"id":"b2-ex-282","solutionId":"b2-sol-282","chapter":10,"module":"Film · Vogelflug","moduleIndex":4,"label":"A5","title":"Vogelflug","page":170,"kind":"fill","tags":["Practice","Reading","Listening"],"modelAnswer":"1. Forscher zählen jedes Jahr viele Zugvögel.\n      2. Wenn ein Vogel zum ersten Mal gefangen wird, bekommt er einen Ring mit einer Nummer.\n      3. Wenn der Vogel später wieder gefunden wird, ist der Ring wie ein Ausweis.\n      4. So erfahren die Forscher, wohin die Vögel geflogen sind.\n      5. Vögel werden seit vielen Jahren beobachtet, deshalb sind sie gute Indikatoren für die\n      Klimaveränderung.","fields":[{"label":"1","answers":["Forscher zählen jedes Jahr viele Zugvögel."]},{"label":"2","answers":["Wenn ein Vogel zum ersten Mal gefangen wird, bekommt er einen Ring mit einer Nummer."]},{"label":"3","answers":["Wenn der Vogel später wieder gefunden wird, ist der Ring wie ein Ausweis."]},{"label":"4","answers":["So erfahren die Forscher, wohin die Vögel geflogen sind."]},{"label":"5","answers":["Vögel werden seit vielen Jahren beobachtet, deshalb sind sie gute Indikatoren für die Klimaveränderung."]}],"film":true,"y0":610,"y1":1320},{"id":"b2-ex-283","solutionId":"b2-sol-283","chapter":10,"module":"Film · Vogelflug","moduleIndex":4,"label":"A6A","title":"Vogelflug","page":170,"kind":"open","tags":["Practice","Reading","Writing","Listening"],"modelAnswer":"Beispiele:\n      Ozonloch, Pole schmelzen, zu viel Energieverbrauch, Treibhausgase, CO2 aus Fabriken,\n      globale Erwärmung, Abholzung von Wäldern und deren Umwandlung in Nutzflächen trägt zur\n      Erwärmung bei, zu hoher Fleischkonsum, z. B. Rinderzucht: sehr viel Methan wird produziert\n      (Verdauungsgase der Tiere), Meeresspiegelanstieg, Wetterextreme, Schäden am Ökosystem","fields":[],"film":true,"y0":0,"y1":900}]};
